window.HB_TR["john"]["ks"]=["1. ابتداہس منز اوس کلام تہٕ کلام اوس خدایس سٍتـ̡ تہٕ کلام اوس خدایہ۔\n2. یۅہے اوس خدایس سٍتـ̡ شروعاتس منز۔\n3.\\tسٲری چیز ٲسۍ تمۍ سٕندِ دٔسۍ بناونہٕ آمٕتۍ۔ تہٕ أمِس بغٲر اوس نہٕ کانٛہہ چیٖز بناونہٕ آمُت۔\n4. تس منز ٲس زندگی۔ تہٕ زندگی ٲس انسانن ہُند گاش۔\n5. تہٕ گاش چُھ انہِ گٹہِ منز چمکان۔ تہٕ انہِ گٹہِ اوس نہٕ سمجُن۔{سمجُن: یا، کٔر نہٕ قبول، یا، وصول کٔر}\n6.\\tخدایہِ سٕندِ طرفہٕ اوس اکھ انسان سوزنہٕ آمُت، یٔمۍ سُند ناو یوحنا اوس۔\n7.\\tیۅہے سپُد گواہ سٍتـ̡ گاہ دِنہٕ خٲطرٕ، یُتھ سارِنٕے انسان یێمہِ سٍتـ̡ پژھ کٔرِتھ۔\n8. سُہ اوس نہٕ سُہ گاش، مگر {اوسُکھ سوزنہٕ آمُت} امہِ گاشچ گواہی دِنہٕ خٲطرٕ۔\n9.\\t{یہ} اوس پوٚز گاش، یُس پریتھ انسانس گاش کران چھہ یُس دنیاہس منز یِوان چھُ۔\n10.\\tسُہ اوس دنیاہس منز، تہٕ یہ دنیا اوس تٔمۍ سٕندِ دٔسۍ بنیومُت، تہٕ دنیا اوس نہٕ تس زانان۔\n11.\\tسُہ آو پانس نِش، تہٕ تٔمۍ سٕندِس پانس نِش آو نہٕ۔\n12.\\tمگر ییژاہ یوتاہ أمس رٔٹۍ، تِمن دِژ خدایہ سٕندِ فرزند بننُک طاقت، {حتیٰ کہ} تِمن ہٕندِس ناوس پیٹھ یقین تھاون وٲلِس خٲطرٕ: {طاقت: یا، حق، یا، مراعت}\n13. یُس نہٕ خونہٕ سٍتـ̡ پٲدٕ گٔیہِ، نہ مازٕ سٕنزِ مرضی سٍتـ̡ تہٕ نہ انسان سٕنزِ مرضی سٍتـ̡ بلکہ خدایہِ سٕندِ مرضی سٍتـ̡ پٲدٕ سپدان چُھ۔\n14. تہٕ کلام آو ماز بناونہٕ، تہٕ اسہِ مَنٛز بٔرِتھ روزُن، (تہٕ أسۍ وُچھ تٔمۍ سُند جلال ، یُس مٲلہِ سٕندِ کُنی پیدٕ سُند جلال اوس،) فضل تہٕ سچائی سٍتـ̡ بٔرِتھ۔\n15.\\tیوحنا کٔر أمِس گوٲہی تہٕ وَنُن زِ یہِ اوس سُہ یٔمِس مُتلق میہ کتھ کٔرمٕژ، یُس میانہِ پتہٕ یُس یُس میانہِ برونہہ کُن یِوان چھُ، سُہ اوس میانہِ برونہہ کُن۔\n16. تہٕ تٔمۍ سٕنزِ مکمل سٍتـ̡ چُھہ اسہِ سٍتـ̡ س�\n17. شریعت ٲس موسیٰ سٕندِ دٔسۍ دِژمٕژ، {مگر}فضل تہٕ سچائی آیہ عیسیٰ مسیح سٕندِ دٔسۍ دِنہٕ۔\n18.\\tکٲنسہ تہِ انسانس چھہ نہ خدایہ وچھمُت۔ وٲحِد نیٚچُو، یُس مٲلہِ سٕندِس سینس مَنٛز چُھ، تٔمۍ چُھ اعلان کورمُت۔\n19. تہٕ یہِ چُھ یوحنا سُند ریکارڈ ییلہ یہودیو یروشلم پیٹھٕ پادٕرۍ تہٕ لاوی سوزمٕتۍ زِ تُہۍ کُس چُھہ؟\n20. تہٕ تٔمۍ کوٚر اقرار تہٕ کوٚرُن نہٕ انکار۔ مگر کوٚرُن اقرار زِ بہٕ چُھس نہٕ مسیح۔\n21.\\tتہٕ تِمو پرژھ أمِس کیا پتہٕ؟ کیا تُہۍ چھُکھ الیاس؟ تہٕ سُہ چُھس ونان زِ بہٕ چُھس نہٕ۔ کیا ژٕ چھکھ سُہ پیغمبر؟ تہٕ تٔمۍ دیُت جواب، نہٕ۔ {سُہ پیغمبر: یا پیغمبر؟}\n22. تَمہِ پتہٕ ووٚن تِمو أمِس زِ تُہۍ کُس چھُو؟ تاکہ أسۍ ہیکو تمن جواب دِتھ یمو اسہِ سوزمُت۔ ژیہ کیا چُھکھ پننِس بارس منز ونان؟\n23.\\tتٔمۍ وۆن، بہٕ چُھس بیابانس مَنٛز فریاد دِنہٕ وٲلِس سٕنز آواز، یِتھ کٔنۍ پیغمبر عیسیٰ سُند وَتھ بناوُن۔\n24. تہٕ یِم سوزنہٕ آمٕتۍ ٲسۍ، تِم ٲسۍ فریسیَن ہٕندِس سٍتـ̡ ۔\n25.\\tتہٕ تِمو پرژھ أمِس تہٕ وونُن زِ تیلہِ کیازِ چُھکھ بپتسمہ دِوان، یێلہِ نہٕ تُہۍ سُہ مسیح تہٕ الیاس تہٕ سُہ پیغمبر چھُو؟\n26.\\tیوحنا دیُت تِمن جواب دِتھ زِ بہٕ چُھس آبہٕ سٍتـ̡ بپتسمہ دِوان، مگر یێمہِ سٍتـ̡ چُھہ یُس نہٕ تۅہہِ پتاہ چُھہ ۔\n27. سُہ چُھ، یُس میانہِ پَتہٕ یِنہٕ وول چُھس میانہِ برونہہ کُن ترجیح دِنہٕ آمُت، یٔمۍ سٕندِس کھورِ ہُند لوٚٹ بہٕ چھُس نہٕ یلہٕ تراونس لایق۔\n28.\\tیِم کامہِ آیہ اردن نیبر بیتھابارس مَنٛز کرنہٕ، ییتہِ یوحنا بپتسمہ اوس دِوان۔\n29.\\tدۆیمہِ دۅہہ یوحنا چُھ عیسیٰ مسیح پانس نِش یِوان وُچھان، تہٕ وُچھِو خدایہِ سُند کۅکر، یُس دنیاہُک گۅناہ دور کران چُھ۔ {نِش نِن: یا، بیئر}\n30.\\tیہ چھہ سہ یمۍ سندِ بارس منز میہ وونمُت چھُ، میانہِ پتہٕ چھہ اکھ انسان یوان یُس میانہِ برونہہ ترجیح دِنہٕ یوان چھُ، تکیازِ سُہ اوس میہ برونہہ کُن۔\n31. تہٕ بہٕ اوس نہٕ تس زانان: مگر سُہ گژھہِ اسرٲیلِس برونہہ کُن ظٲہر کرنہٕ یُن، تێمہِ مۅکھہ چُھس بہٕ آبہٕ سٍتـ̡ بپتسمہ دِنہٕ آمُت۔\n32. تہٕ یوحنا ووٚن زِ مے وُچھ روح آسمانہٕ پیٹھٕ کۅترِ ہٕندۍ پٲٹھۍ، تہٕ سُہ اوس أمِس پیٹھ روزان۔\n33.\\tتہٕ بہٕ اوس نہٕ تس زانان، مگر یُس میہ آبہٕ سٍتـ̡ بپتسمہ دِنہٕ خٲطرٕ سوزمُت، یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ روح القدس سٍتـ̡ بپتسمہ دِوان چُھ، سُہ چُھہ یُس روح القدس سٍتـ̡ بپتسمہ دِوان چُھ۔\n34. تہٕ مے وُچھ تہٕ وُچھ زِ یہِ چُھ خدایہ سُند نیٚچُو۔\n35.\\tدۆیمہِ دۅہہ یوحنا تہٕ تٔمۍ سٕندِ زٕ شٲگِرۍ۔\n36.\\tتہٕ حضرت عیسیٰ علیہ السلام وُچھِتھ وُچھِتھ چُھہ ونان، خدایہ سُند کۅکرٕ وُچھِو!\n37.\\tتہٕ دۅیو شاگردو بوز أمِس کتھ تہٕ تِمو کٔر عیسیٰ سٕندِس پٲٹھۍ۔\n38.\\tتێلہِ آو عیسیٰ علیہ السلام پھیُر، تہٕ وُچھُن تِمن پَتہٕ پَتہٕ تہٕ وُچھُن تِمن کیا یژھان؟ تِمو ووٚن أمِس ربی، (یعنی ترجمہٕ کرنہٕ آمُت، مالک،) تہٕ کتہِ چھُکھ روزان؟ {رہائش: یا، ابیڈیسٹ}\n39. سُہ چُھ تِمن ونان زِ یِمو تہٕ وُچھِو۔ تِم آیہِ تہٕ وُچھکھ سُہ کتہِ روزان تہٕ تمہِ دۅہہ روٗدۍ أمِس سٍتۍ روزان: تکیازِ یہ اوس دٔہِمہِ بجہ ۔ {متعلق...: یہ اوس رٲژ برونہہ زٕ گھنٹہٕ}\n40. یِمو دۄیو منزٕ اکھ یُس یوحنا بوزان اوس تہٕ أمِس پَتہٕ پٲٹھۍ، اوس شمعون پطرس سُند بوے اینڈریو۔\n41.\\tسُہ چُھ گۅڈٕ پنُن بوے شمعون لبان تہٕ أمِس ونان زِ اسہِ لوٚب مسیح یُس مسیح سُند ترجمہٕ چُھ کرنہٕ آمُت۔ {مسیح: یا، مسح شدٕ}\n42. تہٕ سُہ اوٚن عیسیٰ مسیحس نِش۔ تہٕ یێلہِ عیسیٰ مسیحن وُچھ، تٔمۍ ووٚن، تہٕ تُہۍ چُھکھ شمعون یُس یوناہ سُند نیچو چُھ، تہٕ ژے یِن سیفاس وننہٕ یُن، یُس تشریح مطٲبق اکھ کُن چُھ۔\n43. یێمہِ دۅہہ گژھہِ عیسیٰ علیہ السلام گلیل مَنٛز نیرِ، تہٕ فلپس لٔبِتھ تہٕ أمِس وَنُن زِ میانہِ پٲٹھۍ۔\n44.\\tوُنہِ اوس فلپ بیتھسیداہُک، یُس اینڈریو تہٕ پطرس سُند شہر اوس۔\n45. فلپس چُھ نتھانیل لبان تہٕ أمِس وَنُن زِ اسہِ لوٚب سُہ یُس شریعت مَنٛز موسیٰ تہٕ پیغمبرن لیوکھمُت چُھ، حضرت عیسیٰ سُند ناصرت، یُس یوسف سُند نیچو۔\n46.\\tتہٕ نتھانیلن ووٚن أمِس زِ کیا ناصریتس منز ہیکہٕ کانہہ اصل چیز نیرِتھ؟ فلپ چُھ أمِس وَنان۔\n47.\\tحضرت عیسیٰ علیہ السلام وُچھ نتھانیلس پانس نِش یِوان، تہٕ وُچھِو پٔزۍ پٲٹھـ̡ اکھ اسرٲیل، یٔمِس مَنٛز چُھنہٕ کانہہ فریب دِنہٕ۔\n48.\\tنتھانیل چُھ أمِس ونان زِ ژے کتہِ چُھکھ میہ زانان؟ عیسیٰ مسیحن دیُت جواب تہٕ وونُن تٔمِس زِ امہِ برونہہ زِ فلپس ژے بُلاونہٕ آمُت، ییلہ تہٕ ژٕ انجیر کُلِس تل ٲس، مے وُچھ ژے ۔\n49.\\tنتھانیلن دیت جواب تہ وونُن ربی، تہٕ چُھکھ خدا سُند نیٚچُو۔ تہٕ چُھکھ اسرٲیلُک بادشاہ۔\n50.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، کیازِ میہ ووٚن ژے انجیر کُلِس تَل وُچھمُت، کیا ژے چھُکھ یقین کٔرِتھ؟ ژے وُچھِو یِمو کھۅتہٕ بٔڈۍ چیز وُچھان۔\n51. تہٕ سُہ چُھس ونان زِ پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ پٔزۍ پٲٹھۍ، پٔزۍ پٲٹھۍ، تہٕ خدایہِ سٕندِ فرشتہٕ وُچھِو اِنسان سٕندِس نیٚچِس سٍتـ̡ کھسنہٕ تہٕ وسان ۔","1. تہٕ تریمہِ دۅہہ گۆو گلیل کِس کاناہس مَنٛز خانٛدر۔ تہٕ حضرت عیسیٰ سٕنز موج ٲس تتہِ:\n2. تہٕ عیسیٰ علیہ السلام تہٕ تٔمۍ سٕندِس شٲگِرِد سٍتـ̡ بُلاونہٕ آمُت۔\n3. تہٕ ییلہ تِم شرابُک یژھان اوس، عیسیٰ سٕنز موج چھے أمِس ونان زِ تِمن چُھہ نہٕ شراب۔\n4. عیسیٰ مسیح چُھ أمِس ونان زِ زنانہٕ، مےٚ کیا چُھ ژےٚ سٍتـ̡ وابستہٕ؟ میون وقت آو نہٕ وُنیُک تام۔\n5.\\tتسٕنزِ ماجہ چھے خادمن ونان زِ یہِ یُس تہِ وَنُن چُھ، سُہ کرُن۔\n6. تہٕ یہودین پاک کرنہٕ پتہٕ آیہ کنن ہندۍ شیہ بانہٕ بناونہٕ، یمن منز زٕ تریہ فرکن ٲسۍ۔\n7. عیسیٰ مسیح چُھ تِمن ونان زِ آبہٕ بانہٕ بٔرِو آبہٕ سٍتـ̡ بٔرِتھ۔ تہٕ تِمو بٔرِتھ بٔرۍ۔\n8.\\tتہٕ سُہ چُھ تِمن ونان زِ وُنۍ کٔرِو تہٕ دعوت کِس حاکمس نِش گژھِ۔ تہٕ تِم چھِ نِش {یہ}۔\n9.\\tییلہ دعوتُک حکمران چُھس آبُک مزہ چُھ، تہٕ یہ ٲس نہٕ خبرے زِ یہِ کتہِ چُھہ: (مگر یِمو نوکر آب کھین، تِمن ٲس پتاہ زِ یہِ کتہِ چُھہ۔) دعوتُک حٲلِمن بُلوو مہراز،\n10.\\tتہٕ چُھ أمِس ونان زِ پرٮ۪تھ کانہہ انسان چُھ شروعاتس منز اصل شراب۔ تہٕ ییلہ انسان رژھ کھنڈ چُھ، تیلہ یُس بدتر چُھ: {مگر} ژے تھوو وُنیُک تام اصل شراب۔\n11.\\tمعجزاتن ہٕندِس آغازس سٍتـ̡ کٔر حضرت عیسیٰ علیہ السلام گلیل کِس کاناہس مَنٛز، تہٕ کوٚرُن پَنُن جلال ظٲہر۔ تہٕ تٔمۍ سٕندِس شٲگِرِد گٔیہِ أمِس پٲٹھۍ۔\n12.\\tامہ پتہ گۆو سُہ کفرناؤم، سُہ تہٕ أمۍ سٕنزِ موج تہٕ تٔمۍ سٕندٮ۪ن بٲے تہٕ تٔمۍ سٕندٮ۪ن شٲگِرِدَن کُن، تہٕ تِم روٗد نہٕ واریاہن دۅہن اتہِ روزان۔\n13. تہٕ یہودین ہُند فسح آو اتھس پیٹھ، تہٕ عیسیٰ ووت یروشلمس کُن،\n14.\\tتہٕ وُچھِتھ مندرس مَنٛز تِم یِم بیل، کۅتر تہٕ کۅتر کٕنَن وٲلۍ، تہٕ پٲنسہٕ بدلاون وٲلۍ:\n15. تہٕ ییلہ تٔمۍ لۄکچہِ رزِ ہُند عذاب، تٔمۍ ژٔلِتھ سارِنٕے مندرٕ منزٕ تہٕ دانٛد تہٕ بیل۔ تہٕ بدلاون والٮ۪ن ہٕندۍ پٲنسہٕ ترٛٲوِتھ تہٕ دِژٕن ٹیبل۔\n16.\\tتہٕ وونُن یِمن کۅتر کٕننہٕ آمٕتۍ، یِم چیز نِش نِیُن۔ میانہِ مٲلہِ سُند گرٕ بناو نہٕ تجارتُک مکانہٕ۔\n17.\\tتہٕ تٔمۍ سٕندٮ۪ن شاگردن یاد اوس زِ یہ اوس لیکھنہٕ آمُت، چانہِ گرٕکۍ جوش چُھس مے کھٮ۪وان۔\n18.\\tپتہٕ دِژ یہودیو جواب تہٕ وونُن أمِس زِ ژے کیا نشانہٕ چُھکھ اسہِ ہاوان، یێلہِ تہٕ ژٕ چُھکھ یِم کٲم کران چھِو؟\n19.\\tحضرت عیسیٰ علیہ السلام دِیُت جواب تہٕ وونُن تِمن زِ یہِ مندر تباہ کرُن، تہٕ ترٮ۪ن دۅہن مَنٛز کٔرٕ بہٕ یہِ تُلنہٕ۔\n20.\\tپتہٕ ووٚن یہودی زِ ژتٲجی تہٕ شییہ ؤری اوسُکھ یہِ مندر تعمیر کٔرِتھ، تہٕ کیا ژے کٔرِو یہ ترٮ۪ن دۅہن منز تعمیر کرنہٕ؟\n21.\\tمگر تٔمۍ کٔر پننہِ جسمہٕ کِس مندرس مُتلق کتھ کرنہٕ۔\n22.\\tتێلہِ ییلہ سُہ مُردٕ منزٕ زندٕ سپُد، تٔمۍ سٕندٮ۪ن شاگردن اوس یاد زِ تٔمۍ اوس تِمن یہ وونمت۔ تہٕ تِمو کٔر صحیفس تہٕ تتھ کلامس پیٹھ یقین یُس عیسیٰ علیہ السلام اوس وونمُت۔\n23. وۅنۍ ییلہ سُہ فسح کِس موقعس پیٹھ یروشلمس مَنٛز اوس، واریاہ لوگ ٲسۍ تٔمۍ سٕندِس ناوس پیٹھ یقین تھاوان، ییلہ تِمو تِم معجزات وُچھمٕتۍ۔\n24.\\tمگر حضرت عیسیٰ علیہ السلام کٔر نہ تِمن سٍتـ̡ پانس سٍتـ̡ وابستہٕ، تکیازِ سُہ اوس سارِنٕے انسانس زانان۔\n25.\\tتہِ چھہ نہ یہ ضروری زِ کٲنسہِ گژھہِ انسانس متعلق گواہی دِنۍ، تکیازِ تس ٲس زانان زِ انسانس منز کیا چھہ آسان۔","1. فریسیَن ہُند اَکھ شخٕص اوس یُس نِکوڈیمس ناو اوس، یُس یہودین ہُند حُکُمران اوس۔\n2. یۅہے آو رٲژ عیسیٰ ہس نِش تہٕ وونُن ربی، اسہِ چھیہ پتاہ زِ تہۍ چُھکھ خدایہ سٕندِ طرفہٕ آمُت استاد، تکیازِ کانہہ تہِ انسان ہیکہِ نہٕ یِم معجزات کٔرِتھ یِم تہٕ تۅہہِ کران چھِو، مگر خدایہ آسہِ أمِس سٍتـ̡ ۔\n3.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان، یوتام نہٕ انسان دُبارٕ پٲدٕ سپدِ، سُہ ہیکہِ نہٕ خدایہِ سٕنز بادشٲہی وُچھِتھ۔ {دوبارٕ: یا، ہیرٕ پیٹھ}\n4. نیکوڈیمس چُھ أمِس ونان زِ بُزرگ آسنہٕ وِزِ انسان کِتھ کٔنۍ ہیکہِ پٲدٕ سپدِتھ؟ کیا سُہ ہیکہٕ دوٚیمہِ لٹہِ پنٛنہِ ماجہِ ہٕنٛدِس رحمس منٛز دٲخل گٔژھتھ، تہٕ زیٚنہٕ یِتھ؟\n5.\\tحضرت عیسیٰ علیہ السلام دیت جواب، پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ یوتام نہٕ انسان آبہٕ سٍتـ̡ تہٕ روح سٍتـ̡ پٲدٕ سپدِ، سُہ ہیکہِ نہٕ خدایہ سٕنزِ بادشٲہی مَنٛز اژِتھ۔\n6. یُس ماز سٍتـ̡ پٲدٕ سپدان چُھ، سُہ چُھ ماز۔ تہٕ یُس روح سٍتـ̡ پٲدٕ سپدان چُھ، سُہ چُھ روح۔\n7. تعجب گژھ نہٕ زِ میہ ووٚن ژے دُبارٕ پٲدٕ گژھُن۔ {دوبارٕ: یا، ہیرٕ پیٹھ}\n8.\\tواو چُھہ ییتہِ واو چُھہ وسان تہٕ توے چُھہ امچ آواز بوزان، مگر یہ کتہِ چُھ یوان تہٕ کتہِ چُھ گژھان: یِتھے پٲٹھۍ چُھ پریتھ کانہہ یُس روحہٕ سٍتـ̡ پٲدٕ سپدان چُھ۔\n9.\\tنیکودیمس دیُت جواب تہٕ وونُن أمِس زِ یِم چیز کِتھہ کٔنۍ ہیکن ٲسِتھ؟\n10.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، کیا تُہۍ چھُکھ اسرٲیلُک مٲلک، تہٕ کیا چُھہ نہٕ یِمن چیزن ہُند پتاہ ؟\n11. پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ أسۍ چھِ کتھ کران زِ أسۍ چھِ زانان تہٕ گوٲہی دِوان زِ أسۍ وُچھمٕتۍ۔ تہٕ تۅہہ چُھہ نہٕ سٲنۍ گواہ قبول۔\n12. اگر میہ ژیہ زمینہِ ہنز کتھ وننہ آسہِ، تہٕ تہۍ چھِو نہٕ یقین کران، تیلہِ کتھہ پاٹھۍ کرو یقین اگر بہٕ ژیہ آسمانی چیزن ہنز کتھ وننہ آسہِ۔\n13. تہٕ کانہہ تہِ انسان چُھ نہٕ آسمانس تام کھسُن، مگر یُس آسمانہٕ پیٹھٕ وسُن اوس، سُہ تہِ چُھ انسان سُند فرزند یُس آسمانس مَنٛز چُھ۔\n14.\\tیُتھ زن موسیٰ سُند نیچو تُلُن بیابانس مَنٛز تُلُن:\n15. یُس تہِ أمِس پیٹھ ایمان تھاوان چُھ، سُہ گژھِ نہٕ ختم گژھُن، بٔلکہِ گژھہِ ابدی زندگی حٲصِل کرنہٕ۔\n16.\\tیێلہِ خدایہ اوس دنیاہس سٍتـ̡ محبت کٔرمٕژ، یێمہِ سٍتـ̡ دِیُت پنُن کُنی نیٚچُو، یُس تہٕ یُس أمِس پیٹھ ایمان تھاوان چُھ، سُہ گژھہِ نہٕ ختم سپدُن، بٔلکہِ گژھہِ ابدی زندگی حٲصِل۔\n17. کیازِ خداین اوس نہٕ پنُن نیچو دنیاہس مَنٛز دُنیاہس مَنٛز دُنیاہس مَنٛز سوٗزمُت۔ مگر یہ زِ تس سٍتۍ گژھہِ دنیا بچاونہ۔\n18. یُس أمِس پیٹھ ایمان تھاوان چُھ، سُہ چُھنہٕ مذمت کرنہٕ آمُت، مگر یُس نہٕ ایمان چُھ تھاوان سُہ چُھہ گوڈٕے مذمت کرنہٕ آمُت، کیازِکہِ سُہ چُھنہٕ خدایہ سٕندِس کُنی فرزند سٕندِس ناوس پیٹھ یقین تھاوان۔\n19.\\tتہٕ یِہ چھُ مذمت زِ گاش چُھ دنیاہس مَنٛز آمُت، تہٕ انسانو اوس گاشہٕ بجایہ تاریک پٲٹھۍ، تِکیازِ تِہٕندِ اعمال ٲسۍ بُرۍ۔\n20. یُس کانہہ بد کار کران چُھہ سُہ چُھ گاشس سٍتـ̡ نفرت کران، تێلہِ چُھ نہٕ گاشس کُن یِوان تہٕ یێلہِ تٔمۍ سٕندِس اعمال سٍتـ̡ ییہ ملامت کرنہٕ۔ {ملامت کرنہٕ: یا، دریافت}\n21. مگر یُس سُہ پزر کران چُھ سُہ چُھ گاشس کُن یِوان، یُتھ تٔمۍ سٕندِ اعمال ظٲہر گژھن تہٕ تِم گژھن خدایہ سٕندِ سٍتـ̡ کرنہٕ۔\n22. یِمو چیزو پَتہٕ آو عیسیٰ مسیح تہٕ تٔمۍ سٕندِ شٲگِرِ یہودایہ کِس سرزمینس مَنٛز۔ تہٕ تتہِ روٗد سُہ تِمن سٍتـ̡ تہٕ بپتسمہ دِنہٕ۔\n23.\\tتہٕ یوحنا تہِ اوس سلیمس نزدیک عینون مَنٛز بپتسمہ دِوان، تکیازِ اتہِ اوس واریاہ آب تہٕ تِم آیہ تہٕ آیہ بپتسمہ دِنہٕ۔\n24. یوحنا اوس نہٕ وُنیُک تام قٲد خانس منٛز تراونہٕ آمُت۔\n25.\\tامہ پتہ گۆو یوحنا سندین شاگردن تہ یہودین درمیان پاکیزگی متعلق سوال۔\n26.\\tتہٕ تِم آیہِ یوحنا نِش تہٕ وونُن ربی، یُس اردن اپارِ ژے سٍتـ̡ اوس، یٔمِس سٍتـ̡ گوٲہی دِوان چُھ، وُچھِو یۅہے بپتسمہ دِوان تہٕ سارِنٕے لُکھ أمِس نِش یِوان۔\n27.\\tیوحنا دیت جواب تہ وونُن زِ انسان ہیکہِ نہ کانہہ تہِ حٲصل کٔرِتھ، مگر یہ گژھہِ اسمانس پیٹھ دِنہٕ۔ {رسیو: یا، پانس نِن}\n28. یێلہِ چُھہ میہ گوٲہی دِوان زِ بہٕ چُھس نہٕ مسیح چُھس، مگر بہٕ چُھس تس برونہہ کُن سوزنہٕ آمُت۔\n29. یُس مہرِنہِ آسہِ سُہ چھُ مہرازٕ سُند یار، یُس کھڑا روزان تہٕ بوزان چُھ، سُہ چُھ مہرازٕ سٕنزِ آوازِ سٍتـ̡ سٮ۪ٹھاہ شاد سپدان: تێمہِ کِنۍ چھے میٲنۍ خوشی پوٗرٕ سپدان۔\n30.\\tتس گژھہِ ہُرراوُن، مگر میہ گژھہِ کم کرُن۔\n31. یُس ہیرِ پیٹھٕ یِوان چُھ، سُہ چُھ سارِنٕے سارِنٕے کھۄتہٕ تھوٚد آسان: یُس زمینہٕ مَنٛز چُھ سُہ چُھہ زمینہٕ سٍتـ̡ کتھ کٔرِتھ، یُس آسمانہٕ پى۪ٹھٕ یِوان چُھ، سُہ چُھ سارِنٕے سارِنٕے کھۄتہٕ زیادٕ آسان۔\n32. تہٕ یُس تٔمۍ وُچھمُت تہٕ بوزمُت چُھ، سُہ چُھ گوٲہی دِوان۔ تہٕ کٲنسہ تہِ انسان چُھ نہٕ تٔمۍ سٕنز گوٲہی حٲصل کران۔\n33.\\tیێمہِ سٕنزِ گوٲہی حٲصل سپٕز سُہ چُھہ پننِس مُہر سٍتـ̡ دِژمُت زِ خدا چُھ پوٚز ۔\n34. یُس خدا سوزمُت چُھ، سُہ چُھ خدایہِ سٕندِ کلامٕچ کتھ کران: کیازِکہِ خدا چُھ نہٕ روٝحہٕ سٍتـ̡ دِوان۔\n35. باپ چُھ نیچوِس سٍتـ̡ محبت کران، تہٕ دِژُن سارِنٕے چیٖز پننِس اتھس مَنٛز۔\n36. یُس یُس نیچوس پیٹھ ایمان تھاوان چُھ، سُہ چُھ نہٕ ابدی زندگی حٲصل کران، تہٕ یُس نہٕ نیچوس پیٹھ ایمان تھاوان چُھ، سُہ گژھہِ نہٕ زندگی وُچھان۔ مگر خدایہ سُند غضب چُھ تس پیٹھ روزان۔","1. یێلہِ خداوند پتاہ زِ کِتھہ کٔنۍ اوس فریسیو بوزمُت زِ حضرت عیسیٰ علیہ السلام کٔر یوحنا سٕندِ کھۅتہٕ زیادٕ شٲگِرِ بنٲوِتھ تہٕ بپتسمہ دِژمُت،\n2. (حالانکہِ حضرت عیسیٰ علیہ السلام اوس نہٕ پانہٕ بپتسمہ دِژمُت، بلکہ تٔمۍ سٕندِس شٲگِرَن ہُند بپتسمہ دِژمُت،)\n3. سُہ دراو یہودایہ، تہٕ دُبارٕ گلیل کُن روانہٕ۔\n4. تہٕ تس گژھہِ سامریاہس مٔنزۍ گژھُن۔\n5. پَتہٕ چُھ سُہ سامریہ کِس أکِس شہرس مَنٛز یُس یعقوب پننِس نیچوِس یوسفس دِژمُت چھُ۔\n6.\\tوۅنۍ اوس یعقوب سُند کۅر اتہِ۔ تَمہِ کِنۍ اوس عیسیٰ مسیح سٕندِس سفرس سٍتـ̡ تھکان گٔژِھتھ بِہتھ کُنہِ\n7.\\tسامریہٕچ اکھ زنانہٕ چھے آب کھیننہٕ خٲطرٕ یوان: عیسیٰ علیہ السلام چُھ أمِس ونان زِ مے دِیُن چنہٕ خٲطرٕ۔\n8.\\t(تکیازِ تٔمۍ سٕندِ شٲگِر گٔیہِ ماز ہینہٕ خٲطرٕ شہرس منز۔)\n9.\\tتێلہِ چھے سامریہٕچ زنانہِ أمِس ونان زِ یہودی آسنہٕ کِنۍ چُھکھ ژے یہودی آسنہٕ کِنۍ میانہِ نِش شراب، یُس سامریہٕچ زنانہٕ چھُ؟ تکیازِ یہودین چھہ نہ سامری سٍتـ̡ کانہہ وابستہٕ۔\n10.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، یێلہِ ژے خدایہِ سُند تحفہٕ زانان چھُ، تہٕ یُس تہٕ کُس چُھہ ژے ونان چُھ، مے دِیُن چنہٕ۔ ژیہ ہا أمِس منگُن، تہٕ سُہ دِہا ژےٚ زندٕ آب دِوان۔\n11.\\tزنانہِ چھے أمِس ونان زِ جناب، ژے چُھہ نہٕ کانہہ تہِ کُنہِ سٍتـ̡ س�\n12. کیا تُہۍ چھوا سٲنِس مٲلہِ یعقوب سٕندِ کھۅتہٕ بٔڈ یٔمۍ اسہِ کۅر دِژ، تہٕ پانس تہٕ پننین شُرٮ۪ن تہٕ چارواین چِھہ؟\n13. حضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن أمِس یُس یَتھ آبہٕ سٍتـ̡ چُھہ سُہ گژھہِ دُبارٕ ترش:\n14. مگر یُس تہِ بہٕ دِنہٕ یُس آب چیٚوان چُھ، سُہ گژھہِ نہٕ زانہہ ترش۔ مگر یُس آب بہٕ تس دِیہِ سُہ آسہِ تس منز آبُک کیور یُس ابدی زندگی منز پھۅلان آسہِ۔\n15.\\tزنانہِ چھے أمِس ونان زِ جناب، مے دِیُن یہِ آب زِ بہٕ چُھس نہٕ پیاس تہٕ نہ یِنہٕ یِنہٕ خٲطرٕ۔\n16. عیسیٰ مسیح چُھ أمِس ونان زِ گژھ پَنُن خانٛدار، تہٕ یور یور گژھ۔\n17.\\tزنانہِ دیت جواب تہ وونُن میہ چھہ نہ کانہہ خانٛدار۔ حضرت عیسیٰ علیہ السلام ووٚن أمِس پٲٹھۍ، ژے چُھس نہٕ کانہہ خانٛدار:\n18.\\tکیازِ ژے چھہِ پانژھ خانٛدار۔ تہٕ یُس وُنۍ تۅہہ چُھس نہٕ تُہند خانٛدار چُھ، تَتھ مَنٛز چُھہ تۅہہ پٔزۍ پٲٹھۍ۔\n19.\\tزنانہِ چھے أمِس ونان جناب، بہٕ چُھس تُہۍ چھِو پیغمبر۔\n20.\\tسانۍ مٲلۍ ٲسۍ اتھ پہاڑس منز عبادت کران۔ تہٕ تُہۍ چھِو ونان زِ یروشلمس مَنٛز چُھ سُہ جاے ییتہِ انسانس عبادت کرٕنۍ۔\n21.\\tعیسیٰ مسیح چُھ أمِس ونان زِ زنانہٕ، میانہِ پٲٹھـ̡ یقین کرُن، سُہ وقت چُھ یێلہِ نہٕ یێتھ بالس مَنٛز، تہٕ نہٕ وُنہِ تہِ یروشلمس مَنٛز، مٲلِس سٕنز عبادت کٔرِو۔\n22. تم چِھ نہٕ پتاہ زِ أسـ̡ کیاہ چِھہ عبادت کران، کیازِ نجات چھے یہودین ہٕنز۔\n23. مگر سُہ وقت چُھ یِوان، تہٕ وُنہِ چُھہ سُہ یێلہِ پٔزۍ پٲٹھـ̡ پٔزۍ عبادت کرن وٲلـ̡ روح تہٕ حقیقتس سٍتـ̡ مٲلِس سٕنز عبادت کرنہٕ خٲطرٕ۔\n24. خدا چُھ اکھ روح: تہٕ یُس أمِس عبادت کران چُھ، تِم پزِ روح تہٕ حقیقتس سٍتـ̡ عبادت کرٕنـ̡ ۔\n25.\\tزنانہِ چھے أمِس ونان زِ مسیح چُھ یِوان، یێمِس مسیح ونان چُھ، یێلہِ سُہ یێلہِ یِیہ، سُہ کرِ اسہِ سارِنٕے چیز۔\n26. عیسیٰ مسیح چُھ أمِس ونان زِ بہٕ چُھس یُس ژےٚ کتھ کران چُھ، سُہ چُھہ {سُہ}۔\n27.\\tتہٕ اَمہ پَتہٕ آو تٔمۍ سٕندِ شٲگِرِد تہٕ حٲران گٔیہِ زِ تٔمۍ کٔر زنانہِ سٍتـ̡ کتھ کرنہٕ، توتہِ اوس نہٕ کٲنسہ مردس ووٚنمُت، ژیہ کیا چُھہ یژھان۔ یا کیازِ چھکھ تس سیتۍ کتھ کران؟\n28.\\tزنانہِ ترٲو پنُن آبہٕ بانہٕ ترٲوِتھ شہرس منز تہٕ وَنُن مردَن وَنُن،\n29.\\tیِہ وُچھِو أکِس شخٕصس سٍتـ̡ یێمہِ سٍتـ̡ یێمہِ سٍتـ̡ میہ سارِنٕے کُنہِ کتھہِ ہُند وَنُن چُھہ: کیا یہِ\n30.\\tتمہِ پتہ گٔیہِ تِم شہرٕ نیبر تہٕ أمِس نِش آیہ۔\n31.\\tاَتھ دوران کٔر تٔمۍ سٕندِس شٲگِرِ سٕندِس دُعا دُعا تہٕ وَنُن زِ آقا، کھٮ۪و۔\n32.\\tمگر تٔمۍ ووٚن تِمَن زِ مےٚ چُھ ماز کھٮ۪نہٕ خٲطرٕ یُس نہٕ ژےٚ پتاہ چھُ۔\n33.\\tتێلہِ وۆن شاگردو اَکھ أکِس سٍتـ̡، کیا کٲنسہِ شخژن چُھہ أمِس کھٮ۪نہٕ خٲطرٕ اوٚنمُت؟\n34. عیسیٰ مسیح چُھ تِمن ونان زِ میون ماز چُھ تٔمِس سٕنز مرضی پورٕ کرٕنـ̡ یُس مے سوزمُت چُھ، تہٕ تٔمۍ سٕنز کٲم مُکمل کرٕنـ̡ ۔\n35.\\tیہ ونو نہ، وُنہِ تہِ چھہ ژور ریتھ تہ فصل واتہِ؟ وچھ، بہٕ چُھس ژے ونان، پنٕنۍ أچھ تُلِتھ تہٕ کھہَن کُن وُچھ۔ تکیازِ تم چھہِ گۅڈے سفید۔\n36. یُس لُٹان چُھ، سُہ چُھ اَبدی زندگی خٲطرٕ پھل حٲصل کَران، یُس وُچھان چُھ تہٕ یُس رٔلِتھ رٔلِتھ روزِ۔\n37. تہٕ یَتھ مَنٛز چُھ یہِ کتھ پٔز زِ اَکھ چُھ وونان، تہٕ بیٛاکھ چُھ لُٹان۔\n38.\\tمے سوزمُت ژے سُہ لُٹنہٕ خٲطرٕ یُس نہٕ تۅہہ محنت کٔرِتھ، باقٕے لٔگۍ محنتہٕ، تہٕ تُہۍ چھِو تِمن ہٕنزِ محنتہٕ مَنٛز دٲخل گٔمٕژ۔\n39.\\tتہٕ اَمہِ شہرٕکۍ واریاہ سامری ٲسۍ أمِس زنانہِ ہٕندِس کلامَس پیٹھ یقین تھاوان، یٔمۍ گوٲہی دِژ، تٔمۍ ووٚن میہ سُہ سورُے یُس میہ کورمُت۔\n40. یێلہِ ییلہ سامری أمِس نِش آیہ، تِمو کٔر أمِس التجا زِ سُہ روزِ تِمن سٍتـ̡ روزُن، تہٕ سُہ روٗد دۄن دۅہن اَتہِ روزُن۔\n41.\\tتہٕ بییہ تہِ چھہ تمۍ سندِ کلامس پیٹھ یقین تھاوان۔\n42. تہٕ وۆنُن زنانہِ ہٕندِس کُنہِ کتھہِ سٍتـ̡ پى۪ٹھ، تێلہِ چُھہ أسـ̡ پى۪ٹھ\n43.\\tوۅنۍ گۆو دۅیو دۅہو پَتہٕ تتہِ نیرِتھ گلیل کُن۔\n44.\\tعیسیٰ علیہ السلام دِژ پانہٕ گوٲہی زِ أکِس پیغمبرس چھُنہٕ پننِس ملکس مَنٛز کانہہ عزت۔\n45. پَتہٕ ییلہ سُہ گلیل آو تہٕ گلیلیو کٔر أمِس استقبال، یِم تٔمۍ یروشلمس مَنٛز دعوتس مَنٛز کٔرۍ، تِکیازِ تِم تہِ گٔیہِ دعوتس مَنٛز۔\n46. یێمہِ سٍتـ̡ حضرت عیسیٰ علیہ السلام آو دُبارٕ گلیل کِس کاناہس مَنٛز، یێتہِ تٔمۍ آبہٕ شراب۔ تہٕ اَکھ خاص رئیس، یٔمۍ سُند نیچو کپرنومس منز بیمار اوس۔ {رٔعیٖب: یا، درباری، یا، حکمران}\n47.\\tییلہ تٔمۍ بوٗز زِ عیسیٰ مسیح آو یہودایہ پیٹھٕ گلیل کِس مَنٛز دِنہٕ، سُہ گوٚو أمِس نِش تہٕ تٔمِس کٔرٕن التجا زِ سُہ گژھہِ بۄن تہٕ پننِس نیچوِس شفا دِنہٕ، تکیازِ سُہ اوس مرنہٕ کِس موقعس پیٹھ۔\n48. اَمہِ پَتہٕ ووٚن عیسیٰ علیہ السلام تٔمِس زِ یوٚت تام نہٕ تُہۍ نشانہٕ تہٕ عجائب وُچھِو، تُہۍ ہیکِو نہٕ پژھ کٔرِتھ۔\n49.\\tرئیسَن چُھ أمِس وَنُن زِ جناب، میانہِ شُرِ سٕندِ مرنہٕ برونہہ، بۄن ؤسِو۔\n50.\\tعیسیٰ چُھ أمِس ونان زِ پَنٕنـ̡ وَتہٕ پٔکِو۔ تُہند نیچو چُھ زندٕ۔ تہٕ أمِس نفرن پژھ کٔر تتھ لفظس پیٹھ یُس حضرت عیسیٰ علیہ السلام أمس سٍتـ̡ کتھ کورمُت اوس، تہٕ سُہ گۆو پننہِ وتہِ۔\n51.\\tتہٕ ییلہ سُہ وۅنۍ بۄن وسان اوس، تٔمۍ سٕندِس نوکر سمکھے أمِس تہٕ وونُن زِ تُہند نیچو چُھ زندٕ۔\n52.\\tتمہ پتہ پرژھ تمن سٍتـ̡ تمہِ ساعتہ ییلہ تٔمۍ ترمیم شروع کٔر۔ تہٕ تِمو ووٚن أمِس راتھ سٔتِمِس بجہِ تپھ۔\n53.\\tتێلہِ اوس مٲلِس پتاہ زِ یہِ اوس اَمی ساتہٕ یێمہِ سٍتـ̡ حضرت عیسیٰ علیہ السلام أمِس ووٚنمُت، تُہند نیچو چُھ زندٕ، تہٕ پانس تہٕ تٔمۍ سُند پورٕ گرٕ چُھہ پٲٹھۍ۔\n54. یہِ {چُھ} دُبارٕ دوٚیِم معجزہٕ {یُس} حضرت عیسیٰ علیہ السلام کٔر، یێلہِ سُہ یہوداہ پیٹھٕ گلیل مَنٛز آو۔","1. امہِ پتہٕ سپُد یہودین ہُند دعوت۔ تہٕ عیسیٰ ووت یروشلمس تام۔\n2. وۅنۍ چُھ یروشلمس مَنٛز دانٛد {بازر} نِش اکھ تالاب، یتھ عبرانی زبانہِ مَنٛز بیتھیسڈا ونان چھِ، یتھ پانژھ دٲر چھِ۔ {مارکیٹ: یا، گیٹ}\n3.\\tیِمن منز ٲس نامرد لُکن ہٕنز اکھ بٔڈ بٔڈ بٔڈۍ بٔڈۍ، انہِ، رُکاونہٕ آمٕژ، مرٔزِتھ آبہٕ کِس پَکُنُک انتظار۔\n4. تکیازِ اکھ فرشتہ اوس أکِس خاص موسمس منز تالابس منز بۄن تہٕ آبس پریشان کٔرِتھ، یُس تہِ آبہٕ پریشان گژھنہٕ پتہٕ اژان اوس، سُہ اوس تٔمِس کُنہِ تہِ بیمارِ سٍتـ̡ بٔنِتھ۔\n5.\\tتہٕ اَکھ شخٕص اوس، یٔمِس ترٕہ ٲٹھہِ ؤری بیمارِ ٲس۔\n6.\\tییلہ حضرت عیسیٰ علیہ السلام تس اپُز وُچھمُت، تہٕ یہ زانان زِ سُہ چُھہ وُنہِ واریاہ کالہٕ گومُت، سُہ چُھ أمِس وَنُن، کیا ژٕ گژھِہ پوٗرٕ گٔژھِتھ؟\n7.\\tنامرد انسانن دیُت أمس جواب، جناب، میہ چُھنہٕ کانہہ انسان، ییلہ آبس پریشان آسہِ، میہ تراوِ تالابس منز، مگر ییلہ بہٕ یِوان چھُس، بیاکھ اکھ قدم چھُس میانہِ برونہہ کُن۔\n8. عیسیٰ مسیح چُھ أمِس ونان زِ ووٚتھ، پَنُن بسترٕ رٔٹِو، تہٕ پَکُن پَکُن۔\n9.\\tتہٕ فوراً گوٚو یہِ شخٕص پوٗرٕ تہٕ روٚٹ پنُن بستر، تہٕ پَکُن پَکُن: تہٕ امی دۅہہ اوس سبت دۅہ۔\n10. یێمہِ کِنۍ ووٚن یہودیو یُس شفا گومُت چُھ، یہِ چُھہ سبت دۅہہ، چُھہ نہٕ تۅہہِ ہُند بسترٕ تُلُن جٲیز۔\n11.\\tتٔمۍ دیُت تِمن جواب، یُس میہ پوٗرٕ بنوومُت، یێمہِ وۆنُن پَنُن بسترٕ رٔٹِتھ پَکُن۔\n12.\\tتێلہِ پرژھ تمس کُس انسان یُس ژیہ ووٚن، بسترس رٔٹتھ پکان تہ پکُن۔\n13.\\tیُس یُس شفا اوس دِنہٕ آمُت سُہ اوس نہٕ سُہ کُس اوس، تکیازِ حضرت عیسیٰ علیہ السلام اوس پانس پانس نِش دِژمُت، واریاہ بٔڈ وجود۔ {اکھ کثیر...: یا، تتھ ہجوم منزٕ یُس اوس}\n14.\\tاَمہِ پَتہٕ چُھ عیسیٰ مسیح سُہ ہیکلس مَنٛز لبنہٕ آمُت، تہٕ وونُن تٔمِس وُچھِو، وُچھِو، تہٕ وُچھِو تُہہِ سٍتـ̡ گۅناہ کٔرِتھ، یێلہِ نہٕ تۅہہِ سٍتـ̡ کانہہ بدتر چیز واتہِ۔\n15. یہِ شخٕص دراو تہٕ یہودین ووٚنُن زِ یہِ اوس عیسیٰ مسیح، یٔمۍ سُہ پوٗرٕ بنیومُت۔\n16. تہٕ امہِ مۅکھہ کٔر یہودیو عیسیٰ ہس ستاونہٕ تہٕ مارنٕچ کوٗشش، تکیازِ تٔمۍ ٲس یِم کٲم سبت دۅہہٕ کٔرمٕژ۔\n17. مگر عیسیٰ مسیحن دیت تمن جواب، میون مول چُھ وُنیُک تام کٲم کران، تہٕ بہٕ چُھس کٲم کران۔\n18.\\tتێلہِ کٔر یہودیو أمِس مارنہٕ خٲطرٕ زیادٕ کوشش، تکیازِ تٔمۍ اوس نہ صرف سبت پھُٹروومُت بلکہ اوس یہ تہِ ونان زِ خدا اوس تٔمۍ سُند مول، یُس پانس خدایس برابر بناوان اوس۔\n19. تێمہِ پٲٹھـ̡ دیُت عیسیٰ مسیحن جواب تہٕ وونُن تِمن پٔزۍ پٲٹھۍ، یێلہِ چُھہ یێلہِ تہِ چُھہ یێلہِ تہِ چُھہ یێلہِ سُہ باپ سُند کٲم کران چُھ، تێلہِ چُھہ یێلہِ تہِ سُہ کُنہِ تہِ کٲم کران چُھ، تێلہِ چُھہ یێلہِ تہِ سُہ چُھہ نیچوُن تہِ کران۔\n20.\\tکیازِ باپ چُھ نیچوِس سٍتـ̡ محبت کران، تہٕ سُہ ہاوِ أمِس یِمو کھوتہٕ زیادٕ کٲم ہاونہٕ، یُتھ تُہۍ حیران گٔژھِو۔\n21. یێلہِ پٲٹھـ̡ باپ چُھہ مُردن زندٕ کٔرِتھ، تہٕ تِمن زندٕ چُھہ کٔرِتھ؛ یێلہِ تہِ چُھ نیچو یێلہِ تہِ چُھہ یێلہِ سُہ یێلہِ تہِ چُھہ یێلہِ س\n22.\\tکیازِ باپ چُھ نہٕ کٲنسہ تہِ انسانس سٍتـ̡ فیصلہ کران، مگر کورُن سورے فیصلہٕ نیٚچوِس سٍتـ̡ دِنہٕ:\n23.\\tزِ سارِنٕے انسان گژھن نیچوِس عزت کرٕن، یِتھٕ پٲٹھۍ تِم مٲلِس عزت کران چھِ۔ یُس نہٕ نیچوِس عزت کران چُھ، سُہ چُھ نہٕ تس مٲلِس عزت کران یُس أمِس سوزمُت چُھ۔\n24. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ یُس میون کلام بوزان چُھ، تہٕ یُس مےٚ سوزمُت چُھ، سُہ چُھ ابدی زندگی حٲصل کٔرِتھ، تہٕ سُہ گژھِ نہٕ مذمت کرنہٕ۔ مگر یہ چھہ مرنہٕ پیٹھہ زندگی تام منتقل سپدان۔\n25. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ وقت چُھ یِوان، تہٕ وۄنۍ چُھ، یێلہِ مُردٕ خدایہِ سٕندِس نیٚچوِس سٕنز آواز بوزن، تہٕ یِم بوزان آسن زندٕ۔\n26. یێلہِ پٲٹھـ̡ مٲلِس پانس مَنٛز زندگی چُھ؛ یِتھٕ پٲٹھۍ چُھ أمِس نیٚچوِس پانس مَنٛز زندگی دِنہٕ خٲطرٕ دِژمُت۔\n27.\\tتہٕ دِژُن أمِس فٲصلہٕ دِنُک تہِ اِختِیار دِژمُت، تِکیازِ سُہ چُھ انسان سُند نیٚچُو۔\n28.\\tاتھ پیٹھ گژھ نہ حیران: تکیازِ وق چھہ یِوان، یتھ منز قبرن منز موجود سارِوٕے تٔمۍ سٕنز آواز بوزِ،\n29. تہٕ گژھہِ برونہہ کُن۔ یِمو زندگی ہٕندِس قیامتس سٍتـ̡ نیکی کٔرمٕژ چھِ؛ تہٕ تِمو یِمو بُرٕ کٔرۍ، لعنت کِس قیامتس تام۔\n30. بہٕ ہیٛکہٕ نہٕ پانَے کُنہِ تہِ کٔرِتھ: یُتھ بہٕ بوزان چھُس، بہٕ چھُس فٲصلہٕ دِوان: تہٕ میون فٲصلہٕ چھُ منصفانہٕ۔ کیازِ بہٕ چُھس نہٕ پنٕنۍ مرضی ژھاران بلکہ چھُس مٲلۍ سٕنز مرضی یٔمۍ مےٚ سوزمُت چھُ۔\n31. اگر بہٕ پننِس پانس سٍتـ̡ گواہی دِوان چُھس، میٲنۍ گواہی چھے نہٕ صحیح۔\n32.\\tبیاکھ چھہ یُس میانہِ شہادت دِوان چھُ۔ تہٕ بہٕ چھُس پتاہ زِ یُس گواہ سُہ میانہِ متعلق گواہی دِوان چُھ، سُہ چُھ صحیح۔\n33. یێلہِ سُہ اوس یوحنا سٍتـ̡ سٍتـ̡ گوٲہی دِنہٕ آمُت۔\n34.\\tمگر میہ چھہ نہ انسانس نش گواہی میلان، مگر یم کتھہ چھیہ میہ ونان زِ تم گژھہِ نجات دِنہٕ۔\n35.\\tسُہ اوس اکھ دزان تہٕ چمکدار گاش: تہٕ تُہۍ ٲسِو أمۍ سٕندِس گاشس منز خوش گژھنہٕ خٲطرٕ أکِس وقتس خٲطرٕ تیار۔\n36.\\tمگر میہ چُھہ یوحنا سٕندِ کھۅتہٕ زیادٕ گوٲہی دِژمٕژ: یِم کامہِ مٲلۍ سٕندِ دٔسۍ میہ دِژمٕژ چھِ، تِم کامہِ یِم بہٕ کران چھِ، تِم کامہِ ہٕنز گوٲہی دِوان یُس مٲلہِ سٕندِ دٔسۍ سوزمُت چھُ۔\n37.\\tتہٕ پانہٕ یُس میہ سوزمُت چُھ، چُھہ میانہِ سٍتـ̡ گوٲہی دِژمٕژ۔ ژیہ چھیہ نہ کنہِ ساعتہ تسنز آواز بوزمژ تہ نہ چھیہ تسنز شکلہ وچھمژ۔\n38.\\tتہٕ تۅہہِ چُھہ نہٕ تٔمۍ سُند کلام پانس مَنٛز قایم روزان: یێمہِ سٕندِ خٲطرٕ تٔمۍ سوزمُت چُھ، تٔمِس سٍتـ̡ چُھہ نہٕ تٔمِس پیٹھ یقین کٔرِتھ۔\n39. صحیفہٕ ژھانڈِو۔ تِکیازِ تِمن مَنٛز چُھہ تۅہہِ ہُند خیال زِ تۅہہِ چُھہ ابدی زندگی حٲصِل کٔرِتھ، تہٕ تِم چھِ تِم یِم میانہِ گوٲہی دِوان چھِ۔\n40. تہٕ تُہۍ یِو نہٕ میانہِ نِش، یُتھ زِندگی حٲصِل کٔرِتھ۔\n41.\\tمیہ چھہ نہ مردن ہٕندِ طرفہٕ عزت میلان۔\n42. مگر بہٕ چُھس ژے زانان زِ ژے چُھہ نہٕ پانس مَنٛز خدایہِ سُند محبت۔\n43. بہٕ چُھس پننِس مٲلہِ سٕندِ ناوٕ سٍتـ̡ آمُت، تہٕ تہٕ تێہہ چُھہ نہٕ میہ قبول۔\n44.\\tتۅہہ کِتھہ پاٹھۍ ہیکو یقین کٔرتھ، یُس اکھ أکِس سٍتـ̡ عزت حٲصل کران چُھ، تہٕ سُہ عزت یُس صرف خدایہ سٕندِ طرفہٕ میلان چُھ؟\n45.\\tیہ مہٕ سوچو زِ بہٕ کرٕ ژےٚ مٲلِس سٍتـ̡ الزام دِوان، یێمہِ سٍتـ̡ چُھہ موسیٰ سٍتـ̡ تہِ الزام لگاوان، یێمِس پیٹھ تُہۍ بھروسہٕ کران چھِو۔\n46. تکیازِ اگر تہۍ موسیٰ ہس پیٹھ یقین کرو تیلہِ آسہ ہا میہ پژھ کٔرتھ، تکیازِ تمۍ اوس میانہِ متعلق لیوکھمُت۔\n47.\\tمگر اگر نہٕ تٔمۍ سٕندِس تحریرس پیٹھ یقین چھِو، تیلہِ کِتھہ کٔنۍ کٔرِو میانہِ کلامَس پیٹھ پژھ؟","1.\\tیِمو چیزو پَتہٕ گۆو عیسیٰ علیہ السلام گلیل کِس سمندرس پیٹھ، یُس طبیریاہُک {سمندر} چُھ۔\n2.\\tتہٕ لٔج أمِس پَتہٕ واریاہ بٔڈِ، تِکیازِ تِمو وُچھ تٔمۍ سٕندِ معجزات یِم تِمن پیٹھ کٔرۍ۔\n3. تہٕ عیسیٰ ووت أکِس پہاڑس پیٹھ، تہٕ تتہِ بیوٹھ سُہ پننین شاگردن سٍتـ̡ ۔\n4. تہٕ یہودین ہُند عید اوس فسح نزدیک۔\n5. یێلہِ حضرت عیسیٰ علیہ السلام تُلِتھ اَکھ بٔڈ صحبتہٕ أمِس نِش یِوان وُچھ، سُہ چُھ فلپس وَنُن زِ أسۍ کتہِ ہینہٕ روٹی یُتھ یِم کھٮ۪ن؟\n6.\\tتہٕ یہِ ووٚن أمِس ثٲبت کرنہٕ خٲطرٕ: تِکیازِ سُہ اوس پانہٕ زانان زِ سُہ کیا کرِ۔\n7.\\tفلپس دیُت أمِس جواب، زٕ ہتھ پونسہٕ روٹی چُھنہٕ تِہندِ خٲطرٕ کٲفی، یُتھ زن پرٮ۪تھ کانہہ ہیکہِ رژھ کھنڈ نِتھ۔\n8. تٔمۍ سُند اکھ شٲگِر، شمعون پطرس سُند بوے اینڈریو چُھ أمِس ونان ،\n9.\\tاَتہِ چھُ اَکھ لڑکہٕ، یٔمِس پانژھ وٕشکہٕ روٹِتھ تہٕ زٕ لۄکٕٹۍ گاڈٕ چھِ، مگر یِم کُس چھُ واریاہن مَنٛز ؟\n10. تہٕ حضرت عیسیٰ علیہ السلام ووٚن، بِہناوُن نفر۔ وۅنۍ ٲس اتھ جایہ واریاہ گاسہ۔ چنانچہ بیوٹھ مرد تقریباً پانژھ ساس تعدادس منز۔\n11. تہٕ حضرت عیسیٰ علیہ السلامن نِش روٹ۔ تہٕ ییلہ تٔمۍ شُکریہ ادا کوٚر، تٔمۍ بٲگرٲو شاگردن تہٕ شاگردن تہٕ یِمن ہٕندِس مُتعلِق دِنہٕ آمٕتۍ۔ تہٕ یِتھے پٲٹھۍ چھِ گاڈَن ہُند تہِ یوتاہ تِم کرِ۔\n12.\\tییلہ تِم بٔرِتھ گٔیہِ، تٔمۍ ووٚن پننین شاگردن زِ یِم باقٕے ٹُکرٕ جمع کٔرِتھ، یُس نہٕ کانہہ تہِ ضایع سپدِ۔\n13.\\tلہذا کٔر تِمو جمع تہٕ بٔرِکھ باہ ٹوٗکرِ پانژَو وٕشکہٕ روٹین ہٕندِ ٹُکرٕ سٍتۍ، یِم کھٮ۪نہٕ والٮ۪ن ہٕندِ خٲطرٕ ہیوٚر تہٕ ہیوٚر روٗدۍ۔\n14.\\tتێلہِ ییلہ تِمو عیسیٰ علیہ السلام سُند معجزہ وُچھمُت اوس، وۆنُن زِ یہِ چُھ پزر سُہ پیغمبر یُس دُنیاہس مَنٛز یُس یُس دُنیاہس مَنٛز یُن۔\n15. یێلہِ عیسیٰ علیہ السلامن یہ سمجھ زِ تِم یِن زبردستی أمِس بادشاہ بناونہٕ خٲطرٕ، سُہ دراو پانہٕ أکِس پہاڑس کُن۔\n16. تہٕ ییلہ تہِ {ونہ} آو تہٕ تٔمۍ سٕندۍ شٲگِر گٔیہِ سمندرس کُن،\n17.\\tتہٕ ژاو أکِس جہازس منز، تہٕ ووت سمندرس اپارِ کفرناؤمس کُن۔ تہٕ وۅنۍ اوس انہِ گوٚٹ، تہٕ عیسیٰ اوس نہٕ تِمن نِش آمُت۔\n18.\\tتہٕ سوٚدرٕ ووت اَکہِ زبردست واو سٍتـ̡ یُس وُپھ وُن۔\n19.\\tتێلہِ ییلہ تِمو پانژ، وُہ یا ترہ فرلانگ ناوِ کٔرِتھ، تِمو وُچھ عیسیٰ سمندرس پیٹھ پکان تہٕ جہازس نزدیک یِوان: تہٕ تِم گٔیہِ کھوژان۔\n20. مگر سُہ چُھ تِمن ونان زِ یہِ چُھس بہٕ چُھس۔ خوفزدہ گژھ نہٕ۔\n21.\\tتمہ پتہ روٚٹ تمو پننہ مرضی سان جہازس منز۔تہ یکدم ووت جہازِ تتھ زمینس پیٹھ ییتہِ تم گٔیہ۔\n22.\\tدۆیمہِ دۅہہ ییلہ سمندرس اپارِ کھڑا لوکو وُچھ زِ تتہِ چھیہ نہ بییہ کانہہ ناو، سوائے سۅ ناوِ یتھ منز تٔمۍ سٕندِ شٲگِر اژان ٲسۍ، تہٕ حضرت عیسیٰ علیہ السلام گۆو نہٕ پننین شاگردن سٍتـ̡ ناوِ منز بٔنِتھ بلکہ گٔیہِ تٔمۍ سٕندِ شٲگِرِ کُنی کُنی نیران۔\n23.\\t(توتہِ آیہ تیبیریا پیٹھٕ باقٕے ناوٕ تتھ جایہِ نکھٕ ییتہِ تِمو روٹی کھٮ۪وان ٲسۍ، تمہ پتہٕ اوس خداوند شُکر ادا کورمُت:)\n24.\\tیێلہِ لوکو وُچھ زِ عیسیٰ مسیح اوس نہٕ تتہِ تہٕ نہ تٔمۍ سٕندِس شٲگِرِد، تِمو تہِ گٔیہِ جہازٕ سٍتـ̡ تہٕ حضرت عیسیٰ سٕندِس ژھانڈنہٕ خٲطرٕ آیہ کفرناؤمس کُن۔\n25.\\tتہٕ ییلہ تمو سُہ سمندرٕ کِس دوٚیمہِ طرفہٕ لوٚب، تِمو ووٚن أمِس ربی، ژٕ کر آو یور ؟\n26.\\tحضرت عیسیٰ علیہ السلام دیُت تِمن جواب تہٕ وونُن، پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ تم چھِو نہ معجزات وُچھمٕتۍ، بلکہ امہ مۅکھہ زِ ژے روٹی کھیوٚو تہٕ بٔرِتھ ٲس۔\n27. تتھ مازس خٲطرٕ کٔرِو نہٕ محنت یُس ختم سپدان چُھ، بلکہ تتھ مازٕ خٲطرٕ یُس ابدی زندگی تام روزِ، یُس انسان سُند فرزند ژےٚ دِیہِ، تٔمِس خٲطرٕ چُھ خدا باپ مُہر دِنہٕ آمُت۔ {محنت نہٕ: یا، کٲم کٔرِو نہٕ}\n28.\\tتێلہِ ووٚن تِمو أمِس زِ أسۍ کیا کٔرِو، یُتھ أسۍ خدایہ سٕنزِ کٲم کٔرِتھ؟\n29. حضرت عیسیٰ علیہ السلام دِیُت جواب تہٕ وونُن تِمن زِ یہِ چُھ خدایہِ سٕنز کٲم، یُس تٔمِس سٍتـ̡ یێلہِ تٔمِس سٍتـ̡ پژھ چُھہ یێمِس سٍتـ̡ یێلہِ سٍ\n30.\\tتِمو ووٚن أمِس کُس نشانہٕ، یُتھ أسۍ وُچھِتھ تہٕ پژھ کٔرِو؟ تُہۍ کیا چھِو کٲم کران؟\n31.\\tسانۍ مٲلۍ ٲسۍ ریگستانس منز منا کھیوان۔ یِتھ کٔنۍ چُھ لیکھنہٕ آمُت، تٔمۍ دِژ تِمن آسمانہٕ پیٹھٕ روٹی کھٮ۪نہٕ خٲطرٕ۔\n32. تێمہِ وۆن حضرت عیسیٰ علیہ السلام تِمن وۆن، پٔزۍ پٲٹھۍ، بہٕ چُھس تہِ ونان زِ موسیٰ ہن دِژ نہٕ اسمانہٕ پیٹھٕ سۅ روٹی دِژمٕژ۔ مگر میون مول چُھ ژےٚ آسمانہٕ پیٹھٕ حقیقی روٹی دِوان۔\n33. کیازِ خدایہِ سٕنز روٹی چُھ سُہ یُس اسمانہٕ پیٹھٕ وسان چُھہ تہٕ دُنیاہس زندگی دِوان چُھ۔\n34. اَمہِ پتہٕ ووٚن تِمو أمِس خداوند، اسہِ دِیُن یہِ روٹ۔\n35. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تِمن زِ بہٕ چُھس زندگی ہٕنز روٹی تہٕ یُس میانہِ نِش یِنہٕ سُہ گژھہِ نہٕ زانہہ فاقہٕ۔ تہٕ یُس میہ پیٹھ ایمان تھاوان آسہِ سہ گژھہِ نہ زانہہ ترش۔\n36. مگر میہ ووٚن ژے زِ ژے تہِ چھکھ میہ وچھمُت، تہٕ یقین چھُنہٕ کران۔\n37. یُس سٲری مٲلۍ میہ دِوان چُھ، سُہ گژھہِ میہ نِش واتہٕ۔ تہٕ یُس میانہِ نِش یِوان چُھس بہٕ کُنہِ تہِ پٲٹھۍ کٔڑِتھ کٔرِتھ۔\n38. تکیازِ بہٕ ووت آسمانہٕ پیٹھ، نہ پنٕنۍ مرضی پورٕ کرنہٕ خٲطرٕ، بلکہ سُہ سُند مرضی یُس مےٚ سوزمُت اوس۔\n39. تہٕ یِہ چُھ مٲلہِ سٕنز مرضی یُس میہ سوزمُت چُھ، یُس تٔمۍ مے دِژمُت چُھ، بہٕ پزِ نہٕ کانہہ تہِ رٲوُن، مگر پَزِ ٲخری دۅہہٕ دُبارٕ دُبارٕ تُلنہٕ۔\n40. تہٕ یِہ چُھ تٔمۍ سٕنز مرضی یُس مے سوزمُت چُھ، یُس پریتھ کانہہ یُس نیچو وُچھان چُھ، تہٕ تس پیٹھ ایمان تھاوان چُھ، سُہ گژھہِ ابدی زندگی حٲصل کٔرِتھ، تہٕ بہٕ کرٕ تس ٲخری دۅہہٕ زندٕ۔\n41.\\tیہودی کٔر أمِس کُن بڑبڑاوان، تکیازِ تٔمۍ ووٚن، بہٕ چُھس سُہ روٹی یُس آسمانہٕ پیٹھٕ وسان اوس۔\n42. تہٕ تِمو ووٚن، کیا یہِ چھُنہٕ حضرت عیسیٰ سُند نیچو، یٔمۍ سُند مول تہٕ موج أسۍ زانان چھِ؟ تیلہِ کتھہ پاٹھۍ چھہ سہ ونان زِ بہٕ ووت آسمانہ پیٹھ۔\n43.\\tحضرت عیسیٰ علیہ السلام دِژ جواب تہٕ وونُن تِمن سٍتـ̡ پٲٹھ\n44.\\tکانہہ تہِ انسان ہیکہِ نہٕ میانہِ نِش یِتھ، مٲلِس سٍتـ̡ یٔمۍ میہ سوزمُت چُھ، تہٕ بہٕ کرٕ تس ٲخری دۅہہٕ تُلِتھ۔\n45.\\tیہ چھہ پیغمبرن منز لیکھنہ آمت، تہ تم گژھن سارنے خدایہ سنز تعلیم دِنہٕ۔ تَمہِ کِنۍ چُھ پرٮ۪تھ کانہہ انسان یُس بُوزمُت چُھ، تہٕ مٲلِس سٍتـ̡ زانان چُھ، سُہ چُھ میانہِ نِش یوان۔\n46. یہِ چُھہ نہٕ زِ کٲنسہِ تہِ چُھہ باپ وُچھمُت، سوائے یُس خدایہِ سُند چُھ، تٔمۍ چُھ مٲلِس وُچھمُت۔\n47. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ یُس میہ پیٹھ ایمان تھاوان چُھ، سُہ چُھ ابدی زندگی حٲصل کران۔\n48. بہٕ چُھس زندگی ہٕنز سۅ روٹی ۔\n49.\\tچانہِ مٲلۍ ٲسۍ بیابانن منز منا کھٮ۪وان تہٕ گٔیہِ مٔرۍ۔\n50. یہِ چُھ سُہ روٹی یُس اسمانہٕ پیٹھٕ وسان چُھ، یُس انسان کھٮ۪تھ تہٕ مَرِ نہٕ۔\n51. بہٕ چُھس سُہ زندٕ روٹی یُس اسمانہٕ پیٹھٕ وسان چُھ، یُس کانہہ انسان امہِ روٹی منز کھٮ۪یہ، سُہ روزِ ہمیشہٕ زندٕ۔ تہٕ یُس روٹی بہٕ دِیہٕ سُہ چُھہ میون ماز، یُس بہٕ دُنِیاہٕچ زندگی خٲطرٕ دِیہِ۔\n52.\\tیہودی کٔر پانہٕ أکِس سٍتـ̡ جدوجہد کران زِ یہِ انسان کِتھ کٔنۍ دِیہِ اسہِ کھٮ۪نہٕ خٲطرٕ ماز دِتھ۔\n53. یێلہِ حضرت عیسیٰ علیہ السلامن ووٚن تِمن زِ پٔزۍ پٲٹھۍ، بہٕ چُھس تہٕ یێلہِ نہٕ تۅہہِ سُند ماز کھٮ۪وان تہٕ تٔمۍ سُند خوُن چیٚو، تێلہِ چُھہ نہٕ تێلہِ کانہہ زُوُن۔\n54. یُس میون ماز کھٮ۪وان تہٕ میون خون چیٚیہ، سُہ چھُ ابدی زندگی حٲصِل کٔرِتھ۔ تہٕ بہٕ کٔرٕ تس ٲخری دۅہہ تُلان۔\n55. تکیازِ میون ماز چُھ پزۍ پاٹھۍ ماز تہٕ میون خون چُھ پٔزۍ پٲٹھۍ۔\n56. یُس میون ماز کھیوان چُھ، تہٕ میون خون چیوان چُھ، سُہ چُھ میٲنس مَنٛز روزان، تہٕ بہٕ چُھس تس مَنٛز۔\n57. یِتھٕ کٔنۍ زِندٕ مٲلہِ سٕندِ دٔسۍ سوزمُت چُھ، تہٕ بہٕ چُھس مٲلہِ سٕندِ سٍتـ̡ زندٕ روزان، یێلہِ سُہ تہِ چُھس میانہِ سٍتـ̡ زندٕ روزُن۔\n58.\\tیہِ چُھ سُہ روٹی یُس اسمانہٕ پیٹھٕ وسان اوس، یُس نہٕ تۅہہِ آبو مَن کھٮ۪وان اوس، تہٕ موٗدمُت، یُس یَتھ روٹی کھٮ۪وان آسہِ سُہ روزِ ہمیشہٕ زندٕ۔\n59.\\tیِمو کتھہٕ وَنُن اوس یہِ عبادت خانس مَنٛز، یِتھ کٔنۍ تٔمۍ کفرناؤمس مَنٛز پرناوان اوس۔\n60.\\tتێمہِ کِنۍ ییلہ تٔمۍ سٕندیو واریاہو شاگردن یہِ بوزو، ووٚن زِ یہِ چُھ سخٕت کہانی۔ یہ کُس ہیکہِ بوزِتھ؟\n61.\\tیێلہِ حضرت عیسیٰ علیہ السلام پانس منز پتاہ زِ تٔمۍ سٕندِس شٲگِرِ چُھہ اتھ پیٹھ گڑبڑ کران، تٔمۍ ووٚن تِمن زِ کیا تۅہہِ چُھہ ناراض سپدان؟ {جَرم: یا، سکینڈلائز، یا، تُہۍ ٹھوکر کھسُن}\n62.\\t{کیا} تہٕ اگر ژیہ وُچھِو انسان سُند فرزند ییتہِ برونہہ کُن اوس؟\n63.\\tیہ چھہ روح زندہ کران۔ ماز چھہ نہ کانہہ فایدہ دِوان: یم لفظ میہ ژیہ ونان چھہِ، تم چھہِ روح، تہ یم چھہِ زندگی۔\n64.\\tمگر توہہ منز چھہِ کینہہ یم یقین کران چھہِ۔ تکیازِ حضرت عیسیٰ علیہ السلام اوس گۅڈہ پیٹھے زانان زِ تم کُس چھہِ یُس نہٕ یقین کران اوس، تہٕ کُس پزِ تس دھوکہ دِنہٕ۔\n65. تہٕ تٔمۍ ووٚن، تێمہِ کِنۍ ووٚن میہ ژے زِ کانٛہہ تہِ انسان ہیکہِ نہٕ میٲنس نِش یِتھ، سوائے یہ میٲنس مٲلہِ سٕندِ طرفہٕ دِنہٕ آمُت۔\n66.\\tاَمہِ وقتہٕ پیٹھٕ گٔیہِ تٔمۍ سٕندِ واریاہ شٲگِر واپس، تہٕ گٔیہِ نہٕ أمِس سٍتـ̡ پَکُن۔\n67.\\tتێلہِ وۆن حضرت عیسیٰ علیہ السلام بہن بێیہِ بێیہِ، کیا تُہۍ تہِ نیرِو؟\n68.\\tپَتہٕ دیُت شمعون پطرس أمِس جواب، خداوند، أسۍ کٔمِس نِش گژھو؟ ژے نِش چھِ ابدی زندگی ہٕندۍ کلام۔\n69. تہٕ أسـ̡ چُھہ یقین تھاوان تہٕ یقین چُھہ زِ تہٕ چُھہ سُہ مسیح یُس زندٕ خدایہ سُند نیٚچُو۔\n70.\\tحضرت عیسیٰ علیہ السلام دیُت تِمن جواب، کیا مے چُھہ نہٕ تۅہہ باہ ژارنہٕ آمُت، تہٕ یێلہِ منزٕ چُھ اکھ شیطان؟\n71.\\tتٔمۍ کٔر یہوداہ اسکریوتی سٕندِس نیچوِس سٍتـ̡ کتھ کرنہٕ، تکیازِ سُہ اوس أمِس دھوکہٕ دِنہٕ یُن، یُس بہَن مَنٛز اکھ اوس۔","1.\\tیِمو چیزو پَتہٕ آو عیسیٰ علیہ السلام گلیلِس مَنٛز پَکُن، تِکیازِ یہودی اوس نہٕ یہودی سُہ مارُن یژھان۔\n2. وۅنۍ اوس یہودین ہُند خیمہ دِنہٕ آمُت۔\n3. تٔمۍ سٕندٮ۪و بٲے ووٚن أمِس یێلہِ نیرِو تہٕ یہوداہس مَنٛز گژھُن، یُتھ تُہند شٲگِر تہِ وُچھِن تِم کٲم یِم تۅہہِ کران چھِ۔\n4.\\tتکیازِ {یُس} چھہ نہ کانہہ انسان یُس کانہہ تہِ کتھ کرِ، تہ سہ چھہ پانہ کھلہِ پاٹھۍ زاننہ یژھان۔ اگر ژیہ یِم کٲم کٔرِو، پنُن پان ہٲوِو دُنیاہس برونہہ کُن۔\n5.\\tتکیازِ تٔمۍ سٕندِس بٲے ٲسۍ نہٕ أمِس پیٹھ پژھ تھاوان۔\n6. یێلہِ چُھہ عیسیٰ علیہ السلام تِمن وۆن، میون وق چُھہ نہٕ وُنہِ تہِ آمُت، مگر تُہند وق چُھ ہمیشہٕ تیار۔\n7. دنیا ہیکہِ نہٕ ژےٚ نفرت کٔرِتھ۔ مگر میہ چھیہ یہ نفرت، تکیازِ بہٕ چھُس اتھ کتھہِ ہنز گوٲہی دِوان زِ امہ چہ کٲم چھیہ بدکار۔\n8.\\tیَتھ دعوتس تام گژھِو بہٕ وُنہِ تہِ اتھ دعوتس تام ووتُن۔ تکیازِ میون وقت چھہ نہ وُنہِ پورہ۔\n9.\\tییلہ تٔمۍ یِم لفظ تِمن وَننہٕ آمٕتۍ، سُہ روٗد گلیلِس مَنٛز روزُن۔\n10.\\tمگر ییلہ تٔمۍ سٕندِ بٲے ہیوٚر گٔیہ، تیلہِ ووت سُہ تہِ دعوتس تام، نہ کھلہِ پٲٹھۍ، بلکہ یتھہ پاٹھۍ یہ راز اوس۔\n11.\\tپتہٕ ووت یہودیو أمِس دعوتس مَنٛز ژھانڈنہٕ تہٕ وونُن، سُہ کتہِ چُھ؟\n12.\\tتہٕ لُکن مَنٛز گٔیہِ أمِس مُتعلِق سٮ۪ٹھاہ گڑبڑ کرنہٕ، کینژَو وَنُن زِ سُہ چُھ اَکھ اصل انسان، باقیو وَنُن نہٕ۔ مگر سُہ چُھ لوٗکن دھوکہٕ دِوان۔\n13.\\tمگر یہودین ہندِ خوفہٕ سٍتـ̡ اوس نہٕ کٲنسہ تہِ أمِس مُتلق کتھ کٔرمٕژ۔\n14.\\tوۅنۍ گۆو عیسیٰ مسیح مندرس منز تہ ہیچھناوُن۔\n15.\\tتہٕ یہودی گٔیہِ حٲران تہٕ وونُن، أمِس شخصس کِتھہ کٔنۍ چُھہ پتاہ زِ أمِس چِٹھۍ چھِ، یُس نہٕ زانہہ ہیٚچھمُت۔ {چٹھۍ: یا، ہیچھن}\n16. حضرت عیسیٰ علیہ السلام دیُت تِمن جواب تہٕ وونُن، میون عقیدہ چُھ نہٕ میون بلکہ سُہ یُس میہ سوزمُت چُھ۔\n17.\\tاگر کانہہ انسان پننہِ مرضی پورٕ کرِ، سُہ گژھہِ امہِ نظریہٕ سٍتـ̡ زانان، چاہے سُہ خدایہ سُند آسہِ، یا بہٕ چُھس پانس مُتلق کتھ کران۔\n18.\\tیُس پننِس بارس منز کتھ کران چُھ، سُہ چُھ پنُن جلال ژھاران یُس أمِس سوزمُت چُھ، سُہ چُھ صحیح، تہٕ تس مَنٛز چُھنہٕ کانہہ ناپاکیزگی آسان۔\n19. کیا موسىٰ ہن دِژ نہٕ شریعت تہٕ {توتہِ} چُھہ نہٕ تۄہہِ منزٕ کانہہ تہِ شریعت مانان۔ ژیہ کیازِ چھکھ میہ مارُن؟\n20.\\tلُکن دِژ جواب تہٕ وونُن، ژے چُھہ شیطان تہٕ کُس چُھہ ژےٚ مارُن؟\n21.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ تِمن وونُن زِ مے چھے اکھ کٲم کٔرمٕژ، تہٕ تُہۍ چھِو سارِوٕے حٲران گٔژھان۔\n22. اَمہِ کِنۍ دِژ موسىٰ ژےٚ ختنہٕ۔ (امہ مۅکھہ نہ زِ یہ چھہ موسیٰ سُند، بلکہ چھہ باپدین سُند؛) تہٕ تم چِھ سبت کہ دوہ اکس مردس ختنہ کران۔\n23. یێلہِ کٲنسہِ سبت دۅہہٕ ختنہ سپدِ، یێلہِ موسىٰ سُند شریعت گژھہِ نہٕ پھُٹراونہٕ یُن۔ کیا ژیہ چھوا میہ پیٹھ ناراض، تکیازِ میہ چھہ سبت کہ دۅہہ اکھ انسان پورہ کرمژ؟ {یہ...: یا، موسیٰ سند قانون پھٕٹراونہٕ ورٲے}\n24.\\tظٲہر مُطٲبق کرو نہٕ فٲصلہٕ، بٔلکہِ کٔرِو صحیح فٲصلُک فٲصلہٕ۔\n25.\\tیِمو منزٕ کینہہ ووٚن یروشلمٕکۍ کینٛہہ، کیا یہِ چھُنہٕ سُہ یُس تِم مارُن یژھان چھِ؟\n26.\\tمگر سُہ چُھ بے باکی سان کتھ کران، تہٕ تِم چھِ نہٕ أمِس کُنہِ تہِ وَنان۔ کیا حکمرانن چھا پٔزۍ پٲٹھۍ پتاہ زِ یہِ چُھ مسیح؟\n27. تێلہِ چُھہ أسـ̡ أمِس انسانس زانان زِ سُہ کتہِ چُھہ یێلہِ چُھہ یێلہِ مسیح یێلہِ چُھہ یێلہِ سُہ کتہِ سٍتـ̡ چُھہ\n28.\\tیێلہِ وۆن عیسیٰ علیہ السلام مندرس مَنٛز یێلہِ تٔمِس ہیچھناوُن، تہٕ بہٕ چُھس نہٕ پانس سٍتـ̡ آمُت، مگر یُس میہ سوزمُت چُھ، سُہ چُھہ پوٚز یُس نہٕ تۅہہ زانان چُھس۔\n29.\\tمگر بہٕ چُھس تس زانان: کیازِ بہٕ چُھس أمِس سٍتـ̡ تہٕ تٔمۍ چُھس سوزمُت۔\n30.\\tپتہٕ تِمو أمِس نِنٕچ کوٗشش، مگر کٲنسہ تہِ تٔمِس پیٹھ اتھہٕ، تکیازِ تٔمۍ سُند وق اوس نہٕ وُنیُک تام آمُت۔\n31.\\tتہٕ واریاہو لُکو کٔر أمِس پیٹھ پژھ تہٕ ووٚنُن، یێلہِ یێلہِ عیسیٰ یِیہ، کیا سُہ کٔرِہ یِمو کھۅتہٕ زیادٕ معجزات یُس أمِس انسانس کٔرۍمٕتۍ؟\n32.\\tفریسیو بوز زِ لُکھ چھِ أمِس مُتلق یِژھہٕ کتھہٕ پٲٹھۍ۔ تہٕ فریسی تہٕ بٔڈۍ پادٕرۍ سوٗزۍ أمِس نِنہٕ خٲطرٕ افسر۔\n33.\\tتێلہِ وۆن عیسیٰ علیہ السلام تِمن سٍتـ̡ تہٕ بہٕ چُھس تٔمِس نِش گژھان یُس میہ سوزمُت اوس۔\n34.\\tژیہ ژھانڈِتھ تہٕ میہ لٔبِتھ تہٕ ییتہِ بہٕ آسہِ، تتہِ ہیکہِ نہٕ یِتھ۔\n35.\\tپتہٕ ووٚن یہودی پانس منز، سُہ کوٚت گژھِ، زِ اسہِ لٔبِتھ نہٕ۔ کیا سُہ گژھہِ غیر قومن منز منتشر گژھن والین نِش، تہٕ غیر قومن ہیچھناوُن؟ {غیر قومی: یا، یونانی}\n36.\\tیہ کیا کتھ چھیہ یہ زِ تم چھہِ میہ ژھانڈان تہ میہ لٔبتھ تہ ییتہِ تہِ چھُس نہ ژیہ یِتھ؟\n37.\\tعیسیٰ مسیح کِس ٲخری دۅہس منز، یێلہِ کٲنسہِ تہِ ترش، سُہ گژھہِ میانہِ نِش یِنہٕ تہٕ چُھہ پینہٕ۔\n38. یُس میٲنس پیٹھ ایمان تھاوان چُھ، یِتھ کٔنۍ صحیفہٕ چُھ وننہٕ آمُت، تٔمۍ سٕندِ یٔڈ منزٕ گژھہِ زندٕ آبٕکۍ دریاو۔\n39. (مگر یێمہِ سٍتـ̡ چُھہ یێمہِ روحہٕ سٍتـ̡ یُس أمِس پیٹھ ایمان تھاون وٲلِس پٲٹھـ̡ حٲصل سپدُن: تکیازِ روح القدس اوس نہٕ وُنیُک تام {دِنہٕ}؛ کیازِ زِ عیسیٰ مسیح اوس نہٕ وُنیُک تام جلال دِنہٕ آمُت۔)\n40.\\tتَمہِ مۄکھٕ ییلہ واریاہ لوکھ یہ قول بوزِتھ وونُن زِ حقیقتس مُتلق چھُ یہ رسول اللہ صلی اللہ علیہ وآلہ وسلم۔\n41. باقیو ووٚن، یہِ چُھ مسیح۔ مگر کینژو ووٚن، کیا مسیح گلیل منزہ نیرِ؟\n42. کیا صحیفس منز چُھ نہٕ وننہٕ آمُت زِ مسیح چُھ داؤد سٕندِ اولادٕ سٕندِ نِش آمُت، تہٕ بیت لحم کِس شہرس منز، یتہِ داؤد اوس؟\n43.\\tتہ گۆو تمۍ سندِ وجہ سٍتۍ لوکن منز تقسیم۔\n44.\\tتہٕ یِمو منزٕ آسہ کینہہ أمِس نِوان۔ مگر کٲنسہ تہِ اوس نہ أمس پیٹھ اتھہ۔\n45.\\tاَمہِ پَتہٕ آو افسر بٔڈۍ پادٕرین تہٕ فریسیَن نِش۔ تہٕ تِمو ووٚن تِمَن زِ ژےٚ کیازِ چھِو نہٕ سُہ أنِمُت؟\n46.\\tافسرن دیت جواب، زانہہ تہِ اوس نہ انسانس یتھہ پاٹھۍ کتھ کران۔\n47.\\tتَمہِ پَتہٕ دِیُت تِمن فریسیو جواب، کیا تُہۍ تہِ چھِو دھوکہٕ دِنہٕ آمٕتۍ؟\n48.\\tکیا کٲنسہ حکمرانن یا فریسیو چھہ تس پیٹھ یقین کورمُت؟\n49.\\tمگر یِم لُکھ یُس شریعت زانان چُھ، تِمن چُھہ لعنت۔\n50. نیکوڈیمس چُھ تِمن ونان، (یُس رٲژ عیسیٰ ہس نِش آو، تِمو منزٕ اکھ آسُن،) {عیسیٰ ہس سٍتۍ: Gr. Him}\n51.\\tکیا سانہِ شریعت چھہ انسان سُند فیصلہ کران، امہ برونہہ زِ سُہ کیا چُھ کران؟\n52.\\tتِمو دِژ جواب تہٕ وونُن تٔمِس زِ کیا تُہۍ تہِ چھوا گلیلُک ؟ ژھانڈِو، تہٕ وُچھِو: تِکیازِ گلیل منزٕ چُھنہٕ کانہہ پیغمبر پٲدٕ سپدان۔\n53.\\tتہٕ پرٮ۪تھ کانہہ انسان گوٚو پننِس گرس منز۔","1. عیسیٰ مسیح گۆو زیتون کِس پہاڑس پیٹھ۔\n2. تہٕ صُبحٲے آو سُہ دُبارٕ مندرس مَنٛز، تہٕ سٲری لُکھ آیہِ أمِس نِش۔ تہٕ سُہ بیوٹھ تہٕ ہیچھناوُن۔\n3. تہٕ کاتب تہٕ فریسی أنۍ أمِس نِش زنا کٔرِتھ اکھ زنانہٕ۔ تہٕ ییلہ تمو أمس درمیان تھوو،\n4.\\tتِم چھِ أمِس ونان زِ مالہ، یہِ زنانہٕ ٲس زنا کٔرِتھ نِنہٕ آمٕژ۔\n5.\\tوۅنۍ چھہ موسیٰ شریعتس منز اسہِ حکم دِژمُت زِ یِمن گژھہِ پتھرِ مارنہٕ یُن، مگر تُہۍ کیا چُھہ ونان؟\n6.\\tیہِ ووٚن تِمو أمِس لالچ دِتھ زِ تِمَن گژھہِ أمِس پٮ۪ٹھ الزام لگاونہٕ۔ مگر حضرت عیسیٰ علیہ السلام ووت بوٚن، تہٕ {پننہِ} اونگجہِ سٍتـ̡ لیوکھُن زمینس پیٹھ، {یێتھہ پٲٹھـ̡ تِم بوزان چُھ}۔\n7. یێلہِ تِمو أمِس پرژھنہٕ جٲری تھوو، تٔمِس تھوٚد تہٕ تِمن وونُن، یُس یُس تہٕ یُس گۅنہٕ نہٕ چُھ، سُہ تراوُن گۅڈٕ أمِس کُن کٔنہِ۔\n8.\\tبییہِ ووت سہ بوٚن تہ زمینس پیٹھ لیکھُن۔\n9.\\tتہٕ یِمو بوٗزِتھ {یہ} بوٗزِتھ گٔیہِ اَکہٕ پٲٹھۍ، سارِوٕے کھۄتہٕ بٔڈِس پیٹھٕ {حتیٰ کہ} پٔتِس تام تہٕ عیسیٰ سٕندِس کُنی تہٕ زنانہٕ درمِس منز کھڑا گٔیہِ۔\n10.\\tییلہ حضرت عیسیٰ علیہ السلام پانس تھوٚد تہٕ زنانہِ ورٲے اوس نہٕ کانہہ تہِ وُچھمُت، تٔمۍ ووٚن أمِس زنانہٕ، تِم کتہِ چھِ تۅہہِ پیٹھ الزام لگاونہٕ آمٕتۍ۔ کیا کٲنسہ تہِ چُھہ تۅہہِ مذمت کٔرمٕژ؟\n11.\\tتٔمۍ ووٚن نہٕ کانہہ انسان، خدا۔ تہٕ حضرت عیسیٰ علیہ السلام ووٚن تٔمِس تہٕ بہٕ چُھس نہٕ ژےٚ مذمت کران: گژھ تہٕ گژھ نہٕ مزید گناہ۔\n12.\\tتێلہِ وۆن عیسیٰ علیہ السلام دُبارٕ تِمن سٍتـ̡ وۆنُن، بہٕ چُھس دُنیاہُک گاش، یُس میانہِ پٲروی کرِ، سُہ گژھہِ نہٕ انہِ گٹہِ مَنٛز پَکُن، بٔلکہِ روزِ زندگی ہُند گاش۔\n13.\\tفریسیو ووٚن أمِس زِ ژے چُھکھ پنُن پان درج تھاوان؛ تُہند ریکارڈ چُھ نہٕ صحیح۔\n14.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ ووٚنُن تِمن زِ بہٕ چُھس پنُن پٲٹھـ̡ پى۪ٹھ مگر ژیہ ہیکو نہ یہ ؤنتھ زِ بہٕ کتہِ پیٹھہ آمُت تہٕ کتہِ چھُس گژھان۔\n15.\\tیُس ماز پَتہٕ فیصلہ کٔرِو۔ بہٕ چُھس نہٕ کٲنسہ تہِ انسانس فیصلہ کران۔\n16. تہٕ توتہِ اگر بہٕ فیصلہ کٔرِتھ، میون فیصلہ چُھ صحیح: کیازِ بہٕ چُھس نہٕ کُنی بلکہ بہٕ تہٕ سُہ مٲل یُس مےٚ سوزمُت چُھ۔\n17.\\tیہ تہِ چھہ تُہندس قانونس منز لیکھنہ آمت زِ دۅن نفرن ہنز گوٲہی چھیہ صحیح۔\n18. بہٕ چُھس یُس پانس سٍتـ̡ گوٲہی دِوان چُھ، تہٕ یُس مٲل یُس مےٚ سوزمُت چُھ، سُہ چُھہ میانہِ سٍتـ̡ گوٲہی دِوان۔\n19.\\tاَمہِ پتہٕ ووٚن تِمو أمِس زِ تُہند مول کَتہِ چُھ؟ حضرت عیسیٰ علیہ السلام دیُت جواب، تہٕ ژے چُھہ نہ میہ زانان تہٕ نہ میٲنس مٲلس سٍتـ̡ زانان تہٕ یێلہِ تہِ آسہٕ مٲنِس مٲلس تہِ زانان۔\n20.\\tیِم لفظ چُھہ عیسیٰ سٕندِس خزانس مَنٛز وَننہٕ آمُت، یِتھ کٔنۍ تٔمۍ ہیکلس مَنٛز ہیچھناوان اوس، تہٕ کٲنسہ تہِ اوس نہٕ أمِس پیٹھ اتھہٕ تھوومُت۔ تکیازِ تسند وقت اوس نہ وُنہِ ووتمُت۔\n21. یێلہِ وۆنُن عیسیٰ علیہ السلام دُبارٕ تِمن سٍتـ̡ یێلہِ بێیہِ بێیہِ تہٕ یێلہِ تہِ بہٕ گژھُن، تہٕ یێلہِ تہِ بہٕ یێلہِ تہِ گژھُن، تێلہِ تہِ گژھِو نہٕ یِنہٕ۔\n22.\\tپتہٕ ووٚن یہودی زِ کیا سُہ مارِ پان؟ تکیازِ سُہ چُھ ونان زِ ییتہِ بہٕ گژھِ، تہٕ تُہۍ ہیکو نہٕ یِتھ۔\n23. تہٕ تٔمۍ ووٚن تِمَن زِ تُہۍ چھِو بۄنہٕ کُنہِ پیٹھ۔ بہٕ چُھس ہیرِ پیٹھ: تہۍ چھو یتھ دنیاہُک؛ بہٕ چُھس نہٕ یتھ دنیاہُک ۔\n24.\\tتێلہِ ووٚن میہ ژے زِ ژے گژھہِ پننین گناہن منز مرُن، تکیازِ اگر نہٕ ژیہ یہ یقین کران زِ بہٕ چُھس، تیلہِ گژھہِ تم پننین گناہن منز مرُن۔\n25.\\tتَمہِ پتہٕ ووٚن تِمو أمِس کُس چھُو؟ تہٕ عیسیٰ مسیح چُھ تِمن ونان، یُس میہ شروع پیٹھے ووٚنمُت اوس۔\n26.\\tمیہ چھیہ واریاہ کتھہ وننہ تہ فیصلہ کرُن، مگر یُس میہ سوزان چھہ سہ چھہ صحیح۔ تہٕ بہٕ چھُس دنیاہس سٍتۍ تِم کتھ کٔرِتھ یِم میہ تس متعلق بوزمٕتۍ چھِ۔\n27.\\tتِمن ٲس نہٕ سمجھ زِ تِمن سٍتـ̡ اوس مٲلہِ سٕندِس بارس منز کتھ کٔرمٕژ۔\n28.\\tتێلہِ وۆن عیسیٰ علیہ السلام تِمن سٍتـ̡ ییلہ تم انسان سُند فرزند تُلِو، تێلہِ گژھہِ ژیہ معلوم زِ بہٕ چُھس {سُہ}، تہٕ {یہ} چُھس نہٕ پانس سٍتـ̡ کانہہ تہِ کران۔ مگر یِتھٕ کٔنۍ میٲنس مٲلہِ سٍتـ̡ ہیچھناومُت، بہٕ چُھس یِم کتھ کتھ کران۔\n29. یُس میہ سوزمُت چُھ، سُہ چُھ میہ سٍتـ̡ تکیازِ بہٕ چُھس ہمیشہٕ تِم کٲم کران یم تس خوش کران چھِ۔\n30.\\tییلہ تٔمۍ یِم کتھ کٔرِتھ، واریاہن لوٗکن ہُند یقین اوس أمِس پیٹھ۔\n31.\\tتێلہِ ووٚن عیسیٰ علیہ السلام تِمن یہودین یِم أمِس پیٹھ ایمان تھاوان چھِو، تێلہِ چھِو تُہۍ پٔزۍ پٲٹھۍ میٲنۍ شٲگِرۍ۔\n32. تہٕ پٔزۍ پٲٹھـ̡ پٔزۍ پٲٹھـ̡ تہٕ سٍتـ̡ کرِ توے آزاد۔\n33.\\tتِمو دِژ أمِس جواب، أسۍ چھِ ابراہیم سُند اولاد، تہٕ أسۍ چھِنہٕ زانہہ کٲنٛسہِ ہٕندِس غلامَس مَنٛز، تہٕ کِتھہٕ کٔنۍ چُھکھ وَنُن زِ تُہۍ یِیہِ آزاد کرنہٕ۔\n34. عیسیٰ علیہ السلام دِیُت تِمن جواب، پٔزۍ پٲٹھۍ، بہٕ چُھس تہٕ یُس تہِ گۅنہہ کران چُھ، سُہ چُھہ گۅنہٕ سُند خادم۔\n35. تہٕ خادم چُھ نہٕ گرس مَنٛز ہمیشہٕ روزان: {مگر} چُھ فرزند ہمیشہٕ روزان۔\n36. تێلہِ یێلہِ نیچو تہِ آزاد کرِ، تێلہِ گژھہِ تۅہہ آزاد۔\n37. بہٕ چُھس پتاہ زِ تُہۍ چھِو ابراہیم سُند اولاد۔ مگر تہۍ چھکھ میہ مارُن یژھان، تکیازِ میانہِ کلامس چھیہ نہ ژے منز کانہہ جاے۔\n38. بہٕ چُھس سُہ کتھ کران یُس میہ پننِس مٲلس سٍتـ̡ وُچھمُت چُھ، تہٕ تہٕ تُہۍ چھِو سُہ کٔرِتھ یُس ژے پننِس مٲلِس سٍتـ̡ وُچھمُت چُھ۔\n39.\\tتِمو دِژ جواب تہٕ وونُن زِ ابراہیم چُھ سون مول۔ عیسیٰ مسیح چُھ تِمن ونان زِ اگر تم ابراہیم سٕندِ شُرۍ ٲسِو، تہٕ تم کٔرِو ابراہیم سٕنز کٲم کٔرِتھ۔\n40.\\tمگر وۅنۍ چُھہ ژیہ میہ مارُن یژھان، یُس ژیہ پزر ووٚنمُت چُھ، یُس میہ خدایہ سٍتـ̡ بوزمُت چُھ، یہِ اوس نہٕ ابراہیم سٍتـ̡ ۔\n41.\\tتُہۍ چھِو پننِس مٲلہِ سٕندِ اعمال کران۔ اَمہِ پتہٕ ووٚن تِمو أمِس زَن، أسۍ چھِنہٕ زناکاری سٍتـ̡ پٲدٕ سپدان۔ اسہِ چُھ اکھ مول، {حتیٰ کہ} خدا۔\n42. عیسیٰ علیہ السلام ووٚن تِمن زِ اگر خدا تُہند مول آسہِ، تہٕ تُہۍ کٔرِو میہ محبت، کیازِ بہٕ ووت خدایہِ سٕندِ طرفہٕ برونہہ کُن۔ نہ اوس میہ پانس سیتۍ آمت، مگر تمۍ سوز میہ ۔\n43.\\tژیہ کیازِ چھہ نہ میون کلام سمجھان؟ {حتیٰ کہ} کیازِ ژے ہیکو نہ میون کلام بوزان۔\n44.\\tتُہۍ چھِو پننِس مٲلہِ سٕندِس شیطانس سٍتـ̡ تہٕ پننِس مٲلہِ سٕنزِ ہوس سٍتـ̡ کٔرِو۔ سُہ اوس شروع پیٹھے اکھ قاتل، تہٕ حقیقتس منز اوس نہٕ روزان، تکیازِ تس منز چھُنہٕ کانہہ حقیقت۔ ییلہ سُہ اپُز ونان چُھ، سُہ چُھ پنُن کتھ کران: کیازِ سُہ چُھ اپُز تہٕ امیُک مول۔ {پنن پنُن: یا، پننہٕ مرضی یا مزازٕ سۭتۍ}\n45.\\tتہٕ کیازِ بہٕ چُھس پزر ونان چھُس، تۅہہ چھُنہٕ میہ پژھ کران۔\n46.\\tژیہ منزٕ کُس چُھہ میہ گۅنہہ ہُند قایل؟ تہٕ اگر بہٕ پٔز ونان چھُس، تیٚلہِ کیازِ چھُنہٕ ژےٚ میانہِ پیٹھ پژھ کران؟\n47. یُس خدایہِ سٕندِ طرفہٕ چُھہ سُہ چُھہ خدایہِ سٕنز کتھ بوزان تہٕ تێلہِ چُھہ نہٕ تِمن ہٕندِ کُن بوزان، کیازِکہِ تُہۍ چُھہ نہٕ خدایہِ سٕندِ سٍتـ̡ ۔\n48.\\tپتہٕ دیُت یہودین جواب تہٕ وونُن أمِس زِ أسۍ چھِنہٕ اصل پٲٹھۍ ونان زِ تہٕ تہٕ چُھکھ شیطان؟\n49. عیسیٰ علیہ السلام دیُت جواب، میہ چُھ نہٕ کانہہ شیطان۔ مگر بہٕ چُھس پننِس مٲلِس عزت کران، تہٕ ژے چھِو مےٚ بے عزتی کران۔\n50. تہٕ بہٕ چُھس نہٕ پنُن جلال ژھاران: سُہ چُھ یُس ژھاران تہٕ فیصلہ کران چُھ۔\n51. پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ اگر کانہہ انسان میانہِ کتھہِ پیٹھ عمل کرِ، سُہ گژھہِ نہٕ زانہہ مرُن۔\n52.\\tاَمہِ پتہٕ ووٚن یہودیو أمِس زِ وۅنۍ چھُ اسہِ پتاہ زِ ژے چُھکھ اکھ شیطان۔ ابراہیم تہٕ پیغمبرن ہُند مُرد۔ تہٕ ژے چھُکھ ونان زِ اگر کانہہ انسان میانہِ کتھہِ پیٹھ عمل کرِ، تس گژھہِ نہ زانہہ موتُک مزہ چکھ۔\n53. کیا تُہۍ چھُکھ سٲنِس مٲلِس ابراہیم سٕندِ کھۅتہٕ بوڈ یُس موٗدمُت چھُ؟ تہٕ پیغمبرن چھِ مٔرۍمٕتۍ: کُس چُھکھ پان بناوان؟\n54. عیسیٰ مسیحن دیُت جواب، یێلہِ بہٕ پانس عزت دِوان چُھس، میون عزت چُھہ نہٕ کانہہ تہِ: یہ چُھہ میون مول یُس میہ عزت کران چُھ۔ یٔمِس متعلق تُہۍ ونان چھِو زِ سُہ چُھ تُہند خدا:\n55.\\tتوتہِ چُھہ نہٕ تس زانان۔ مگر بہٕ چھُس تس زانان: تہٕ اگر بہٕ یہ ونُن، بہٕ چھُس نہٕ تس زانان، بہٕ روزٕ ژےٚ ہیوٗ اپُز، مگر بہٕ چھُس تس زانان، تہٕ تٔمۍ سٕنز کتھ تھاوان چھُس۔\n56.\\tتُہند مول ابراہیم گۆو میون دۅہ وُچھِتھ خۅش۔\n57.\\tتَمہِ پتہٕ ووٚن یہودیو أمِس زِ ژٕ چھُکھ نہٕ وُنہِ پنژاہ وُہُر وٲنسہِ، تہٕ کیا ژے چھُے ابراہیم وُچھمُت؟\n58.\\tحضرت عیسیٰ علیہ السلام ووٚن تِمن وۆن، پٔزۍ پٲٹھۍ، بہٕ چُھس تہِ ونان، ابراہیم سٕندِ برونہہ تہٕ بہٕ چُھس۔\n59.\\tتێلہِ تُل تِمو أمِس کُن لگاونہٕ خٲطرٕ کَنہِ کٔرِتھ، مگر عیسیٰ علیہ السلام ژوٗرِ تہٕ ژاو مندرٕ منزٕ نٮ۪بر، یِمن منزٕ گٔژِھتھ تہٕ یِتھٕ پٲٹھـ̡ گٔیہِ۔","1.\\tتہٕ ییلہ {عیسیٰ} پکان پیوٚو، تٔمۍ وُچھ اکھ انسان یُس زینہٕ پیٹھے اوٚن اوس۔\n2.\\tتہٕ تٔمۍ سٕندٮ۪و شٲگِرَو پرژھ أمِس زِ آقا، کُس اوس گۅناہ کورمُت، أمِس شخٕص یا تٔمۍ سٕندِس مٲلِس ماجہ زِ سُہ چُھ انہٕ زامُت؟\n3.\\tحضرت عیسیٰ علیہ السلام دیت جواب، نہ چھہ أمس انسانس تہٕ نہ تس مٲلس ماجہ گۅناہ کورمُت، بلکہ گژھہِ خدایہ سٕنز کٲم تس منز ظٲہر سپدٕنۍ۔\n4. میہ پزِ تمہِ سٕنزِ کامہِ کٲم کرٕنۍ یُس میہ سوزمُت چھُ، یێلہِ دۅہ آسہِ: رٲژ چھِ یِوان، یێلہِ نہٕ کانہہ انسان کٲم ہیکہِ کٔرِتھ۔\n5. یوتام بہٕ دُنیاہس منز چُھس، بہٕ چُھس دنیاہُک گاش۔\n6.\\tییلہ تٔمۍ یتھہ پاٹھۍ کتھ کٔر، تمٔۍ تھووُن زمینس پیٹھ، تہٕ تھوکُن میژِ سٍتـ̡ میژِ سٍتـ̡ مسح کٔرِتھ، {مسح کٔرِتھ...: یا پھٔہلٲوِن میژِ ہٕنزِ اچھن پیٹھ}\n7.\\tتہٕ وونُن زِ گژھ سیلوم کِس تالابس مَنٛز واش کرُن، (یُس تشریح مطٲبق سوزنہٕ آمُت چھُ۔) تَمہِ کِنۍ گوٚو سُہ پننہِ وتہِ تہٕ واش کٔرِتھ آو وُچھان۔\n8.\\tہمسایہ تہ یمو امہ برونہہ أمس وچھمت اوس زِ سہ چھہ انہِ گوٚن، ووٚن زِ یہ چھہ نہ سہ یُس بِہتھ منگان اوس۔\n9.\\tکینژو وۆن، یہ چھہ یہ: باقیو {وۆن}، سہ چھہ امس ہیو :{مگر} ووٚن میہ چھہ {سہ}۔\n10.\\tتَمہِ کِنۍ ووٚن تِمو أمِس کِتھہٕ کٔنۍ گٔیہِ تۅہہِ أچھ یَلہٕ؟\n11.\\tتٔمۍ دیُت جواب تہٕ وونُن، یُس عیسیٰ مسیح ونان چھِ، تٔمۍ بنٲو میژِ تہٕ میانہِ أچھ مسح کٔرِتھ وونُن، تہٕ وونُس سیلوم کِس تالابس کُن گژھ تہٕ واش کرُن، تہٕ بہٕ گٔیہٕ واش تہٕ واش کٔرٕن، تہٕ بہٕ گۆو واش تہٕ واش کٔرٕن، تہٕ بہٕ گٔیہِ واش تہٕ واش کٔرِتھ۔\n12.\\tتِمو ووٚن أمِس کَتہِ چھُ؟ تمۍ ووٚن میہ چھیہ نہ خبر۔\n13.\\tتِمو اوٚن فریسیَن نِش یُس برونہہ کُن انہِ گوٚو۔\n14. تہٕ سبت دۅہ اوس عیسیٰ علیہ السلام میژِ بنیوو، تہٕ أچھ کھولٕنـ̡ ۔\n15.\\tبییہِ وُچھِتھ فریسیو تہِ پرژھ أمِس گاش کِتھہ پٲٹھۍ۔ تٔمۍ ووٚن تِمن میژِ میژِ میانٮ۪ن أچھن پیٹھ، تہٕ بہٕ واش کٔرِتھ وُچھمُت۔\n16. تَمہِ کِنۍ چُھ کینہہ فریسیو ووٚنمُت، یہِ انسان چُھنہٕ خدایہِ سُند دۅہہ، کیازِ سُہ چُھہ نہٕ سبت دۅہ تھاوان۔ باقیو ووٚن زِ اکھ گۅنہگار انسان کِتھ کٔنۍ ہیکہِ یِتھۍ معجزات کٔرِتھ؟ تہٕ تمن درمیان ٲس اکھ تقسیم۔\n17.\\tتِم چھہِ انہِ شخصس بییہ ونان زِ تۅہہ کیا چُھہ تس متعلق ونان زِ تمۍ چھیہ تہنز اچھ کھولمژ۔ تم فرماو، تم چھ پیغمبر۔\n18.\\tمگر یہودی اوس نہٕ أمِس مُتعلِق یقین زِ سُہ اوس اوٚن گومُت، تہٕ تٔمۍ سٕندِس مٲلِس ماجہ بُلٲوِتھ یُس تٔمِس گاش اوس دِنہٕ آمُت۔\n19.\\tتہٕ تِمو پرژھ تِمَن زِ یہِ چھا تُہند نیچو، یُس تُہۍ ونان چھُو انہٕ زامُت؟ تیلہِ کتھہ پاٹھۍ چھہ سہ وچھان؟\n20.\\tتٔمۍ سٕندِس مٲلِس ماجہ دِژ تِمن جواب تہٕ وونُن زِ اسہِ چھُ پتاہ زِ یہِ چُھ سون نیچو، تہٕ سُہ اوس انہٕ زامُت۔\n21.\\tمگر سہ کمہِ ذریعہ وُچھان چھُ، اسہِ چھیہ نہ خبر۔ یا کُس چھُ أچھ کھولمُت، اسہِ چھُنہٕ پتاہ زِ سُہ چھُ وٲنسہِ وٲنسہِ؛ أمِس پرژھو: سُہ کرِ پننہِ خٲطرٕ کتھ کرنہٕ۔\n22.\\tیِمو کٔر تٔمۍ سٕندِس مٲلِس ماجہ سٍتـ̡ تکیازِ تِم ٲسۍ یہودین کھوژان، تکیازِ یہودی اوس گۅڈے اتفاق کورمُت زِ یێلہِ کانہہ انسان اقرار کرِ زِ سُہ چُھ مسیح چُھ، سُہ گژھہِ یہودی عبادت خانہٕ منزٕ نیبر کڈنہٕ یُن۔\n23.\\tتَمہِ کِنۍ ووٚن تٔمۍ سٕندِس مٲلِس ماجہ سُہ وٲنسہِ۔ أمِس پرٛیٚژھِو.\n24.\\tاَمہ پتہٕ وُنُن تِمو دُبارٕ انہِ شخٕص یُس انہِ اوس، تہٕ وونُن خدایہ سُند تعریف، أسۍ چھِ پتاہ زِ یہِ انسان چُھ گۅنہگار۔\n25.\\tتٔمۍ دیُت جواب تہٕ وونُن، کیا سُہ گۅنہگار آسہِ یا نہٕ، بہٕ چھُس نہٕ پتاہ: اکھ کتھ چھیہ میہ پتاہ زِ ییلہ بہٕ انہِ اوسس، وُنۍ چھُس وُچھان۔\n26. اَمہ پتہٕ ووٚن تِمو دُبارٕ أمِس دُبارٕ ، تٔمِس کیا کوٚر تۅہہِ سٍتـ̡ ؟ تمۍ کتھہ پاٹھۍ چھیہ چانۍ اچھ کھولمژ۔\n27.\\tتٔمۍ دِژ تِمن جواب، مے چُھہ ژیہ گۅڈے وَننہٕ آمُت، تہٕ ژے بوز نہٕ: ژیہ کیازِ بوزِو دُبارٕ؟ کیا تُہۍ تہِ ٲسِو تٔمۍ سٕندِ شٲگِرِد؟\n28.\\tاَمہِ پتہٕ کٔر تِمو أمِس طعنہ دِتھ تہٕ وونُن، تہٕ وَنُن تُہۍ چھُکھ تٔمِس شٲگِرِ۔ مگر أسۍ چھِ موسیٰ سٕندِ شٲگِرِد۔\n29.\\tاسہِ چھیہ پتاہ زِ خداین چھہ موسیٰ ہس سیتۍ کتھ کٔرمٕژ: اسہِ چھیہ نہ پتاہ زِ سُہ کتہِ پیٹھہ چھُ۔\n30.\\tمردس دیت جواب تہ وونُن تمن زِ اتھ منز کیازِ چھہ اکھ حیرت انگیز چیز، یُس نہ ژیہ پتاہ چھہ سہ کتہِ پیٹھہ آمت، تہٕ {توتہِ} چھہ تمۍ میانہِ اچھ کھولمژ۔\n31. وۅنۍ چُھہ اسہِ پتاہ زِ خدا چُھہ نہٕ گۅنہگارن بوزان مگر یێلہِ کانہہ انسان خدا سُند عبادت کرُن آسہِ تہٕ پنٕنۍ مرضی کران چُھ، سُہ چُھ بوزان۔\n32.\\tینہ پیٹھہ دنیا شروع گوو، یہ بوز نہ زِ کٲنسہِ انسانس چھہ انہِ زینہِ وٲلس اچھ کھولمت۔\n33.\\tاگر یہ انسان خدایہ سُند آسہِ نہ، سُہ ہیکہِ نہٕ کینہہ تہِ کٔرِتھ۔\n34.\\tتِمو دِژ جواب تہٕ وونُن أمِس زِ ژے چھُکھ گۅنہٕ گۅنہٕ سٍتـ̡ پٲدٕ گومُت، تہٕ ژٕ چھُکھ اسہِ ہیچھناوُن؟ تہٕ تِمو کٔر سُہ کڑنہٕ۔ {کاسٹ...: یا، کٔرِتھ کٔرِتھ کٔرِتھ}\n35.\\tحضرت عیسیٰ علیہ السلام بوز زِ تمو کٔر سُہ کٔڈِتھ کڈنہٕ۔ تہٕ ییلہ أمس لٔبِتھ، تٔمۍ ووٚن أمِس زِ کیا تُہۍ چھوا خدایہ سٕندِس نیٚچوِس پیٹھ یقین تھاوان؟\n36.\\tتٔمۍ دیُت جواب تہٕ وونُن، سُہ کُس چُھ، خداوند، یُس بہٕ ہێکہٕ تس پیٹھ یقین کرُن؟\n37. تہٕ حضرت عیسیٰ علیہ السلام ووٚن تٔمِس زِ ژے چھے أمِس وُچھمٕژ، تہٕ سُہ چُھ توے سٍتـ̡ کتھ کران۔\n38. تہٕ تٔمۍ ووٚن، خداوند، بہٕ چُھس یقین تھاوان۔ تہٕ سُہ اوس أمِس پوٗزا کران۔\n39. تہٕ عیسیٰ علیہ السلام ووٚن، فیصلہٕ خٲطرٕ چُھس بہٕ یتھ دنیاہس مَنٛز آمُت، یُس نہٕ وُچھان چُھ، تِم گژھن وُچھن؛ تہٕ یُس وُچھان چھُ تِم گژھن انہِ گٔژھِتھ۔\n40.\\tتہٕ یِمو فریسیو یِمو أمِس سٍتـ̡ ٲس، بوز یِم لفظ تہٕ وونُن زِ أسۍ تہِ چھَا انہٕ گٔمٕتۍ؟\n41.\\tحضرت عیسیٰ علیہ السلام ووٚن تِمن زِ یێلہِ تہِ انہِ گۅناہ آسہِ، تێلہِ گژھہِ نہٕ کانہہ گۅناہ سپدُن، مگر وۅنۍ چُھہ تُہۍ ونان زِ أسـ̡ وُچھان۔ تَمہِ کِنۍ چُھ تُہند گۅناہ باقی۔","1. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ یُس نہٕ دروازٕ کِنۍ کۅکرِ ہٕندِس کھورِ منز اژان چُھ، سُہ چُھ ژور تہٕ ڈاکو ۔\n2. مگر یُس دروازٕ کِنۍ اژان چُھ، سُہ چُھ دانٛد ہُند چرواہ۔\n3.\\tأمِس خٲطرٕ چھُ قلی کھولان۔ تہٕ دانٛد چُھ تٔمۍ سٕنز آواز بوزان: تہٕ سُہ چُھ پنٕنـ̡ دانٛدن ناوٕ سٍتـ̡ بلاوان، تہٕ چُھہ تِمن نٮ۪بر نیران۔\n4.\\tییلہ سُہ پَنُن کۅکر کڈان چُھ، سُہ چُھ تِمن برونہہ کُن نیران، تہٕ کۅکرٕ چھِ أمِس پَتہٕ پَتہٕ نیران، تکیازِ تِم چھِ تٔمۍ سٕنز آواز زانان۔\n5.\\tتہٕ أکِس اجنبی سٍتـ̡ گژھن نہٕ تِم پَتہٕ پٲٹھۍ، بٔلکہِ ژٔلِن أمِس نِش، تِکیازِ تِم چھِنہٕ اَپرن ہٕنز آواز زانان۔\n6.\\tعیسیٰ علیہ السلامن کٔر تِمن سٍتـ̡ کتھ کرنہٕ آمٕژ۔\n7. اَمہِ پَتہٕ ووٚن عیسیٰ علیہ السلام تِمن دُبارٕ دُبارٕ وَنُن، پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ وَنُن، بہٕ چُھس کۅکرِ ہُند دروازٕ۔\n8.\\tیُس میہ برونہہ کنہِ آمُت چھُ، تم چھہِ ژور تہٕ ڈاکو: مگر کۅکرِ بوز نہٕ۔\n9. بہٕ چُھس دروازٕ: میانہِ ذریعہٕ یێلہِ کانٛہہ تہِ انسان اژِ، سُہ گژھہِ بچاونہٕ تہٕ اژِتھ نیرِتھ تہٕ مرگہٕ ژھانڈنہٕ۔\n10. چور چُھ نہٕ یِوان، مگر ژوٗرِ نِنہٕ خٲطرٕ، مارنہٕ خٲطرٕ، تہٕ تباہ کرنہٕ خٲطرٕ: بہٕ چُھس آمُت زِ تِمن ہٕندِ زندگی حٲصل کرنہٕ خٲطرٕ، تہٕ تِمن ہٕندِس زیادٕ سٍتـ̡ حٲصل کرنہٕ خٲطرٕ۔\n11. بہٕ چُھس نیک چرواہ آسان: نیک چرواہ چُھ پَنُن جان دِوان۔\n12.\\tمگر یُس کرایہ دار چُھ، تہٕ یُس کۅکرِ آسہِ نہٕ، سُہ چُھ رامہٕ ہُند یِوان وُچھان، تہٕ کۅکرِ تراوان تہٕ ژٔلِتھ ژلان۔\n13.\\tکرایہ دار چھُ، تکیازِ سُہ چُھ کرایہ دار، تہٕ سُہ چُھس نہٕ کۅکرِ ہُند خیال تھاوان۔\n14.\\tبہٕ چُھس نیک چرواہ تہٕ پنُن {کۅکر} زانان تہٕ بہٕ چُھس پنُن زانان۔\n15. یێلہِ پٲٹھـ̡ چُھہ میہ زانان تہٕ بہٕ چُھس مٲلِس سٍتـ̡ زانان: تہٕ بہٕ چُھس پَنُن زُو دِنہٕ خٲطرٕ دِوان۔\n16.\\tتہٕ باقٕے کۅکرِ یِم نہٕ اَتھ گٔژھِتھ چھِ، تِم تہِ چھِس اَنُن، تہٕ تِم بوزن میٲنۍ آواز۔ تہٕ اَکھ گٔژھ آسہِ، {تہٕ} اکھ چرواہ۔\n17. تێمہِ کِنۍ چُھس میون مول میہ محبت کران، تکیازِ بہٕ چُھس پنُن زُو دِوان، یُتھ بہٕ دُبارٕ نِتھ۔\n18.\\tکانہہ تہِ انسان چھہ نہ یہ میانہِ نِش نِش نِتھ، مگر بہٕ چھُس یہ پانس نِش تراوان۔ میہ چھہ یہ تراونک طاقت، تہ میہ چھہ یہ بییہ نِنُک طاقت۔ یہ حکم چھہ میہ پننس مٲلس سٍتـ̡ میلان۔\n19. تَمہِ مۄکھٕ گۆو یہودین مَنٛز یِمن کَتھن خٲطرٕ دُبارٕ تقسیم۔\n20.\\tتہٕ یِمو مَنٛز چھُ واریاہو وَنُن زِ أمِس چُھ شیطان تہٕ پاگل چُھ۔ ژیہ کیازِ بوزان چھُو؟\n21.\\tباقیو ووٚن زِ یِم چھِنہٕ شیطان سٕندِ کلام۔ کیا شیطان ہیکہِ انہِ سٕنزِ أچھ کھولِتھ؟\n22.\\tتہٕ یروشلمس منز اوس وقف کرنُک عید تہٕ یہ اوس وند۔\n23. تہٕ عیسیٰ مسیح پوٚک سلیمان سٕندِس دٲرس مَنٛز مندرس مَنٛز۔\n24.\\tاَمہِ پتہٕ آیہِ یہودی أمِس اندۍ پکھۍ تہٕ وونُن زِ ژے کٲتِس کالس چُھکھ اسہِ شک کران؟ یێلہِ تُہۍ مسیح چھِو، تیلہِ وَنُن سیدِ سیدِ سٍتـ̡ ۔ {بناو...: یا، اسہِ تھپھ کٔرِو سسپنس منز}\n25. عیسیٰ مسیحن دیت تمن جواب، میہ ووٚن ژےٚ، تہٕ تہٕ تم چُھہ نہٕ یقین کران: یُس کٲم بہٕ پننِس مٲلہِ سٕندِ ناوٕ سٍتـ̡ کران چُھ، تِم چِھ میانہِ سٍتـ̡ گوٲہی دِوان۔\n26. مگر تہۍ چھِو نہٕ یقین کران، تکیازِ تہۍ چھِو نہٕ میانہِ کۅکرِ سٍتـ̡ یُس میہ ژے ووٚنمُت چُھ۔\n27.\\tمیانہِ کۅکرِ چھیہ میٲنۍ آواز بوزان، تہٕ بہٕ چھُس تِمن زانان تہٕ تِم چھِ میانہِ پٲٹھۍ:\n28. تہٕ بہٕ چُھس تِمن ابدی زندگی دِوان۔ تہٕ تِم گژھن نہٕ زانہہ ختم گژھن، تہٕ نہ کُنہِ تہِ {انسان} تِم میانہِ اتھہٕ نِش نِنہٕ۔\n29.\\tمیون مول، یمۍ میہ دِژمُت، سُہ چُھ سارِوٕے کھۄتہٕ بوڈ ۔ تہٕ کانہہ تہِ {انسان} ہیکہِ نہٕ میٲنس مٲلہِ سٕندِ اتھہٕ منزٕ {تِم} کٔڈِتھ۔\n30. میہ تہٕ {میانۍ} مول چھہِ اکھ۔\n31.\\tپتہٕ تُل یہودی بییہِ کنہِ کٔنہِ۔\n32. حضرت عیسیٰ علیہ السلام دِیُت تِمن جواب، میہ ہٲومٕژ واریاہ اصل کامہِ چھے میہ پننِس مٲلہِ سٕندِ طرفہٕ ہٲومٕژ۔ یِمو منزٕ کمہِ کامہِ خٲطرٕ چُھکھ ژیہ میہ سنگسار کران؟\n33.\\tیہودیو دیُت أمِس جواب دِتھ زِ اصل کامہِ خٲطرٕ چُھہ نہٕ أسۍ ژے کٔنہِ کٔرِتھ۔ مگر توہین مذہب خٲطرٕ؛ تہٕ کیازِ زِ تُہۍ چھِو انسان آسنہٕ کِنۍ پنُن پان خدا بناوان۔\n34.\\tحضرت عیسیٰ علیہ السلام دیت تمن جواب، کیا یہ چُھہ نہٕ چانہِ شریعتس منز لیکھنہٕ آمُت، میہ ووٚن، تہۍ چھو خدا؟\n35. یێلہِ سُہ تِمن دیوتا وَنُن، یێمہِ سٍتـ̡ خدایہِ سُند کلام آو تہٕ صحیفہٕ ہیکہِ نہٕ پھُٹرٲوِتھ۔\n36. یُس مٲلۍ صٲبن پاک کورمُت تہٕ دُنیاہس مَنٛز سوزمُت چھُ، تٔمِس مُتعلِق ؤنِو تہٕ کفر کٔرِو۔ کیازِ میہ ووٚن، بہٕ چُھس خدایہ سُند نیٚچُو؟\n37.\\tاگر بہٕ پننِس مٲلہِ سٕنزِ کٲم کرِ، تیلہِ گژھہِ نہٕ میانہِ کامہِ پیٹھ یقین کرنہٕ۔\n38. مگر یێلہِ بہٕ تہٕ یێلہِ تہٕ تہٕ یێلہِ\n39.\\tتێلہِ کٔر تِمو دُبارٕ أمِس نِنٕچ کوٗشش، مگر سُہ ژوٚل تِہٕندِ اتھہٕ نِش نِش،\n40. تہٕ گۆو اردن اپارِ تتھ جایہِ ییتہِ یوحنا گۅڈنچہ لٹہِ بپتسمہ دِژمُت۔ تہٕ تتہِ روٗد سُہ روزان۔\n41.\\tتہٕ واریاہو لٔگۍ أمِس سٍتـ̡ یُس یوحنا أمِس شخصس سٍتـ̡ کتھ کٔرمٕژ ٲس، سٍتـ̡ ٲس پٔزۍ۔\n42.\\tتہٕ واریاہ لوٗکھ تٔمِس پیٹھ یقین تھاوان۔","1.\\tوۅنۍ اوس اکھ {انسان} بیمار، {ناو} لازارس، یُس مریم تہٕ تسٕنزِ بینہِ مارتھا ہُند شہر اوس۔\n2. (یہِ ٲس مریم یٔمۍ خداوند سٕندِس مرہم سٍتـ̡ مسح کٔرِتھ، تہٕ تٔمۍ سٕندِس کھۅر پننِس مَس سٍتـ̡ صاف کٔرِتھ، یێمہِ سُند بوے لازارس بیمار اوس۔)\n3. تَمہِ کِنۍ سوز تٔمۍ سٕنزِ بینہِ أمِس نِش یہِ ونان زِ خداوند، یُس تُہۍ محبت کران چُھ، سُہ چُھ بیمار۔\n4. یێلہِ حضرت عیسیٰ علیہ السلام بوٗز، تٔمۍ ووٚن زِ یہِ بٮ۪مار چُھنہٕ موتس تام، بٔلکہِ خدایہِ سٕندِ جلال خٲطرٕ، یُتھ خدایہِ سُند فرزند یێمہِ سٍتـ̡ جلال سپدِ۔\n5. وۅنۍ اوس عیسیٰ مسیح مارتھا تہٕ تسٕنزِ بینہِ تہٕ لزارس سٍتـ̡ محبت کران۔\n6.\\tییلہ تس یہ بوز زِ سُہ چُھ بیمار، سُہ روٗد دۅن دۅہن تتھۍ جایہ ییتہِ سُہ اوس۔\n7.\\tامہ پتہ چھہ سہ پننین شاگردن ونان زِ اسۍ گژھو بییہ یہوداہس منز۔\n8.\\tتٔمۍ سٕندِس مرید چھِ أمِس ونان زِ آقاہ، یہودی کٔر تۅہہِ کٔنہِ پتھرِ مارنٕچ کوشش۔ تہٕ کیا ژٕ چُھکھ دُبارٕ تتہِ نیران؟\n9. حضرت عیسیٰ علیہ السلام دیُت جواب، کیا چُھنہٕ دوہس منز باہ گھنٹہٕ آسان؟ یێلہِ کانہہ انسان دۅہس پکان چُھ، سُہ چُھنہٕ ٹھوکر کھسان، تکیازِ سُہ چُھ یتھ دنیاہُک گاش وُچھان۔\n10.\\tمگر اگر کانہہ انسان رٲژ پکان چُھ، سُہ چُھ ٹھوکر کھسان، تکیازِ تس منز چُھنہٕ کانہہ گاش۔\n11.\\tیِمو کتھہٕ وۆن: تہٕ تمہ پتہ چُھ سُہ تِمن ونان زِ سٲنـ̡ یار لعزر چُھ شوٚنگان۔ مگر بہٕ چھُس نیران، تاکہ بہٕ ہیوٚک تس نندر نِش بیدار کٔرتھ۔\n12. اَمہِ پتہٕ ووٚن تٔمۍ سٕنٛدٮ۪و شٲگِر، خداوند، اگر سُہ شوٚنگِتھ آسہِ، سُہ کرِ رژھ رژھ۔\n13.\\tعیسیٰ علیہ السلام اوس پننہِ مرنٕچ کتھ کٔرمٕژ، مگر تِمو اوس خیال زِ تٔمۍ اوس نندر منز آرام کرنٕچ کتھ کٔرمٕژ۔\n14. تێمہِ وۆن عیسیٰ علیہ السلام سیدِ سیود پٲٹھۍ، لزارس چُھ موٗدمُت۔\n15. تہٕ بہٕ چُھس چانہِ خٲطرٕ خوشی زِ بہٕ اوسُس نہٕ تتہِ اوسمُت، یُس تُہۍ پژھ کٔرِتھ ہیکو۔ توتہِ گژھو أسۍ أمِس نِش۔\n16.\\tپَتہٕ ووٚن تھامس، یُس ڈیڈیمس ونان چھِ، پننین سٲتھی شاگردن ووٚن، أسۍ تہِ گژھو أمِس سٍتـ̡ مرُن۔\n17. پَتہٕ یێلہِ عیسیٰ آو تٔمِس وُچھ زِ سُہ اوس ژور دۅہہٕ قبرِ مَنٛز لوٚگمُت۔\n18.\\tوۅنۍ اوس بیت القدس نزدیک، تقریباً پندہ فرلانگ دور: {تقریبا...: یعنی تقریباً زٕ میل}\n19.\\tتہٕ واریاہ یہودی آیہِ مارتھا تہٕ مریم نِش تِمن پننِس بٲے سٍتـ̡ تسلی دِنہٕ خٲطرٕ۔\n20.\\tتمہِ پتہ ییلہ تس یہ بوٗز زِ عیسیٰ چُھ یِوان، گٔیہِ أمِس سمکھنہٕ، مگر مریم بِہتھ گٔیہِ گرس منز۔\n21.\\tاَمہِ پَتہٕ ووٚن مارتھا عیسیٰ مسیحس سٍتـ̡ خداوند، اگر ژے یتہِ آسہِ، میون بوے آسہ نہٕ مٔرِتھ۔\n22.\\tمگر میہ چھیہ پتاہ زِ وُنہِ تہِ تہِ ژیہ خدایہ سٍتـ̡ یُس تہِ منگہِ، خدا دِیہِ ژے دِیہِ۔\n23. عیسیٰ مسیح چُھ أمِس ونان زِ تُہند بٲے گژھہِ دُبارٕ زندٕ۔\n24. مارتھا چُھ أمِس ونان زِ بہٕ چُھس پتاہ زِ سُہ گژھہِ ٲخری دۅہہٕ قیامتس مَنٛز دُبارٕ زندٕ۔\n25. عیسیٰ علیہ السلام ووٚن تس زِ بہٕ چُھس قیامت، تہٕ زندگی: یُس میٲنس پیٹھ ایمان تھاوان چُھ، یودوے سُہ موٗدمُت آسہِ، توتہِ گژھہِ زندٕ:\n26. تہٕ یُس زندٕ روزِ تہٕ میانہِ پیٹھ ایمان تھاوان آسہِ سُہ گژھِ نہٕ زانہہ مرُن۔ کیا تُہۍ چھِو یہِ پژھ کٔرِتھ؟\n27. سُہ چُھہ أمِس ونان آ، خداوند: بہٕ چُھس یقین تھاوان زِ تہٕ چُھہ مسیح سُند نیچو، یُس دُنیاہس مَنٛز یُن گژھہِ۔\n28.\\tتہٕ ییلہ تٔمۍ یہِ ووٚن، سۅ گٔیہِ پننہِ وتہِ تہٕ بُلٲوٕن مریم پننہِ بینہِ ژوٗرِ پٲٹھۍ، وونُن زِ آقا آو تہٕ چُھس ژےٚ بلاوان۔\n29.\\tییلہ تس یہ بوز، سۅ ووٚتھ جلدی تہ أمس نِش آیہ۔\n30.\\tوُنہِ اوس نہٕ عیسیٰ مسیح وُنہِ شہرس مَنٛز آمُت، مگر اوس تتھ جایہِ ییتہِ مارتھا أمِس سمکھیوو۔\n31.\\tیہودی یِم أمِس سٍتـ̡ گھرس مَنٛز ٲسۍ، تہٕ ییلہ تِمو مریم وُچھ، سُہ ووٚتھ جلدی سان تہٕ نٮ۪بر نیرِتھ أمِس پَتہٕ پَتہٕ وونُن، سُہ گٔیہِ قبرِ تام وَننہٕ خٲطرٕ۔\n32.\\tتێلہِ ییلہ مریم ییتہِ عیسیٰ مسیح اوس، تہٕ تس وُچھمُت، سۅ پیوٚو تٔمِس قدمن نِش تہٕ وونُن خداوند، اگر ژے یتہِ آسہ ہا، میون بوے آسہ نہٕ مٔرِتھ۔\n33.\\tیێلہِ حضرت عیسیٰ علیہ السلام وُچھ أمِس روُن تہٕ یہودی تہِ روُن یُس أمِس سٍتـ̡ آو، تٔمِس گۆو روحس مَنٛز درٛاوُن، تہٕ گٔیہِ پریشان، {پریشان گومُت: Gr. تٔمۍ کٔر پانس پریشان}\n34.\\tتہٕ وونُن، ژے کتہِ چھُکھ دِژمُت؟ تِمو ووٚن أمِس خداوند، آ تہٕ وُچھ۔\n35. عیسیٰ علیہ السلام رووُن۔\n36.\\tاَمہِ پتہٕ ووٚن یہودی، وُچھِو أمِس کِتھہ پٲٹھۍمحبت کٔرِتھ!\n37.\\tتہِ کینژو ووٚن زِ یُس انسان انہِ ہٕنزِ أچھ کھولِتھ آسہِ نہٕ یہ انسان تہِ مرُن؟\n38. تێمہِ کِنۍ چُھ عیسیٰ مسیح پانس مَنٛز دُبارٕ قبرس کُن یوان۔ یہ ٲس اکھ گۅپھ، تہ اتھ پیٹھ اوس اکھ کن۔\n39.\\tحضرت عیسیٰ علیہ السلام ووٚن زِ کٔنہِ کٔرِو کٔنِ۔ مارتھا، یُس مٔرِتھ اوس، أمِس وَنُن چُھ، خداوند، یێمہِ وِزِ چُھ سُہ بدبودار گومُت: کیازِ سُہ چُھ ژۄن دۅہن مُردٕ گومُت۔\n40. عیسیٰ مسیح چُھ أمِس ونان زِ مے چُھہ نہٕ ژے ووٚنمُت، یێلہِ ژے یێلہِ یێلہِ پٲٹھـ̡ پٲٹھـ̡ پٲٹھـ̡ خدایہِ سُند جلال وُچھُن؟\n41.\\tتمہِ پتہ نِش تِمو کٔنہِ کٔنہِ جایہ ییتہِ مردہ دِنہٕ آمُت اوس۔ تہٕ حضرت عیسیٰ علیہ السلامن تُل أچھ تُلِتھ تہٕ وونُن، بابا، بہٕ چُھس تُہند شُکر ادا کران زِ ژے چُھہ میہ بوزمُت۔\n42. تہٕ بہٕ ٲس پتاہ زِ ژے چُھہ میہ ہمیشہٕ بوزان: مگر یِمن لُکن ہٕندِ سٍتـ̡ یِمن ہٕندِ سٍتـ̡ چُھہ میہ سٍتـ̡ یێلہِ پى۪ٹھـ̡\n43. تہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔر، تٔمۍ ووٚن بَڑِ آوازِ سٍتۍ، لزارس، نیبر کُن۔\n44.\\tتہٕ یُس موٗدمُت اوس، اتھہٕ تہٕ کھۄر قبرِ ہٕندِس پلوس سٍتـ̡ بٔنِتھ دراو تہٕ تٔمۍ سُند بُتھ اوس رومال سٍتـ̡ بٔنِتھ۔ عیسیٰ مسیح چُھ تِمن ونان زِ سُہ یلہٕ تراوُن تہٕ تراوُن۔\n45. پَتہٕ واریاہ یہودی یِم مریمس نِش آیہ، تہٕ یِم چیز عیسیٰ علیہ السلام کٔرِتھ وُچھمٕتۍ، تِمو کٔر تٔمِس پیٹھ یقین ۔\n46. مگر یِمو منزٕ گٔیہِ کینہہ فریسیَن نِش تہٕ وونُکھ عیسیٰ علیہ السلام کیا کٔرِمٕتۍ۔\n47.\\tاَمہِ پَتہٕ کٔرِکھ بٔڈۍ پادٕرین تہٕ فریسیَن اَکھ مجلس، تہٕ وونُن، أسۍ کیا چُھہ؟ تکیازِ أمِس انسان چُھ واریاہ معجزات کران۔\n48. اگر أسۍ أمِس یِتھٕ پٲٹھۍ تراو، سٲری انسان گژھن أمِس پیٹھ یقین تہٕ رومی یِن تہٕ نِن سون جاے تہٕ قوم دۄشوٕے نِنہٕ۔\n49.\\tتہٕ یِمو منزٕ اَکھ کِیافاس، یُس اَمی ؤرۍ یہِ بٔڈ پادٕرۍ اوس، ووٚن تِمن ووٚن تِمن زِ تۅہہ چھُنہٕ کانہہ تہِ پتاہ ،\n50.\\tنہ گژھہِ یہ خیال زِ یہ چھہ سانہِ خاطرہ مناسب، اکھ انسان گژھہِ لوکن ہندِ خاطرہ مرُن، تہ یہ زِ سورے قوم گژھہِ نہ ختم سپدُن۔\n51. تہٕ یہِ اوس نہٕ پانس مُتلق کتھ کٔرمٕژ، مگر تَمہِ ؤرۍ یہِ اعلیٰ پادٕرۍ آسنہٕ کِنۍ، تٔمۍ کٔر پیشن گویی زِ عیسیٰ مسیح گژھہِ تمہِ قومہٕ خٲطرٕ مرُن۔\n52. تہٕ نہ صرف تتھ قومہٕ خٲطرٕ، بلکہ سُہ گژھِ خدایہ سٕندِس اولادس منز جمع کرنہٕ یُن یُس پردٕ کُن پھٔہلِتھ آسہِ۔\n53.\\tاَمہِ دۅہہ پَتہٕ ہیوٚت تِمو اِکہٕ وٹہٕ أمِس مارنہٕ خٲطرٕ مشورٕ۔\n54. تێمہِ کِنۍ اوس نہٕ عیسیٰ مسیح یہودین مَنٛز کھلہٕ پٲٹھۍ۔ مگر اَتہِ گۆو بیابانس نکھٕ أکِس ملکس منز، افرائیم ناوٕ کِس شہرس منز، تہٕ تتہِ روٗد پننین شاگردن سٍتـ̡ جٲری۔\n55. تہٕ یہودین ہُند فسح اوس نزدیک تہٕ واریاہ گٔیہِ فسح برونہہ یروشلم تام پانس پاک کرنہٕ خٲطرٕ۔\n56.\\tتێلہِ ژھانڈ تِمو عیسیٰ سٕندِس خٲطرٕ، تہٕ یێلہِ تِم ہیکلس مَنٛز کھڑا ٲسِتھ کٔرِکھ پانہٕ وٲنِتھ کتھ کرنہٕ، تێہہ کیا خیال چُھہ زِ سُہ ییہ نہٕ عیشس مَنٛز۔\n57.\\tوۅنۍ اوس دۅشویو پادٕرین تہٕ فریسیو دِتمُت اکھ حکم زِ اگر کٲنسہِ شخصس پتاہ آسہِ سُہ کتہِ چُھ، سُہ گژھہِ ہاوُن، تہٕ تِم گژھن أمِس نِنہٕ۔","1. پَتہٕ عیسیٰ مسیح سٕندِس فسح برونہہ شیٚیہِ دۅہہٕ یُس بیتھنس مَنٛز آو، یَتھ مَنٛز لازر اوس یُس موٗدمُت اوس، یُس تٔمۍ مُردٕ پى۪ٹھہٕ زندٕ کٔرِتھ۔\n2. تتہِ بنوو تمِس شامُک کھیٛن۔ تہٕ مارتھا کٔر خدمت: مگر لعزر اوس تمن منز اکھ یُس أمس سٍتۍ میزس پیٹھ بِہتھ اوس۔\n3.\\tپتہٕ نِن مریم سُند اکھ پاؤنڈ مرہم یُس سٮ۪ٹھاہ درٛوٚگ اوس، تہٕ عیسیٰ سٕندِس کھۅر مسح کٔرِتھ کوٚرُن تٔمۍ سٕندِس مَس سٍتـ̡ تہٕ گرٕ گۆو مرہم سٍتـ̡ بٔرِتھ۔\n4. پَتہٕ چُھ تٔمۍ سُند اکھ شٲگِر، یہوداہ اسکریوٹ، یُس أمِس دھوکہٕ دِنہٕ یُن،\n5.\\tیہ مرہم کیازِ آو نہ تریہ ہتھ پینسن منز کٕننہٕ تہ غریبن دِنہٕ؟\n6.\\tیہ اوس نہ زِ تس چھہ غریبن ہنز پرواہ کران۔ مگر امہ مۅکھہ زِ سہ اوس اکھ ژور، تہ بیگ اوس، تہ اتھ منز کیا تراونہ آمت اوس۔\n7. اَمہِ پَتہٕ ووٚن عیسیٰ علیہ السلام، سُہ تراوُن تہٕ میانہِ دفن کرنہٕ کِس دۅہہٕ سٍتـ̡ چُھہ یہِ تھوومُت۔\n8.\\tغریبن ہٕندِ خٲطرٕ چُھہ ہمیشہ پانس سٍتـ̡ روزُن؛ مگر میہ چھہ نہ ہمیشہ۔\n9. تَمہِ مۄکھٕ اوس یہودی ہٕندِس واریاہن لُکن پتاہ زِ سُہ چُھ تتہِ موجود، تہٕ تِم آیہ نہٕ صرف عیسیٰ سٕندِ خٲطرٕ بلکہ یِم لزرس تہِ وُچھِتھ، یُس تٔمۍ مُردٕ منزٕ زندٕ اوس کوٚرمُت۔\n10.\\tمگر بٔڈۍ پادٕرین کٔر مشورٕ زِ تِم کرِ لزارس تہِ مارنہٕ۔\n11.\\tکیازِ تٔمۍ سٕندِ وجہ سٍتـ̡ گٔیہِ واریاہ یہودی ژٔلِتھ تہٕ عیسیٰ ہس پیٹھ پژھ پٲٹھۍ۔\n12.\\tدۆیمہِ دۅہہ یِم عیسیٰ مسیحس مَنٛز آیہ، ییلہ تِمو بوز زِ عیسیٰ مسیح چُھ یروشلم یِوان،\n13.\\tکھجور کُلٮ۪ن ہٕنزِ لنجہِ رٔٹِتھ دِژُن أمِس سمکھنہٕ خٲطرٕ، تہٕ وۆنُن ہوشنا: بابرکت چُھہ اسرٲیلُک بادشاہ یُس خداوند سٕندِ ناوٕ سٍتـ̡ یِوان چُھ۔\n14.\\tتہٕ حضرت عیسیٰ علیہ السلام ییلہ اکھ جوان گَرٕ لوٚب، بیوٹھ اَتھ پیٹھ۔ یِتھ کٔنۍ زَن یہِ لیٚکھنہٕ آمُت چھُ،\n15.\\tخوف نہ کرو سیون سنز کور: وچھ تہند بادشاہ چھہ گۅرٕ سٕندِس کۅکرس پیٹھ بِہتھ یوان۔\n16.\\tیِم چیز ٲسۍ نہٕ گۅڈٕ تٔمۍ سٕندِس شٲگِرِس سمجِتھ، مگر یێلہِ عیسیٰ علیہ السلام جلال سپُد، تێلہِ گۆو تِمن یاد زِ یِم کتھٕ ٲس أمِس سٍتـ̡ لیکھنہٕ آمٕژ، تہٕ یِمو ٲس أمِس سٍتـ̡ یِم کٲم کٔرمٕژ۔\n17. تَمہِ کِنۍ لُکھ أمِس سٍتـ̡ ییلہ تٔمۍ لزارس پننہِ قبرِ منزٕ بُلاونہٕ آمُت تہٕ سُہ مُردٕ منزٕ زندٕ کٔرِتھ دِژُن۔\n18.\\tاَمہ مۅکھہٕ لُکھ تہِ سمکھے أمِس سٍتـ̡ ، ییمہ مۅکھہ تِمو بوز زِ تٔمۍ اوس یہِ معجزہ کورمُت۔\n19.\\tفریسیو ووٚن پانہٕ پانس منز، تێہہ کِتھہ پٲٹھـ̡ چُھہ نہٕ کُنہِ چیزس پیٹھ غالب سپدان؟ وچھو دنیا چھہ تس پتہ گٔژھمت۔\n20. تہٕ تِمن مَنٛز ٲسۍ کینہہ یونانۍ یِم دعوتس مَنٛز عبادت کرنہٕ خٲطرٕ آیہ:\n21.\\tیۅہے آو فلپس نِش، یُس گلیل کِس بیت سیدہ سُند اوس، تہٕ وونُن أمِس یُس عیسیٰ مسیح وُچھِو۔\n22. فلپس آو تہٕ اینڈریوس ونان تہٕ بییہِ چُھ عیسیٰ ہس وَنان۔\n23.\\tتہٕ حضرت عیسیٰ علیہ السلام دِیُت تِمن جواب دِتھ زِ سُہ وقت آو یُس انسان سُند فرزند سُند جلال سپدُن۔\n24. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ وَنُن زِ کٕنُک مَکُل زٔمیٖنس مَنٛز پیٚیہِ تہٕ مَرُن، سُہ چُھ کُنی زَن روزان، مگر اگر یہِ مَرِ، سُہ چُھ واریاہ پھل دِوان۔\n25.\\tیُس پننہِ زندگی سٍتـ̡ محبت کرِ، سُہ گژھہِ سُہ راوُن۔ تہٕ یُس اتھ دنیاہس منز پننہِ زندگی سٍتـ̡ نفرت کرِ، سُہ تھاوِ سُہ روزِ ابدی زندگی۔\n26.\\tاگر کانہہ انسان میانہِ خدمت کرُن، سُہ گژھہِ میانہِ پتہٕ پٲٹھۍ۔ تہٕ ییتہِ بہٕ آسہِ، تتہِ آسہِ میون خادم تہِ: اگر کانہہ نفر میانہِ خدمت کرِ، سُہ کرِ {میانِس} مٲلِس عزت۔\n27.\\tوۅنۍ چھہ میون روح پریشان گومت۔ تہٕ بہٕ کیا وَنُن؟ بابا، مے بچاوُن یَتھ وقتس نِش: مگر اَمہ وجہہ خٲطرٕ ووت بہٕ یتھ وقتس تام۔\n28. بابا، پنُن ناو ہُند حمد کٔرِو۔ اَمہ پتہٕ آو اسمانہٕ پیٹھہٕ اکھ آواز، {ونان}، مے چُھ دۅشوے {یہ} جلال دِژمُت، تہٕ کرٕ بییہِ {یہ} تعریف۔\n29.\\tتَمہِ کِنۍ یِمو لُکھ یِم اَتھ سٍتـ̡ کھڑا تہٕ بوزان چُھ، وۆنُن زِ یہِ چُھ گرٛٮ۪ز: باقیو ووٚن زِ اَکھ فرشتہٕ چُھ أمِس سٍتـ̡ کتھ کٔرمٕژ۔\n30.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، یہِ آواز آیہ نہٕ میانہِ مۅکھہٕ سٍتـ̡ بلکہ تہندِ خٲطرٕ۔\n31. وۅنۍ چُھ یتھ دنیاہُک فیصلہٕ: وۅنۍ گژھہِ امہِ دنیاہُک شہزادہ کڈنہٕ یُن۔\n32. تہٕ بہٕ یێلہِ بہٕ زمینہٕ پیٹھٕ تُلنہٕ ییہِ، سارِنٕے انسانس پانس کُن پانس کُن کھینُن۔\n33.\\tیہ وونُن زِ تس کُس مرُن گژھہِ۔\n34. لوکو دیت تس جواب، اسہِ چُھ شریعت سٍتـ̡ بوزمُت زِ مسیح چُھ ہمیشہٕ روزان، تہٕ ژے کِتھہ پٲٹھـ̡ چُھہ ونان زِ انسان سُند فرزند گژھہِ تُلُن؟ یہِ انسان سُند فرزند کُس چُھ؟\n35. تێمہِ پَتہٕ ووٚن عیسیٰ علیہ السلام تِمن سٍتـ̡ گاش تہِ چُھہ توے سٍتـ̡ گاش۔ یُس گاش آسہِ، یُس تہِ گاش آسہِ، تکیازِ یُس انہِ گٹہِ منز پکان چُھ، سہ چھہ نہ پتاہ زِ سہ کوٚت کُن چُھ گژھان۔\n36.\\tییلہ تہِ گاش آسہِ، گاشس پیٹھ یقین تھاوُن، یُتھ زن تم گاشکۍ اولاد بٔنِتھ۔ یِمو کتھہٕ کٔر عیسیٰ مسیح سٕندِ کتھ تہٕ ژٔلِتھ تہٕ کورُن پان تِمن نِش ژوٗر۔\n37.\\tمگر یێلہِ تِمو تِمن برونہہ واریاہ معجزات کٔرۍمٕتۍ، توتہِ ٲسۍ نہٕ تِمو أمِس پیٹھ پژھ تھاوان۔\n38.\\tیُس عیسیٰ نبی سُند کلام گژھہِ پورٕ سپدُن، یُس تٔمۍ ووٚنمُت خداوند، کُس چُھ سانہِ کتھہِ پیٹھ یقین کورمُت؟ تہٕ خداوند سٕنز نٔر کٔمِس سٍتـ̡ ظٲہر سپٕدمٕژ؟\n39.\\tتێلہِ ہیوٚک نہٕ تِم پژھ کٔرِتھ، تکیازِ عیسیاہن ووٚن دُبارٕ،\n40.\\tتِمن ہٕنزِ أچھ انہٕ کٔرِتھ تہٕ دِل کٔرِتھ سختی کٔرِتھ۔ زِ تِم گژھن نہٕ تِمن اچھو سٍتۍ وُچھن، تہٕ نہ گژھن تِمن دِلہٕ سٍتۍ سمجُن، تہٕ بہٕ گژھن تِمن شفا دِنہٕ۔\n41.\\tیِمو کتھہٕ وون یِمن ہُند جلال وُچھِتھ تہٕ أمِس مُتلق کتھ کٔرٕنـ̡ ۔\n42.\\tبہر حال ٲسۍ اہم حکمرانن منز تہِ واریاہ لوٗکھ تس پیٹھ یقین تھاوان۔ مگر فریسیو سٍتـ̡ کٔر نہٕ تِمو اقرار کٔرِتھ، یێلہِ یِم یِن یہودی عبادت خانہٕ منزٕ نیبر کڈنہٕ:\n43.\\tتکیازِ تِم ٲسۍ خدایہ سٕندِ تعریفٕ کھوتہٕ زیادٕ انسانن ہٕنز تعریف پسند کران۔\n44. عیسیٰ علیہ السلام وۆن وۆن تہٕ وونُن، یُس میہ پیٹھ ایمان تھاوان چُھ، سُہ چُھ نہٕ میٲنس پیٹھ پژھ تھاوان بلکہ یُس میہ سوزان اوس۔\n45. تہٕ یُس میہ وُچھان چُھ، سُہ چُھ سُہ وُچھان یُس مے سوزمُت چُھ۔\n46. بہٕ چُھس دنیاہس مَنٛز گاش آمُت، یُس تہٕ یُس میہ پیٹھ ایمان تھاوان چُھ، سُہ گژھِ نہٕ انہِ گٹہِ منز روزُن۔\n47.\\tتہٕ یێلہِ کٲنسہِ انسان میانہِ کتھ بوزان تہٕ یێلہِ نہٕ یقین کرُن، بہٕ چُھس نہٕ أمِس سٍتـ̡ فیصلہ کٔرِتھ، کیازِ بہٕ چُھس نہٕ دنیاہُک فیصلہ کرنہٕ خٲطرٕ آمُت بلکہ دُنیا بچاونہٕ خٲطرٕ آمُت۔\n48.\\tیُس میہ رد کرِ، تہٕ میانہِ کلامٕ رٔٹِتھ چُھہ نہ، سُہ چُھہ أمِس سُند فیصلہ کرُن: یُس لفظ میہ وننہ چُھ، سُہ کرِ أمِس ٲخری دۅہہٕ سُند فیصلہٕ۔\n49.\\tکیازِ میہ چھیہ نہ پانس متعلق کتھ کٔرمٕژ۔ مگر یُس مٲل میہ سوزمُت اوس، تٔمۍ دِژ میہ اکھ حکم، بہٕ کیا پزِ ونُن، تہٕ بہٕ کیا پزِ کتھ کرٕنۍ۔\n50. تہٕ بہٕ چُھس پتاہ زِ تٔمۍ سُند حکم چُھ ابدی زندگی: تێمہِ کِنۍ یێلہِ تہِ بہٕ کتھ کران چُھس، یێلہِ زن مٲلن میہ ووٚنمُت، تِتھے پٲٹھـ̡ چُھس بہٕ کتھ کران۔","1. وۅنۍ ییلہ عیسیٰ مسیحس پتاہ گۆو زِ تٔمۍ سُند وق چُھ آمُت زِ سُہ گژھہِ دُنیاہس نِش مٲلِس نِش نیرُن، یُس دُنیاہس مَنٛز اوس، تٔمۍ کٔر تِمن سٍتـ̡ ٲخرس تام محبت۔\n2. تہٕ شامُک کھٲلِتھ مۄکلیوو، شیطان چُھ وۅنۍ یہوداہ اسکریوٹ سٕندِس دِلس مَنٛز دِنہٕ آمُت، یُس شمعنہٕ سُند نیچو چُھ، أمِس دھوکھہٕ دِنہٕ خٲطرٕ۔\n3. عیسیٰ مسیح یہ زانان زِ مٲلۍ سُند سورے چیز اوس پننس اتھس منز دِژمُت، تہٕ سُہ اوس خدایہ سندِ طرفہٕ آمُت، تہٕ خدایہ سٕندِ طرفہٕ گومُت۔\n4.\\tسُہ چُھ شامُک کھٮ۪نہٕ پٮ۪ٹھٕ وۅتھان تہٕ پَنٕنۍ پَنٕنۍ پَلَو ترٛٲوٕن؛ تہٕ تُل تولیہ، تہٕ لوٚگ پان بند۔\n5.\\tامہ پتہ ترووُن سُہ أکِس بیسنس مَنٛز آب تراوُن، تہٕ لوٚگُن شاگردن ہٕندِس کھۅر چھلناوُن، تہٕ تِمن تولیہٕ سٍتـ̡ صاف کرُن یُس أمِس گٔنڈِتھ اوس۔\n6. پطرس چُھ أمِس پطرس نِش یِوان، تہٕ پطرس چُھ أمِس ونان زِ خداوند، کیا ژٕ چُھکھ میٲنۍ کھۅر چھلناوان؟ {پیٹر چُھ ونان: Gr. سُہ چُھ ونان}\n7. عیسیٰ مسیحن دیُت جواب تہٕ وونُن، بہٕ کیا چُھس کران تہٕ ژے چُھہ نہٕ وُنـ̡ پتاہ۔ مگر ژیہ گژھہِ پتہٕ پتہٕ۔\n8. پطرس چُھ أمِس ونان زِ ژے کٔرِکھ نہٕ میانہِ کھۅر زانہہ چھلنہٕ۔ حضرت عیسیٰ علیہ السلام دیُت أمِس جواب، اگر بہٕ ژے چھلناوٕ نہٕ تیلہِ چُھہ نہٕ ژے میانہِ سٍتـ̡ کانہہ حصہٕ۔\n9. شمعون پطرس چُھ أمِس ونان زِ خداوند، نہ صرف میانہِ کھۅر بلکہ {میانۍ} اتھہٕ تہٕ {میانۍ} کلہٕ تہِ۔\n10. عیسیٰ مسیح چُھ أمِس ونان زِ یُس چھلنہٕ آمُت چُھ، سُہ چُھہ نہٕ پنہٕ نِس کھۅر چھلاونٕچ ضرورت، بلکہ چُھہ پرٮ۪تھ کُنہِ وِزِ صاف سُہ چُھہ، تہٕ تُہۍ چھِو صاف مگر سارِوٕے نہٕ۔\n11.\\tتکیازِ تس ٲس پتاہ زِ تس کُس کرِ دھوکھہٕ۔ تَمہِ کِنۍ ووٚن تُہۍ چھِو نہٕ سارِوٕے پاکیزٕ۔\n12.\\tتێلہِ ییلہ تٔمۍ تِہٕندِ کھۅر چھلناوُن، تہٕ پَنٕنۍ پَلَو تُلِتھ دُبارٕ بِہنہٕ آمُت، تٔمۍ ووٚن تِمن پتاہ زِ مے کیا چُھس ژےٚ کورمُت؟\n13.\\tتہٕ تُہۍ چھِو مَے آقا تہٕ رب ونان تہٕ تُہۍ چھِو اصل پٲٹھۍ۔ {تَمہِ خٲطرٕ} بہٕ چھُس۔\n14. یێلہِ بہٕ چُھس تُہٕندِس کھۅر واش کٔرِتھ۔ تہِ پزِ اکھ أکِس کھۅر چھلناوُن۔\n15.\\tکیازِ میہ دِژ ژیہ اکھ مثال، یُتھ میہ ژیہ کرُن۔\n16. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ خادم چُھ نہٕ پننِس آقا سٕندِ کھۅتہٕ بوڈ آسان۔ نہ سُہ یُس سُہ سوزنہٕ آمُت چُھ۔\n17.\\tاگر توہہِ یِم چیز زانان چھِو، تیلہِ چھِو خوش گٔژھِتھ اگر تہۍ یِم کٔرِو۔\n18.\\tبہٕ چُھس نہٕ تۅہہ سارِنٕے مُتلق کتھ کران: بہٕ چُھس پتاہ زِ مے کُس چُھس چُھہ ژٲرمُت، مگر صحیفہٕ پوٗرٕ گژھنہٕ مۅکھہٕ یُس میانہِ سٍتـ̡ روٹی کھیوان چُھ، سُہ چُھس میٲنس خلاف کھورِ تُلِتھ ۔\n19.\\tوۅنۍ چُھس بہٕ ژے وَننہٕ برونہہ زِ ییلہ یہ سپدِ، تۅہہ گژھہِ یقین کرُن زِ بہٕ چُھس {سُہ}۔ {ونہِ: یا، از پیٹھ}\n20. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ یُس بہٕ سوزان چُھس سُہ چُھس رٔٹان۔ تہٕ یُس میہ وصول کران چُھ، سُہ چُھ سُہ وصول کران یُس مے سوزان چُھ۔\n21.\\tیێلہِ عیسیٰ علیہ السلام یێلہِ ووٚنمُت، سُہ گۆو روحس منز پریشان، تہٕ گوٲہی دِژٕن، تہٕ وونُن، پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ ژے منزٕ اکھ کرِ میہ دھوکہٕ۔\n22.\\tاَمہِ پَتہٕ گٔیہِ شٲگِرِ اَکھ أکِس کُن نظر، شَکھ کٔرِتھ زِ أمِس کُس اوس کتھ کٔرمٕژ۔\n23. وُنہِ اوس عیسیٰ سٕندِس سینس پیٹھ اکھ شٲگِر، یُس عیسیٰ سٕندِس محبتس سٍتـ̡ محبت کران اوس۔\n24.\\tشمعون پطرس کٔر أمِس اشارٕ، زِ سُہ گژھہِ پرژھُن زِ یہِ کُس کُس آسہِ۔\n25.\\tسُہ چُھ عیسیٰ سٕندِس سینس پیٹھ لٔگِتھ أمِس ونان زِ خداوند، یہِ کُس چُھ؟\n26.\\tحضرت عیسیٰ علیہ السلام دیُت جواب، سُہ چُھہ یێمِس سٍتـ̡ بہٕ دِیہٕ سُہ دِنہٕ، یێلہِ بہٕ چُھس دِنہٕ آمُت۔ تہٕ ییلہ تٔمۍ سُہ سوپ ڈبٲو، تٔمۍ دِژ یہوداہ اسکریوتس {یہِ} یُس شمعون سُند نیچو اوس۔ {سوپ: یا، مورسل}\n27. تہٕ سوپ پَتہٕ آو شیطان أمِس مَنٛز دٲخل۔ اَمہِ پَتہٕ ووٚن عیسیٰ علیہ السلامن أمِس زِ ژے کرُن، جلدی کرُن۔\n28.\\tوۅنۍ اوس نہ ٹیبلس پیٹھ موجود کٲنسہ نفرس خبر زِ سہ کمہِ ارادہ کنۍ اوس تس یہ کتھ کران۔\n29.\\tکینژَن ہٕندِس خیالس منز، کیازِ یہوداہ سُند بیگ اوس، حضرت عیسیٰ علیہ السلام اوس أمِس ووٚنمُت، تِم چیز ہییِو یِم اسہِ دعوتس مۅکھہٕ ضروُرت چھِ۔ یا یہ زِ سُہ پزِ غریبن کینہہ دِنہٕ۔\n30.\\tامہ پتہ دوٚپ دِتھ ژاو فوراً نیبر: تہٕ رٲژ ٲس۔\n31. تێمہِ وِزِ ییلہ سُہ نیبر نیرِ، حضرت عیسیٰ علیہ السلام وۆن، وۆنُن چُھ انسان سُند فرزند جلال دِنہٕ آمُت، تہٕ خدا چُھ تس مَنٛز جلال دِنہٕ آمُت۔\n32. یێلہِ خدایہِ سٍتـ̡ تسٕندِس\n33.\\tلۅکٹۍ شُرۍ، توتہِ چھُس ژے سٍتـ̡ تہٕ یِتھ کٔنۍ میہ یہودین ووٚنمُت، ییتہِ بہٕ گژھُس، تہٕ یێلہِ نہٕ یِتھ۔ لہذا چھُس وۅنۍ بہٕ ژےٚ وَنان۔\n34. بہٕ چُھس اکھ نۆو حکم دِوان زِ تُہۍ کرو اکھ أکِس محبت۔ یِتھ کٔنۍ مے چُھس ژے محبت کٔرمٕژ، تہٕ تہٕ چُھکھ اکھ أکِس محبت۔\n35.\\tاَمہِ سٍتـ̡ گژھہِ سارِنٕے {انسان} پتاہ زِ تُہۍ چھِو میٲنۍ شٲگِر، یێلہِ تہٕ یێلہِ تہٕ اَکھ أکِس سٍتـ̡ محبت چھِو۔\n36.\\tشمعون پطرس ووٚن أمِس خداوند، کوٚت کوٚت چُھہ؟ عیسیٰ مسیحن دیُت أمِس جواب، ییتہِ بہٕ گژھُس، تہٕ ژٕ ہیٛکہٕ نہٕ وۄنۍ میانہِ پتہٕ پٔکِتھ۔ مگر ژٕ پَتہٕ پَتہٕ۔\n37. پطرس ووٚن أمِس خداوند، بہٕ کیازِ ہیکہٕ نہٕ وُنۍ چانہِ پتہٕ پٔکِتھ؟ بہٕ دِیہ چانہِ خٲطرٕ پنُن زُن۔\n38.\\tعیسیٰ مسیحن دیت تس جواب، کیا ژیہ میانہِ خاطرہ پنُن جان دِنہٕ؟ پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ کۅکر کٔرِ نہٕ توٚت تام یوٚت تام نہٕ ژے میہ تریہ لٹہِ انکار کرِ۔","1. پَنُن دِل گژھِ نہٕ پریشان گژھُن: تہٕ تُہۍ چھِو خدایس پیٹھ یقین تھاوان، تہٕ میانہِ پیٹھ تہِ پژھ تھاوُن۔\n2.\\tمیٲنس مٲلہِ سٕندِس گرس منز چھِ واریاہ حویلی: اگر {یہ} آسہِ نہٕ تیلہِ ہا بہٕ ژے وَنُن۔ بہٕ چھُس ژےٚ خٲطرٕ اکھ جاے تیار کرنہٕ خٲطرٕ گژھان۔\n3. تہٕ اگر بہٕ گژھ تہٕ چانہِ خٲطرٕ جاے تیار کٔرِتھ، بہٕ یِیہٕ دُبارٕ تہٕ ژے پانس نِش حٲصل کٔرِتھ۔ زِ ییتہِ بہٕ چھُس، تتہِ تہِ آسہِ۔\n4. تہٕ ییتہِ بہٕ گژھُس تہٕ ژیہ پتاہ تہٕ یِتھٕ پٲٹھۍ ژیہ پتاہ چھُ۔\n5. تھامس چُھ أمِس ونان زِ خداوند، اسہِ چُھہ نہٕ پتاہ زِ ژٕ کوٚت چُھہ گٔژھان۔ تہٕ أسۍ کِتھٕ کٔنۍ ہیکون وتھ زٲنِتھ؟\n6. عیسیٰ مسیح چُھ أمِس ونان زِ بہٕ چُھس وَتھ، سچائی تہٕ زندگی چُھس، کانٛہہ تہِ انسان چُھنہٕ مٲلِس نِش یِوان، مگر میانہِ ذریعہٕ۔\n7.\\tاگر ژیہ میہ زانان آسہِ، تیلہِ آسہ ہا میون مول تہِ زانان، تہٕ یێلہِ تہِ چھُکھ سُہ زانان تہٕ وُچھمُت۔\n8. فلپ چُھ أمِس ونان زِ خداوند، اسہِ ہٲوِو باپ تہٕ یہِ چُھ اسہِ کٲفی۔\n9. عیسیٰ مسیح چُھ أمِس ونان زِ بہٕ چُھس ژےٚ سٍتـ̡ واریاہ کال روٗدمُت، تہٕ توتہِ چُھہ نہٕ ژے مے زانان فِلپ؟ یمۍ میہ وچھمُت چُھ، سُہ چُھ مول وُچھمُت۔ تہٕ ژیہ کِتھہ کٔنۍ چُھہ ونان زِ اسہِ ہٲوِو مول؟\n10. کیا تُہۍ چُھہ نہٕ یقین کران زِ بہٕ چُھس مٲلِس سٍتـ̡ تہٕ مٲلِس مَنٛز چُھس؟ یُس لفظ بہٕ ژے کتھ کران چُھس سُہ چُھس نہٕ پانس مُتلق کتھ کران: مگر یُس مٲل یُس میٲنس مَنٛز روزان چُھ، سُہ چُھ کٲم کران۔\n11.\\tمیانہِ پٲٹھـ̡ یقین کرو زِ بہٕ چُھس مٲلس سٍتـ̡ تہٕ مٲلِس مَنٛز چُھس، نتہٕ کامہِ ہٕندِ خٲطرٕ کٔرِو میہ پٲٹھـ̡ پژھ۔\n12. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ یُس میانہِ پیٹھ ایمان تھاوان چُھ، سُہ کرِ سُہ تہِ کرُن۔ تہٕ یِمو کھۅتہٕ بٔڈ {کامہِ} کرِ سُہ کرُن؛ کیازِ بہٕ چُھس پننِس مٲلس نِش گژھان۔\n13. تہٕ یُس تہِ ژیہ میانہِ ناوٕ سٍتـ̡ منگہِ، سُہ کرٕ بہٕ کرُن، یُتھ زِ مٲلِس گژھہِ نیٚچوِس مَنٛز جلال حٲصِل کرنہٕ۔\n14.\\tاگر ژیہ میانہِ ناوٕ سٍتـ̡ کانہہ کتھ پرژھہِ، بہٕ کٔرٕ {یہ}۔\n15.\\tاگر ژیہ میہ محبت کران چھیہ، میٲنۍ حکمن پیٹھ عمل کرُن۔\n16. تہٕ بہٕ کَرٕ مٲلِس سٕنز دُعا، تہٕ سُہ دِیہِ تۅہہِ سٍتـ̡ بیاکھ تسلی دِنہٕ، یُتھ سُہ روزِ تۅہہِ سٍتـ̡ ہمیشہٕ روزُن۔\n17.\\t{حتیٰ کہ} سچُند روح تہِ؛ یُس دنیا ہیکہِ نہ رٔٹِتھ، تکیازِ سہ چھہ نہ تس وچھان، نہ چھہ تس زانان: مگر توہۍ چھہ تس زانان۔ تکیازِ سُہ چُھ توے سٍتـ̡ روزان، تہٕ آسہِ توے سٍتـ̡ روزُن۔\n18. بہٕ تراوٕ نہٕ ژےٚ آرام دِنہٕ: بہٕ یِیہٕ ژےٚ نِش۔ {آرام دِنہٕ: یا، یتیم}\n19. توتہِ رژھ تہ دنیا چھہ نہ میہ وچھان۔ مگر ژیہ چھکھ میہ وچھان: کیازِ بہٕ زندہ، تہٕ ژیہ تہِ زندٕ۔\n20. تمہِ دۅہہ گژھہِ ژیہ پتاہ زِ بہٕ چُھس پننِس مٲلس منز، تہٕ تہٕ تہٕ بہٕ چُھس توے منز۔\n21. یُس میانہِ حکمہٕ تھاوان چُھ، تہٕ یُس میہ محبت کران چُھ، سُہ گژھہِ میانہِ مٲلہِ سٕندِ سٍتـ̡ محبت کرنہٕ، تہٕ بہٕ کرٕ تس محبت تہٕ تس برونہہ کُن ظٲہر کرنہٕ۔\n22. یہوداہ چُھ أمِس وَنُن، نہ کہ اِسکریوتی، خداوند، کِتھ کٔنۍ کٔرِکھ ژٕ پَنُن پان اسہِ برونہہ کُن ظٲہر کرنہٕ، تہٕ دُنیاہس سٍتـ̡ نہٕ۔\n23.\\tحضرت عیسیٰ علیہ السلام دیُت جواب تہٕ وونُن، یێلہِ کانہہ انسان میہ محبت کرِ، سُہ کرِ میٲنۍ کلام، تہٕ میون مول کرِ أمس محبت، تہٕ أسۍ یِو أمِس نِش تہٕ أمِس سٍتـ̡ روزُن۔\n24. یُس میہ محبت کران چُھ، سُہ چُھہ نہٕ میٲنۍ کتھ برقرار تھاوان: تہٕ یُس کلام تہٕ یُس تہٕ بوزان چُھ، سُہ چُھ نہٕ میون بلکہ مٲلہِ سُند یُس مے سوزمُت چُھ۔\n25.\\tیِم کتھ چھیہ میہ ژے سٍتـ̡ کتھ کٔرمٕژ، {توتہِ} ژے سٍتـ̡ موجود۔\n26. مگر تسلی دِنہٕ وول، یُس روح القدس چُھ، یُس مٲل میانہِ ناوٕ سٍتـ̡ سوزِ، سُہ کرِ تۅہہِ سارِنٕے چیزن ہیچھناوُن، تہٕ سارِنٕے چیٖز یێلہِ تہٕ یێلہِ تہٕ یێلہِ تہِ چُھہ ژے وَننہٕ آمُت۔\n27. امن بہٕ چھُس ژے سٍتـ̡ تراوان، پنُن امن چُھس ژے دِوان: یێلہِ نہٕ دُنیا دِوان چُھس، بہٕ دِیُس ژے دِوان چُھس۔ پنُن دِل گژھہِ نہ پریشان تہٕ نہ گژھہِ خوف۔\n28.\\tژے بوز میہ کِتھہ پاٹھۍ ووٚن ژے، بہٕ نیران تہٕ ژے نِش یِنہٕ۔ یێلہِ ژے میہ محبت کٔرِتھ، تێلہِ کٔرِو تۅہہ خۅش گژھُن، کیازِ میہ ووٚنمُت، بہٕ چُھس مٲلس نِش گژھان: کیازِ میون مول چُھ میانہِ کھوتہٕ بوڈ ۔\n29. تہٕ وُنۍ چُھس مے ژےٚ ووٚنمُت زِ یہِ سپدنہٕ برٛونٛہہ، یێلہِ یہِ سپدِ، تُہۍ ہیکِو پژھ کٔرِتھ۔\n30. اَمہِ پتہٕ کَرٕ نہٕ بہٕ ژےٚ سٍتـ̡ زیادٕ کَتھٕ کَتھ، تِکیازِ یێمہِ دُنیاہُک شہزادٕ چُھ یِوان، تہٕ چُھس نہٕ مےٚ مَنٛز کیٚنٛہہ تہِ۔\n31.\\tمگر یُتھ دنیا گژھہِ پتاہ زِ بہٕ چُھس مٲلس سٍتـ̡ محبت کران۔ تہٕ یِتھ کٔنۍ زَن مٲلہِ دِیُت مےٚ حُکُم، توتہِ چُھس بہٕ تہِ کران۔ وۅتھ، اسہِ گژھو اتہِ نیرُن۔","1. بہٕ چُھس پٔزۍ بیل تہٕ میون مول چُھس زمیندار۔\n2. میٲنِس مَنٛز پرٮ۪تھ کُنہِ لٔنٛجہِ یُس نہٕ مٮ۪وٕ دِوان چُھ، سُہ چُھ سُہ صاف کَران، یُس نہٕ پھل دِوان چُھ، سُہ چُھ صاف کَران، یُس زیادٕ پھل دِنہٕ ییہِ۔\n3. وۅنۍ چُھہ تۅہہ سٍتـ̡ پاکیزگی سٍتـ̡ یُس میہ ژے سٍتـ̡ کتھ کورمُت چُھ۔\n4. میہ منز روزُن تہٕ بہٕ چُھس ژے منز۔ تکیازِ لنجہِ ہیکہِ نہ پانس پھل دِتھ، یوٚت تام سہ بیلس منز روزِ۔ تۅہہ ہٮکہٕ نہٕ وۅں سٍتـ̡ بێیہِ سٍتـ̡ بێیہِ سٍتـ̡ روز\n5. بہٕ چُھس بیل تہٕ یُس میہ منز روزان چُھ، تہٕ بہٕ چُھس تس منز روزان، سُہ چُھ واریاہ پھل دِوان: کیازِ میانہِ ورٲیہ ہیکو نہٕ کانہہ تہِ کٔرِتھ۔ {میہ ورٲے: یا، میہ نش ژٹنہٕ}\n6.\\tاگر کانہہ انسان میانہِ مَنٛز روزِ نہٕ، سُہ چُھ لٔرِتھ دِنہٕ یِوان، تہٕ سُہ چھُ مرزاونہٕ یِوان۔ تہٕ انسان چھِ تِم جمع کٔرِتھ، تہٕ نارس منٛز ترٛاوان، تہٕ تِم چھِ زالنہٕ یوان۔\n7. یێلہِ تہٕ یێلہِ تہٕ میٲنۍ کَلام پانس مَنٛز روزِو، تہٕ یێلہِ تہِ یِیہِ تۅہہِ سٍتـ̡ کرنہٕ۔\n8. یَتھ مَنٛز چُھ میون مول جلال دِنہٕ آمُت، یُس تہٕ چُھہ واریاہ پھل دِوان۔ یِتھے پٲٹھۍ بٔنِو تُہۍ میٲنۍ شٲگِرِ۔\n9. یِتھٕ پٲٹھـ̡ مٲلِس چُھس میہ محبت کٔرمٕژ، تِتھٕ کٔنۍ چُھس ژے محبت کٔرمٕژ: میانہِ محبتس مَنٛز جٲری تھاوُن۔\n10. یێلہِ تہٕ یێلہِ میٲنۍ حُکمن ہُند عمل کٔرِو، تێلہِ روزو میانہِ محبتس مَنٛز۔ یێلہِ زن بہٕ چُھس مٲلہِ سٕندِس حُکمن پیٹھ عمل کٔرِمُت، تہٕ تٔمۍ سٕندِس محبتس مَنٛز چُھس عمل کٔرِتھ۔\n11.\\tیِم کتھ چھیہ میہ ژے سٍتـ̡ کتھ کٔرمٕژ، یُتھ میٲنۍ خوشی روزِ ژے منز، تہٕ تۅہہِ ہٕنز خوشی گژھہِ پورٕ۔\n12. یہ چُھ میون حکم زِ تم کرو اکھ أکِس محبت، یِتھ کٔنۍ مے چُھہ ژے محبت کٔرمٕژ۔\n13.\\tامہِ کھوتہ زیادٕ محبت چھہ نہ کانہہ انسان زِ انسان چھہ پننین یارن ہندِ خاطرہ پنُن جان دوان۔\n14.\\tتُہۍ چھِو میٲنۍ دوس، اگر بہٕ یُس تہِ حکم دِوان چھُ۔\n15. اَمہِ پتہٕ چُھس نہٕ بہٕ چُھہ ژےٚ نوکر وَنان۔ تکیازِ خادم چُھنہٕ پتاہ زِ تٔمۍ سُند رب کیا چُھ کران، مگر مے چُھہ ژیہ یارس بُلوومُت۔ تِمن سارِنٕے چیزن خٲطرٕ یُس میہ پننِس مٲلس متعلق بوزمُت چُھ، مے چُھ ژےٚ زانمُت۔\n16. ژے چُھہ نہٕ مے ژٲرمُت، مگر مے چُھہ ژیہ ژٲرمُت، تہٕ چُھہ مقرر کورمُت، تہٕ ژے گژھِو پھل دِنہٕ، تہٕ تُہند پھل روزُن، یُس تہٕ ژے میانہِ ناوٕ سٍتـ̡ مٲلِس سٍتـ̡ منگہِ، سُہ دِیہِ سُہ دِیہِ۔\n17. یِمن چیزن ہُند حُکُم چُھس بہٕ ژے دِوان زِ تُہۍ چھِو اَکھ أکِس سٍتـ̡ محبت کٔر\n18.\\tاگر دنیا ژیہ نفرت کران چھیہ، ژیہ چھیہ پتاہ زِ یہ چھیہ میہ سیتۍ نفرت کران۔\n19.\\tیێلہِ تہٕ دُنیاہس سٍتـ̡ آسہِ تۯێلہِ دُنیاہس سٍتـ̡ دُنیا سٍتـ̡ چُھہ دُنیاہس سٍتـ̡ چُھہ ژٲرمُت، تێلہِ چُھہ دُنیا چُھہ ژے سٍتـ̡ نفرت۔\n20.\\tسُہ لفظ یاد تھاوُن یُس میہ ژیہ ووٚنمُت چُھ، خادم چُھ نہٕ پننِس مالہٕ سٕندِ کھۅتہٕ بٔڈ آسان۔ اگر تِمو مےٚ ستٲومُت چھُ، تِم تہِ کٔرِن تۅہہِ ستاونہٕ۔ اگر تِمو میون کلام برقرار آسہِ، تِم تھاوَن تُہند تہِ۔\n21.\\tمگر یِم سٲری کتھ کٔرِن تِم میانہِ ناوٕ خٲطرٕ، تِکیازِ تِم چھِنہٕ تس زانان یُس میہ سوزمُت اوس۔\n22. اگر نہٕ بہٕ یِمن سٍتـ̡ کتھ کٔرِتھ، تِمن آسہٕ نہٕ گۅناہ کٔرِتھ، مگر وۅنۍ چُھہ نہٕ تِمن ہٕندِس گۅنہٕ ہُند کانہہ پوشہٕ۔ {کلک: یا، بہانہ}\n23. یُس میہ نفرت کران چُھ، سُہ چُھ میٲنس مٲلس سٍتـ̡ تہِ نفرت۔\n24.\\tاگر میہ تِمن منز تِم کٲم کٔرِتھ یِم نہٕ کٲنسہ تہِ کٲنسہِ انسانس کٔرۍ، تِمن آسہ نہٕ گۅناہ گومُت، مگر وۅنۍ چھُ یِمو دۅشوے میہ تہٕ میٲنِس مٲلِس سٍتـ̡ وُچھمُت تہٕ نفرت۔\n25.\\tمگر {یہِ سپُد}، یُس لفظ یُس تِہندِس شریعتس مَنٛز لیکھنہٕ آمُت چھُ، تِمو کٔر میہ سٍتـ̡ نفرت۔\n26. مگر یێلہِ یێلہِ تسُند دِل دِنہٕ وول یُس بہٕ مٲلہِ سٕندِ طرفہٕ تہِ سوزان چُھ، سُہ کرِ میانہِ سٍتـ̡ گوٲہی دِنہٕ:\n27. تہٕ تہٕ تہٕ گوٲہی دِیُن، تکیازِ تہٕ تہٕ چُھہ شروع پیٹھے میانہِ سٍتـ̡ سٍتـ̡ رودمُت۔","1.\\tیِم کتھ چھیہ میہ ژے سٍتۍ کتھ کٔرمٕژ، یُس نہٕ ژیہ ناراض گژھُن۔ {ناراض: سکینڈلائزڈ یا، ٹھوکر کھاونہٕ آمُت}\n2. تِم کٔرِن تۅہہِ عبادت خانہٕ منزٕ نیبر کٔرِتھ: آ، سُہ وقت چُھ یِوان، یُس تہٕ یُس تہِ ژےٚ مارِ، سُہ کرِ سُہ سُہ خدایہِ سٕنز خدمت کران۔\n3. تہٕ یِم کامہِ کٔرِن تۅہہِ سٍتـ̡ تکیازِ تِمو چُھہ نہٕ مٲلِس سٍتـ̡ زانان تہٕ نہ چُھہ میہ سٍتـ̡ زانان۔\n4.\\tمگر یِم کتھ چھیہ میہ ژیہ وننہ آمژ، ییلہ وق ییہ، ژیہ گژھہِ یاد روزُن زِ میہ چھہ تمن متعلق وونمُت۔ تہٕ یِم کتھ ٲس نہ میہ گۅڈہ ژیہ ونمژ، تکیازِ بہٕ اوسس ژیہ سۭتۍ۔\n5. مگر وۅنۍ چھُس بہٕ تس نِش گژھان یُس میہ سوزمُت اوس۔ تہٕ تۄہہِ منٛزٕ چھُنہٕ کانٛہہ تہِ پرژھان، ژےٚ کوٚت چھُو؟\n6.\\tمگر کیازِ میہ چھیہ یہ کتھ ژیہ وننہ آمژ، غم چھہ ژیہ دِل بٔرتھ۔\n7.\\tبہٕ چُھس ژیہ پزر ونان بہٕ نیرُن چُھس نہٕ ژےٚ خٲطرٕ مناسب: تکیازِ اگر بہٕ نیرٕ نہٕ تیلہِ گژھِ نہٕ تسلی دِنہٕ وول ژےٚ نِش۔ مگر اگر بہٕ نیرِ، بہٕ سوزٕ سُہ ژےٚ نِش۔\n8. تہٕ ییلہ سُہ یِیہ، سُہ کرِ گۅنہٕ ہٕندِس دنیاہس تہٕ نیکی ہٕندِس دنیاہس ملامت کٔرِتھ: {ملامت کرُن: یا، قائل کرُن}\n9. گۅنہہ، تکیازِ تم چھہِ نہ میہ پیٹھ یقین تھاوان۔\n10.\\tنیکی ہٕندِس سٍتـ̡ چُھہ بہٕ پننِس مٲلِس نِش گژھان، تہٕ ژے چُھہ نہٕ میہ وُچھان۔\n11. فیصلہٕ، تکیازِ دنیاہُک شہزادٕ چُھ فیصلہ کرنہٕ آمُت۔\n12.\\tمیہ چھیہ وُنہِ تہِ واریاہ کتھ وننہ آمژ، مگر ژیہ ہیوٚک نہ وۅنۍ تم برداشت کٔرتھ۔\n13. یێلہِ سُہ یێلہِ سُہ سُہ سُہ سٍتـ̡ پى۪ٹھـ� مگر یُس تہِ بوزِ، سُہ کرِ کتھ تہٕ سُہ کرِ یِنہٕ وٲلِس چیزس ہاونہٕ۔\n14.\\tسُہ کرِ میانہِ تسبیٖل: تکیازِ سُہ کرِ میٲنۍ سٍتـ̡ رٔٹِتھ تہٕ ژے ہٲوِ۔\n15. مٲلِس سٍتـ̡ سارِنٕے چیٖز چُھہ میٲنۍ ، تێمہِ کِنۍ چُھہ میہ ووٚنمُت زِ سُہ نِش نِیہِ تہٕ ہاوِ ژے ۔\n16.\\tکینژس کالس تہٕ ژے وُچھِو نہٕ مے، تہٕ بییہِ کینژس کالس تہٕ ژے وُچھِو، کیازِ بہٕ چُھس مٲلِس نِش گژھان۔\n17.\\tاَمہِ پَتہٕ ووٚن تٔمۍ سٕندِس شٲگِرَو منزٕ یُس سُہ اسہِ وَنُن چُھ، کینژَس کالس تہٕ ژیہ وُچھِو نہٕ مےٚ: تہٕ بییہِ کینژَس کالس تہٕ ژے وُچھِو مےٚ: تہٕ کیازِ بہٕ چُھس مٲلِس نِش گژھُن؟\n18.\\tتِمو ووٚن یہِ کیا چُھہ یہِ وَنُن، رژھ۔ أسۍ ہیکو نہٕ ؤنتھ زِ سہ کیا چُھ وَنان۔\n19. وۅنۍ اوس حضرت عیسیٰ علیہ السلام پتاہ زِ تِم چھِ أمِس پرژھنہٕ یِنُک خواہش، تہٕ تِمن وُچھِو، یێمہِ سٍتـ̡ چُھہ یێمہِ سٍتـ̡ پرژھہٕ وُچھمُت، تہٕ یێلہِ وُچھِو نہٕ میہ وُچھن؟\n20. پٔزۍ پٲٹھۍ، بہٕ چُھس ژےٚ ونان زِ تۅہہ روو تہٕ ماتم کٔرِو، مگر دنیا گژھہِ خۅش، تہٕ تۅہہ گژھہِ غم، مگر تُہند غم گژھہِ خوشی مَنٛز تبدیل۔\n21.\\tزنانہِ ییلہ مصیبتس منز آسان چھہ سہ چھہ غم گژھان، تکیازِ تسند وقت چھہ آمت، مگر ییلہ تس بچہ زیومت چھہ، تس چھہ نہ یہ غم یاد روزان، خوشی مۅکھہ زِ مرد چھہ دنیاہس منز پیدہ سپدان۔\n22. تہٕ تۅہہِ چُھہ وُنہِ غم، مگر بہٕ وُچھِو ژے دُبارٕ تہٕ تُہند دِل گژھہِ خۅش تہٕ تُہٕنز خوشی یُس نہٕ کانہہ تہِ انسان ژے نِش نِتھ۔\n23. تہٕ تمہِ دۅہہ کٔرِو نہٕ میہ کانہہ تہِ پرژھنہٕ۔ پٔزۍ، پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ یُس تہٕ ژے میانہِ ناوٕ سٍتـ̡ مٲلِس منگہِ، سُہ دِیہِ ژے دِنہٕ۔\n24.\\tاز تام چُھہ نہٕ میانہِ ناوٕ سٍتـ̡ کانہہ تہِ منگمُت: پرژھو، تہٕ ژے میلہِ، یُتھ تُہٕنز خوشی پوٗرٕ گٔژھِ۔\n25.\\tیِم کتھٕ چھے مے ژے سٍتـ̡ محاورن مَنٛز کتھ کٔرمٕژ، مگر سُہ وق چُھہ یێلہِ بہٕ ژے سٍتـ̡ محاورن مَنٛز کتھ کٔرِتھ، مگر بہٕ ہاوٕ ژے مٲلِس سٍتـ̡ سیدِ سیدِ سٍتـ̡ ۔ {محاورہ: یا، تمثیل}\n26. اَمہِ دۅہہٕ کٔرِو تُہۍ میانہِ ناوٕ سٍتـ̡ پرژھن: تہٕ بہٕ چُھس نہٕ ژے ونان زِ بہٕ کَرٕ تۅہہِ خٲطرٕ مٲلِس سٕنز دُعا:\n27. تکیازِ باپ چُھ پانہٕ ژے محبت کران، تکیازِ ژے چُھہ میہ محبت کورمُت، تہٕ چُھکھ یقین کورمُت زِ بہٕ چُھس خدایہ سٕندِ طرفہٕ نیبر آمُت۔\n28. بہٕ چُھس مٲلہِ سٕندِ نِش نیران، تہٕ بہٕ چُھس دُنیاہس مَنٛز آمُت، تہٕ دُنیاہس مَنٛز چُھس۔\n29.\\tتٔمۍ سٕندٮ۪و شاگردو ووٚن أمِس زِ وُنہِ چھُکھ وُنہِ سیدِ سیدِ سٍتـ̡ کتھ کٔرِتھ، تہٕ کُنہِ تہِ محاورٕ چُھہ نہٕ بولان۔ {محاورہ: یا، تمثیل}\n30. وۅنۍ چُھہ اسہِ پژھ زِ ژے چُھہ سارِنٕے چیزن ہُند زان تہٕ یہ چھُنہٕ کانہہ تہِ انسان ژیہ پرژھنٕچ ضرورت: اَمہ سٍتـ̡ چُھہ أسـ̡ یقین زِ تہٕ چُھہ خدایہِ سٍتـ̡ دِنہٕ آمُت۔\n31.\\tحضرت عیسیٰ علیہ السلام دیت تمن جواب، کیا تُہۍ چھوا وۅنۍ یقین تھاوان؟\n32.\\tوُچھو، سُہ وقت چُھہ آمُت، آ، وُنہِ چُھہ وُنـ̡ ژٔٹِھتھ تہٕ یێلہِ تہٕ بہٕ چُھس نہٕ کُنی کُنی، کیازِ مٲل چُھس میہ سٍتـ̡ ۔ {پنن پنُن: یا، پنن گھر}\n33.\\tیِم کتھ چھیہ میہ ژے سٍتـ̡ کتھ کٔرمٕژ، یُتھ میانہِ مَنٛز گژھہِ سکون۔ دُنیاہس مَنٛز گژھہِ تۅہہ مصیبت: مگر رژھ۔ میہ چھہ دنیاہس پیٹھ قابو پیوان۔","1. یِمو کلامَن کٔر عیسیٰ مسیح سٕندِس کُن کتھ تہٕ تُلِن اسمانس کُن أچھ تُلِتھ تہٕ وونُن، بابا، سُہ وقت آو آمُت۔ پننِس نیٚچوِس کٔرِو تسبیٖل، یُتھ تُہند نیچو تہِ کرِ تۅہہِ تسلیٖم:\n2. یِتھٕ کٔنۍ ژے أمِس سارِنٕے مازس پیٹھ اختیار دِژمُت، تہٕ سُہ دِیہِ تِمن ہٕندِس ابدی زندگی یُس ژے دِژمُت چھُ۔\n3. تہٕ یِہ چھے ابدی زندگی، یُتھ تِم زانن تُہۍ وٲحِد پٔزۍ خدا تہٕ عیسیٰ مسیح، یُس ژے سوزمُت چُھ۔\n4. مے کٔر ژے زمینس پیٹھ جلال حٲصل: مے کور سُہ کٲم مُکمل یُس ژے مے دِژمُت چھُ۔\n5. تہٕ وۅنۍ اے بابا، ژے کٔر میہ پننہِ پننہِ سٍتـ̡ جلال سٍتـ̡ یُس میہ دنیاہٕ برونہہ تہِ اوس۔\n6. مے چُھہ تُہند ناو تِمن نفرن ہُند ظٲہر کوٚرمُت یُس ژے میہ دُنیاہس منز دِژمُت چھُ: تِم ٲسۍ تہٕ ژے دِژٕ تِم دِژمٕتۍ۔ تہٕ تِمو چُھ تُہند کلام پورٕ کوٚرمُت۔\n7.\\tوۅنۍ چُھ تِمن پتاہ زِ یُس تہِ ژے مے دِژمُت چھُ، سُہ چُھ تۅہہِ سٍتـ̡\n8.\\tکیازِ میہ چھہ تمن دِژمٕتۍ لفظ یُس ژے میہ دِژمُت چھُ۔ تہٕ تِمو چُھ رٔٹمُت، تہٕ یِمو چُھس پٔزۍ پٲٹھـ̡ پتاہ زِ بہٕ چُھس ژے نِش نِش نیبر آمُت، تہٕ تِمو چُھ یقین کوٚرمُت زِ ژے چُھس مے سوزمُت۔\n9. بہٕ چُھس تِمن ہٕندِ خٲطرٕ دُعا کران: بہٕ چُھس نہٕ دُنیاہس خٲطرٕ دُعا کران بلکہ تِمن ہٕندِ خٲطرٕ یِم ژے مے دِژمٕژ چھِ۔ تکیازِ تم چھہِ تۅہہِ۔\n10. تہٕ میٲنۍ سارِنٕے چھُ تُہُن، تہٕ تُہُند چھُ میٲنۍ ۔ تہٕ بہٕ چُھس تمن منز جلال بخشان۔\n11. تہٕ وُنۍ چُھس نہٕ بہٕ دُنیاہس مَنٛز، مگر یِم چھِ دُنیاہس مَنٛز، تہٕ بہٕ چُھس ژے نِش آمُت۔ پاک باپ، تِم تھاوُن پنُن ناو یُس ژے مے دِژمُت چُھ، یُتھ زن تِم آسن اَکھ یِتھٕ پٲٹھۍ أسـ̡ {چھِ}۔\n12.\\tییلہ بہٕ تِمن سٍتـ̡ دنیاہس مَنٛز اوسس، مے تھوو تِم تہندِس ناوَس پیٹھ: یِم ژے مے دِژمٕژ چھِ، تہٕ یِمو منزٕ چُھہ نہٕ کانہہ تہِ رٲومُت، مگر ہلاکُک نیٚچُو۔ یُتھ صحیفہٕ گژھہِ پورٕ سپدُن۔\n13. تہٕ وۅنۍ چُھس بہٕ ژے نِش آمُت۔ تہٕ یِم چیز بہٕ دُنیاہس منز کتھ کران چھُس، یُتھ زن تِم گژھن میٲنۍ خوشی پانس منز پورٕ۔\n14. میہ دِژ تِمن تُہند کلام۔ تہٕ دنیاہن کٔر تمن سۭتۍ نفرت، تکیازِ تم چِھ نہٕ دنیاہک تہٕ یتھے پٲٹھۍ بہٕ چُھس نہٕ دنیاہک آسان۔\n15. بہٕ چُھس نہٕ دُعا کران زِ ژے کٔرِو تِم دُنیاہس نِش بچاوُن۔\n16. تِم چھِنہٕ دُنیاہُک تہٕ بہٕ چُھس نہٕ دُنیاہُک ۔\n17. پننہِ حقیقتہٕ سٍتـ̡ کٔرِو تِمن پاکیز: تُہند کلام چُھ سچ۔\n18. یِتھٕ پٲٹھۍ ژے مے دُنیاہس مَنٛز سوزمُت، تِتھے پٲٹھۍ چھُ مے تہِ دُنیاہس مَنٛز سوزمُت۔\n19. تہٕ تہندِ خاطرہ چھُس بہٕ پنُن پان پاک بناوان، یُتھ زن تِم تہِ گژھن حقیقتہٕ سٍتـ̡ پاک کرنہٕ۔ {مقدس...: یا، پزۍ پاٹھۍ مقدس}\n20. بہٕ چُھس نہٕ صرف یِمن خٲطرٕ دُعا کران، بٔلکہِ تِمن ہٕندِ خٲطرٕ تہِ یِم تِمن ہٕندِس کلامَس سٍتـ̡ میانہِ پٲٹھـ̡ یقین کرِ۔\n21.\\tیُتھ زِ تِم سٲری آسن اَکہٕ۔ یِتھٕ پٲٹھـ̡ چُھہ، باپ، میہ مَنٛز تہٕ بہٕ چُھس ژے منز، یُتھ زن تِم تہِ اسہِ مَنٛز اکھ بٔنِتھ: یُتھ دُنیا پژھ کٔرِتھ زِ ژے چُھہ میہ سوزمُت۔\n22. تہٕ یُس جلال ژے مے دِژمُت چُھ، سُہ چُھس مے تِمن دِژمُت۔ تاکہ تِم ہیکن اکھ ٲسِتھ، یتھے پٲٹھۍ أسۍ اکھ چھِ:\n23. بہٕ چُھس تِمن مَنٛز، تہٕ تُہۍ چھِو میٲنِس مَنٛز، یُتھ تِم أکِس مَنٛز کامل گٔژھِتھ۔ تہٕ دُنیاہس گژھہِ پتاہ زِ ژے چھُکھ مے سوزمُت، تہٕ تِمن سٍتۍ محبت کٔرمٕژ، یِتھٕ پٲٹھۍ ژے مےٚ محبت کٔرمٕژ۔\n24. باب، بہٕ چُھس یژھان زِ تِم تہِ، یِم ژے مے دِژمٕتۍ، تِم روزن مےٚ سٍتـ̡ یێتہِ بہٕ آسہٕ۔ یُتھ زن تِم میٲنۍ جلال وُچھِن، یُس ژے مے دِژمُت چھُ، تِکیازِ ژے چھُکھ دُنیاہٕچ بُنیاد برونہہ میہ محبت۔\n25. اے نیک باپ، دنیا چُھہ نہٕ ژے زانان، مگر بہٕ چُھس ژے زانان، تہٕ یِمن چُھ پتاہ زِ ژے چُھہ مے سوزمُت۔\n26.\\tتہٕ بہٕ چُھس تِمن سٍتـ̡ تُہند ناو اعلان کورمُت، تہٕ کرٕ اعلان زِ یێمہِ سٍتـ̡ ژے میہ محبت کران چُھ، سُہ گژھہِ تِمن مَنٛز تہٕ بہٕ چُھس تِمن مَنٛز۔","1. یێلہِ عیسیٰ علیہ السلام یِم لفظ بولوو، سُہ دراو پننین شاگردن سٍتـ̡ نالہِ سیڈرنس کُن، یێتہِ اکھ باغ اوس، یتھ مَنٛز سُہ تہٕ تٔمۍ سٕندِس شٲگِرِس اندر اژان اوس۔\n2. تہٕ یہوداہ تہِ، یُس أمِس دھوکھہٕ دِژ، سُہ اوس اتھ جایہِ زانان: تکیازِ عیسیٰ اوس اکثر پننین شاگردن سٍتـ̡ اتہِ روزان۔\n3. یہوداہ چُھ اَمہِ پتہٕ بٔڈِس پادٕرین تہٕ فریسیَن ہٕندِ طرفہٕ اَکھ جمٲژ تہٕ افسر حٲصِل کٔرِتھ، لالٹین تہٕ ٹارچ تہٕ ہتھیار ہٮ۪تھ تتہِ یوان۔\n4. تێمہِ کِنـ̡ عیسیٰ علیہ السلام سٍتـ̡ یێلہِ سارِنٕے چیزن ہٕندِس سٍتـ̡ یُس أمِس سٍتـ̡ یِنہٕ یِن، درٛاو تہٕ وونُن تِمن کُس ژھاران چھُ\n5. تِمو دِژ أمِس جواب عیسیٰ مسیح ناصریت۔ عیسیٰ مسیح چُھ تِمن ونان زِ بہٕ چُھس {سُہ}۔ تہٕ یہوداہ تہِ، یمۍ أمس دھوکہ دِژ، کھڑا تمن سٍتۍ۔\n6.\\tییلہ تٔمۍ تِمن ووٚن، بہٕ چُھس، تِم گٔیہِ پتھ کُن، تہٕ پیوٚو زمینس پیٹھ۔\n7.\\tاَمہ پتہٕ پرژھُن تِمن دُبارٕ کُس ژھاران چھُو؟ تہٕ تِمو ووٚن عیسیٰ مسیح ناصرت۔\n8.\\tحضرت عیسیٰ علیہ السلامن دیت جواب، میہ چھہ ژیہ ووٚنمُت زِ بہٕ چُھس {سُہ} تہٕ یێلہِ\n9.\\tیُس کلام گژھہِ پورٕ سپدُن، یُس تٔمۍ وَنُن وَنُن چھُ، یِمن مَنٛز ژے مے دِژمٕژ چھِ، تِمن مَنٛز چھُنہٕ مے کانہہ تہِ رٲومُت۔\n10.\\tپَتہٕ لوٚگ شمعون پطرس تلوار ہیتھ تہٕ دِژُن پادٕرۍ سٕندِس نوکرس تہٕ ژٹُن تٔمِس دٔچھُن کَن۔ نوکر سُند ناو اوس مالچس۔\n11.\\tتێلہِ ووٚن عیسیٰ علیہ السلام پطرس، پنٕنۍ تلوار تھٲوِو میانس مَنٛز، سُہ پیالہ یُس میانہِ مٲلہِ دِژمُت چُھ، کیا بہٕ چُھس نہٕ سُہ چیوان؟\n12.\\tتمہِ پتہٕ رٔٹ یہودین ہٕندِس کپتان تہٕ افسرو عیسیٰ مسیح تہٕ رٔٹِتھ رٔٹِتھ\n13.\\tتہٕ نِیوو سُہ گۅڈٕ اناس نِش۔ تکیازِ سُہ اوس کایفاسس سُند مول، یُس امی ؤری اعلیٰ پادٕرۍ اوس۔ {ؤری: ؤری۔ تہٕ عناسن سوٗز مسیح بٔنِتھ کیافہ سٕندِس پادٕرۍ سٍتـ̡\n14.\\tوۅنۍ اوس سُہ یُس یہودین مشورٕ دِوان زِ یہ چھہ مناسب زِ اکھ انسان گژھہِ لوکن ہندِ خاطرہ مرُن۔\n15.\\tتہٕ شمعون پطرس پوٚت عیسیٰ سٕندِس پٲٹھۍ، تہٕ یِتھے پٲٹھۍ گۆو بیاکھ شٲگِر: سُہ شٲگِر اوس بٔڈِس پادٕرِس سٍتـ̡ زانان تہٕ گۆو عیسیٰ سٕندِس محلس مَنٛز۔\n16. مگر پطرس اوس دروازس پیٹھ کھڑا۔ پتہٕ دراو سُہ بیٛاکھ شٲگِر، یُس بٔڈِس پادٕرِس زانان اوس، تہٕ کوٚرُن أمِس سٍتـ̡ کتھ یُس دروازٕ تھپھ کٔرِتھ، تہٕ أنِن پطرس۔\n17.\\tتیلہِ چھے پطرس سٕندِس دروازس تھپھ کٔرِتھ ونان، کیا تُہۍ چھُکھ نہٕ أمِس شخصہٕ سٕندِس مریدَن مَنٛز اکھ تہِ؟ سُہ چُھس ونان زِ بہٕ چُھس نہٕ۔\n18.\\tتہٕ نوکر تہٕ افسر ٲسۍ اَتہِ کھڑۍ، یِمو ژٔنگہِ ہُند نار دِژمُت۔ تکیازِ یہ اوس سردی: تہٕ تِمو کٔر پان گرم: تہٕ پطرس کھڑا تمن سٍتۍ، تہٕ کوٚرُن پان گرم۔\n19.\\tاعلیٰ پادٕرین پرژھ عیسیٰ ہس پننین شاگردن تہٕ تٔمۍ سٕندِس نظریہس متعلق۔\n20. حضرت عیسیٰ علیہ السلام دیُت أمِس جواب، میہ کٔر دُنیاہس سٍتـ̡ کھلہٕ پٲٹھۍ۔ میہ اوس زانہہ یہودی عبادت خانس منز تہٕ مندرس منز پرناوان ییتہِ یہودی ہمیشہٕ روزان چھِ۔ تہٕ ژوٗرِ پٲٹھۍ، میہ ووٚن نہٕ کیٚنٛہہ۔\n21.\\tژیہ کیازِ چھکھ میہ پرژھان؟ تمن پرژھ یمو بوز، میہ کیا چُھ تمن وونمُت: وچھ تمن پتہ کیا چُھ میہ وونمُت۔\n22.\\tییلہ تٔمۍ یِتھٕ پٲٹھۍ کتھ کٔرِتھ، أکِس افسرس یُس اَتھ سٍتـ̡ کھڑا اوس، یُس حضرت عیسیٰ علیہ السلام سٕندِس اتھہٕ سٍتـ̡ تھپھ کٔرِتھ وونُن، کیا تُہۍ چُھکھ بٔڈِس پادٕرِس یُتھ جواب دِوان؟ {سۭتۍ...: یا، لاٹھی سۭتۍ}\n23.\\tحضرت عیسیٰ علیہ السلام دیُت أمِس جواب، یێلہِ بہٕ بد کتھ کٔرمٕژ آسہِ، بد سٍتـ̡ گوٲہی دِیُن، مگر یێلہِ چُھہ تێلہِ کیازِ چُھہ میہ ژکھہٕ دِوان۔\n24.\\tوۅنۍ اوس اناسن سُہ بٔڈِتھ کِفافس نِش سوزمُت۔\n25. تہٕ شمعون پطرس ووت کھڑا تہٕ پان گرم کٔرِتھ۔ تِمو ووٚن تٔمِس زِ کیا تُہۍ تہِ چھُکھ نہٕ تٔمۍ سٕندِس شٲگِرَن مَنٛز اکھ؟ تٔمۍ کوٚر اِنکار تہٕ ووٚنُن، بہٕ چُھس نہٕ۔\n26.\\tاعلیٰ پادٕرۍ سٕندِس خادمَس مَنٛز اَکھ رشتہٕ دار یٔمۍ سُند کَن پطرس ژٹمُت اوس، وَنُن چُھہ نہٕ ژے أمِس سٍتـ̡ باغس مَنٛز وُچھمُت؟\n27.\\tپطرس کٔر بییہ اِنکار: تہٕ فوراً کۅکر عملہٕ۔\n28.\\tتێلہٕ نِیوو عیسیٰ مسیح قیافہ پیٹھٕ ہال آف سُہ تہٕ سُلہٕ سُلہٕ۔ تہٕ تِم گٔیہِ نہٕ پانہٕ فیصلہٕ کِس ہالس منٛز، تاکہ تِم گژھن ناپاک کرنہٕ۔ مگر تِم گژھن فسح کھٮ۪ن۔ {ہال...: یا، پیلاطس سُند گھر}\n29.\\tپیلاطس دراو تِمن نِش تہٕ وونُن، تۅہہِ کُس الزام چُھہ أمِس شخصس سٍتـ̡ دِنہٕ۔\n30.\\tتِمو دِژ جواب تہٕ وونُن أمِس زِ اگر سُہ بدکار آسہِ نہٕ تیلہِ ہا نہٕ أسۍ سُہ ژےٚ حوالہٕ کٔرِتھ۔\n31. اَمہِ پَتہٕ ووٚن پیلاطس تِمَن نِش أمِس نِش تہٕ پَنٕنِس شریعت مُطٲبِق کٔرِو أمِس فٲصلہٕ۔ تَمہِ کِنۍ ووٚن یہودیو أمِس زِ اسہِ خٲطرٕ چُھنہٕ کٲنٛسہِ تہِ انسانس مارُن جٲیز۔\n32.\\tیُتھ عیسیٰ سُند کلام گژھہِ پورٕ سپدُن، یُس تٔمۍ کُس موتُک اشارہ دِوان چھُ۔\n33. پَتہٕ ژاو پیلاطس دُبارٕ فیصلہٕ کِس ہالس مَنٛز، تہٕ کوٚرُن عیسیٰ مسیحس بُلاونہٕ تہٕ وونُن، کیا تُہۍ چھُکھ یہودین ہُند بادشاہ؟\n34.\\tحضرت عیسیٰ علیہ السلام دیُت أمِس جواب، کیا ژے چھُکھ یہِ کتھ پننہِ بارس منز وَننہٕ آمُت، کِنہٕ باقیو تہِ وَنُن میانہِ مُتلِق تہِ؟\n35. پیلاطس دیت جواب، کیا بہٕ چھُس یہودی؟ تُہٕندِس قومس تہٕ بٔڈۍ پادٕرۍ چُھکھ ژے مے حوالہٕ دِژمُت: ژے کیا چُھہ کورمُت؟\n36.\\tحضرت عیسیٰ علیہ السلام دیُت جواب، میٲنۍ بادشٲہی چھے نہٕ یێمہِ دنیاہٕچ ، تێلہِ گژھن میٲنۍ بادشٲہی لڑان، یێلہِ گژھہِ نہٕ یہودین نِش واتناونہٕ یُن، مگر وُنۍ چھُنہٕ میٲنۍ بادشٲہی یێمہِ سٍتـ̡ یێلہِ سٍتـ̡ دِنہٕ آمٕژ۔\n37. تَمہِ کِنۍ ووٚن پیلاطس أمِس زِ کیا تُہۍ چھوا بادشاہ؟ عیسیٰ مسیحن دیُت جواب، تہٕ ژٕ چُھس ونان زِ بہٕ چُھس اکھ بادشاہ۔ اَمہ مۅکھٕ اوسُس بہٕ زامُت، تہٕ اَمہ مقصدٕ خٲطرٕ آو بہٕ دُنیاہس منز، یُتھ بہٕ پزِ حقیقتٕچ گواہی دِنہٕ۔ پریتھ کانہہ یُس حقیقتس منز چُھ، سُہ چُھ میٲنۍ آواز بوزان۔\n38. پیلاطس چُھ أمِس ونان زِ پزر کیا چُھ؟ تہٕ ییلہ تٔمۍ یہ ووٚنمُت، سُہ گوٚو دُبارٕ یہودین نِش، تہٕ تِمن وونُن زِ مےٚ چُھنہٕ أمِس مَنٛز کانٛہہ تہِ غلطی لبنہٕ۔\n39.\\tمگر تۅہہِ چُھہ اکھ رسم زِ بہٕ کرٕ ژے یُس فسح وِزِ یلہٕ تراوُن، تێلہِ کیا ژٕ ژے یہودین ہُند بادشاہ یلہٕ تراوُن؟\n40.\\tاَمہِ پتہٕ وَنُن تِم سارِوٕے دُبارٕ یہِ نَفر، بٔلکہِ باراباس۔ وۅنۍ اوس بارباس اکھ ڈاکو۔","1.\\tتێلہِ روٚٹ پیلاطس عیسیٰ مسیح تہٕ دِژُن أمِس کوٹھ۔\n2.\\tتہٕ سپاہیو لوٚگ کانٹَن ہُند تاج، تہٕ تھووُن أمِس کَلس پیٹھ، تہٕ تِمو لٲگِتھ أمِس واگن رنٛگہٕ پوشہٕ،\n3.\\tتہٕ وونُن، یہودین ہُند بادشاہ! تہٕ تِمو دِژ أمِس اتھو سٍتۍ مار۔\n4. تَمہِ کِنۍ دراو پیلاطس دُبارٕ تہٕ تِمن وَنُن زِ بہٕ چُھس سُہ تۅہہِ نِش انان، یُتھ تۅہہِ زانہِ زِ مےٚ چُھنہٕ أمِس مَنٛز کانہہ عیب لبان۔\n5. پَتہٕ آو عیسیٰ مسیح کانٹَن ہُند تاج تہٕ واگن پوشہٕ لٲگِتھ برونہہ کُن۔ تہٕ {پیلاطس} چُھ تِمن ونان زِ وُچھو انسان!\n6.\\tییلہ سردار پادٕرۍ تہٕ افسرو أمِس وُچھ، تِمو دِژ کرٛٮ۪کہٕ دِتھ وَنُن زِ أمِس کٔرِو صلیب دِنہٕ۔ پیلاطس چُھ تِمن ونان زِ تم رٔٹِو أمِس تہٕ صلیب دِیُن، کیازِ مےٚ چُھنہٕ أمِس مَنٛز کانٛہہ تہِ عیب میلان۔\n7.\\tیہودیو دیُت أمِس جواب، اسہِ چُھ اکھ قانون، تہٕ سانہِ قانونہٕ مطٲبق گژھہِ تس مرُن، کیازِ تٔمۍ بنوو پانس خدایہ سُند نیٚچُو۔\n8. ییلہ پیلاطس یہ کتھ بوز، سہ گوٚو زیادٕ کھوژان۔\n9.\\tتہٕ گۆو دُبارٕ فیصلہٕ کِس ہالس مَنٛز، تہٕ وَنُن عیسیٰ مسیحس کتہِ چھُو؟ مگر حضرت عیسیٰ علیہ السلام دیت نہ تس کانہہ جواب۔\n10. تیلہِ چُھہ پیلاطس أمِس وَنُن، کیا ژٕ چُھکھ نہٕ میانہِ سٍتـ̡ کتھ کٔرِتھ؟ کیا ژیہ چھے نہٕ پتاہ زِ میہ چُھہ ژے مصلوب کرنُک طاقت، تہٕ ژے یلہٕ تراونُک اختیار چُھ؟\n11.\\tعیسیٰ مسیحن دیُت جواب، تێہہ ہیوٚک نہٕ میانہِ خلاف کانہہ طاقت ٲسِتھ، مگر یُس ژے ہیرِ پیٹھٕ دِنہٕ آمُت اوس، تێلہِ چُھہ یُس میہ پانس تام واتناوُن چُھ، سُہ چُھ بۆڈ گۅناہ۔\n12. تہٕ اَمہِ پتہٕ کٔر پیلاطس أمِس یلہٕ تراونٕچ کوٗشش، مگر یہودی دِژ کرٛٮ۪کھ دِتھ زِ اگر ژے أمِس نفرس تراوُن، تہٕ تُہۍ چُھنہٕ قیصر سُند یار، یُس تہٕ یُس پانس بادشاہ بناوان چُھ، سُہ چُھ قیصرس خلاف کتھ کران۔\n13.\\tییلہ پیلاطس یہ کلام بوٗز، سُہ أنۍ عیسیٰ مسیح برونہہ کُن، تہٕ بیوٹھ فیصلہٕ چہ کرسی پیٹھ یتھ فٹ پاتھ ونان چھِ، مگر عبرانی زبانہِ منز گبتھا۔\n14.\\tتہٕ یہِ اوس فسح ہٕنز تیٲری تہٕ شیمہِ گھنٹہِ ہٕندِس وقتس منز: تہٕ سُہ چُھ یہودین ونان زِ وُچھو پنُن بادشاہ!\n15.\\tمگر تِمو دِژ کرٛٮ۪کھ دِژ، ژٔلِتھ ژٔلِتھ کٔرِو أمِس صلیب دِنہٕ۔ پیلاطس چُھ تِمن ونان زِ بہٕ کٔرٕ تُہند بادشاہ مصلوب؟ بٔڈۍ پادٕرۍ دِیُت جواب، اسہِ چُھ نہٕ قیصر سٕندِ علاوٕ کانہہ بادشاہ۔\n16. تێمہِ پَتہٕ دِژ سُہ تِمن تام صلیب دِنہٕ خٲطرٕ۔ تہٕ تِمو نیو عیسیٰ مسیح تہٕ نِش نِش نِنہٕ۔\n17. تہٕ سُہ چُھ صلیب ہٮ۪تھ أکِس جایہِ کُن درٛاو یَتھ کَلہٕ کھورِ ہٕنز جاے ونان چھِ، یَتھ عبرٲنی گولگوتھا ونان چھِ:\n18. یێلہِ تِمو أمِس مصلوب کٔرِتھ، تہٕ باقٕے زٕ أمِس سٍتۍ، أکِس طرفہٕ تہٕ عیسیٰ ہس منز۔\n19. تہٕ پیلاطس لیوکھ اکھ عنوان، تہٕ تھووُن صلیبس پیٹھ۔ تہٕ تحریر اوس عیسیٰ مسیح ناصرت، یہودین ہند بادشاہ۔\n20.\\tاتھ عنوانس منز اوس واریاہ یہودی پٔرِتھ: تکیازِ یێلہِ عیسیٰ مسیح مصلوب اوس کرنہٕ آمُت سُہ اوس شہرس نزدیک: تہٕ یہِ اوس عبرانی، {تہ} یونانی، {تہٕ} لاطینیس مَنٛز لیکھنہٕ آمُت۔\n21.\\tاَمہِ پَتہٕ ووٚن یہودین ہٕندِس بٔڈۍ پادٕرین زِ پیلاطس تہٕ لیکھِو نہٕ یہودین ہُند بادشاہ۔ مگر تٔمۍ ووٚن، بہٕ چُھس یہودین ہُند بادشاہ۔\n22.\\tپیلاطس دیت جواب، یُس میہ لیوکھمُت چُھ، سُہ چُھس لیوکھمُت۔\n23. پَتہٕ سپاہیو ییلہ تِمو عیسیٰ مسیحس مصلوب کٔرِتھ، تٔمۍ سٕندِ پلو رٔٹِتھ تہٕ بنٲوِکھ ژور حصہٕ، پرٮ۪تھ سپاہِس اکھ حصہٕ۔ تہٕ {أمۍ سُند} کوٹ تہِ: وۅنۍ اوس کوٹ سیون ورٲے ، ہیرِ پیٹھٕ ووُنُن۔ {ووون: یا، وون}\n24.\\tتِمو ووٚن پانہٕ پانہٕ پانہٕ، أسۍ کرو نہٕ یہ پھٔٹِتھ، بلکہ تراوُن اتھ خٲطرٕ قرعہٕ، یُس کُس آسہِ، یُس صحیفہ پورٕ سپدِ، یُس ونان چھُ، تِمو کٔر میون پوشاک پانس منز، تہٕ میانہِ پوشاک خٲطرٕ کٔرِکھ تِمو قرعہٕ۔ تَمہِ کِنۍ کٔر فوجین یِم چیٖز۔\n25.\\tوۅنۍ ٲس عیسیٰ مسیح سٕنزِ موج تہٕ ماجہ ہٕنزِ بینہِ کلیوفاس سٕنزِ بینہِ تہٕ مریم مگدلینی سٕندِس صلیب سٍتـ̡ کھڑا۔ {کلیوفاس: یا، کلوپاس}\n26. یێلہِ حضرت عیسیٰ علیہ السلام وُچھ پننہِ ماجہ تہٕ شٲگِرِس سٍتـ̡ یُس أمِس محبت کران اوس، سُہ چُھ پننہِ ماجہِ وُچھمُت، زنانہٕ، وُچھِو پنُن نیچو!\n27.\\tاَمہِ پَتہٕ چُھ سُہ شٲگِرِس ونان زِ وُچھِو پنٕنۍ موج! تہٕ تمہِ ساعتہ نِیہِ سۅ شٲگِر سۅ پننِس گرس منز۔\n28.\\tاَمہِ پَتہٕ چُھہ عیسیٰ علیہ السلام یہ زانان زِ سورے چیز چُھہ وۅنۍ مُکمل سپدمُت، یُتھ صحیفہ پورٕ سپدِ، بہٕ چُھس ترش۔\n29.\\tوۅنۍ آو اَکھ بانہٕ بٔرِتھ سرکہٕ سٍتـ̡ بٔرِتھ تہٕ تھووُن سِرکہٕ سٍتـ̡ تہٕ تھووُن سٍتـ̡\n30. یێلہِ عیسیٰ مسیح سِرکہٕ مِلیوٚو، تٔمۍ ووٚن مُکمل تہٕ تٔمۍ ترووُن کلہٕ تہٕ ترووُن بھوت۔\n31.\\tیہودی کٔر تِکیازِ یہِ ٲس تیٲری زِ سبت دۅہہٕ گژھِ نہٕ لاشہٕ سلیبس پیٹھ روزُن، (تکیازِ سبت دۅہ اوس اکھ تھوٚد دۅہ)، پیلاطس کٔر التجا زِ تِہٕنزِ زنگہٕ گژھن پھُٹنہٕ، تہٕ یِم یِن نِنہٕ۔\n32.\\tپتہٕ آو سپاہ تہٕ لٔگِتھ گۅڈنِچہِ زنگہٕ تہٕ بییِس سٕنزِ زنگہٕ یُس أمِس سٍتـ̡ مصلوب کرنہٕ آو۔\n33. مگر ییلہ تم عیسیٰ مسیحس نِش وٲتۍ، تہٕ وُچھکھ زِ سُہ چُھ گوڈٕ موٗدمُت، تِمو کٔر نہٕ تٔمۍ سٕنزٕ زنگہٕ پھٕٹراوٕن:\n34.\\tمگر أکۍ سپاہی ژاو نیزٕ ہیتھ أمِس اندۍ پکھۍ، تہٕ فوراً دراو تتہِ خوُن تہٕ آب۔\n35.\\tتہٕ یٔمۍ سُہ وُچھمُت تہٕ تٔمۍ سُند ریکارڈ چُھ صحیح، تہٕ سُہ چُھ زانان زِ سُہ چُھ پٔز کَران، یُتھ تُہۍ پٔزۍ پٲٹھۍ۔\n36.\\tیِم کامہِ آیہ کرنہٕ، یُتھ صحیفہٕ پورٕ سپدُن، تٔمۍ سٕنز اکھ أڈجہ گژھہِ نہٕ پھُٹنہٕ۔\n37.\\tبییہِ چھہ بیاکھ صحیفہ ونان زِ تم گژھن تس وچھان یُس تمو ژیر کٔرۍ۔\n38.\\tتہٕ امہِ پتہٕ یوسف، یُس عیسیٰ سُند شٲگِر اوس، مگر یہودی سٕندِ خوفہٕ سٍتـ̡ ژوٗرِ پٲٹھۍ، پیلاطس کٔر عیسیٰ سُند لاش نِنٕچ التجا تہٕ پیلاطس دِژ أمِس رخصت۔ سُہ آو تہٕ نِیوُن عیسیٰ سُند لاش۔\n39.\\tتہِ آو نیکوڈیمس تہِ، یُس گۅڈنچہ لٹہِ رٲژ عیسیٰ ہس نِش آو، تہٕ ہتھ پاؤنڈ وزنُک مرکب تہٕ مرُک مرکب أنِتھ۔\n40. پَتہٕ تِمو نِش عیسیٰ سٕنز لاش تہٕ مَسالہٕ سٍتـ̡ لٔگِتھ دِنہٕ۔\n41.\\tوۅنۍ ییتہِ سُہ صلیب دِنہٕ آمُت اوس، تتہِ اوس اکھ باغ۔ تہٕ باغس منٛز اکھ نوٚو قبر، یتھ منٛز نہٕ وٕنیُک تام انسان اوس نہٕ تراونہٕ آمت۔\n42.\\tتێلہِ اوس عیسیٰ علیہ السلام یہودین ہٕنزِ تیاری سٍتـ̡ {دۅہ} دِنہٕ سٍتـ̡ دِنہٕ آمُت۔ تکیازِ قبر اوس نزدیک۔","1. ہفتُک گۄڈنیُک {دۅہ} چُھ مریم مگدلینی سُلی یِوان، ییلہ وُنہِ تہِ انہِ گوٚٹ اوس، قبرس کُن وُچھان تہٕ قبرٕ منزٕ کنہِ کُن کُن وُچھان۔\n2. پَتہٕ چھے سُہ ژلان تہٕ شمعون پطرس نِش تہٕ بیٚیِس شٲگِرس نِش یُس عیسیٰ مسیح محبت کران اوس، تہٕ تِمن وَنُن چُھہ زِ تِمو چُھ خداوند قبرٕ منزٕ نِش نِمُت، تہٕ اسہِ چُھنہٕ پتاہ زِ تِمو کتہِ چُھ سُہ ترٛٲومُت۔\n3.\\tپطرس دراو تہٕ سُہ بیٛاکھ شٲگِر، تہٕ آو قبرس کُن۔\n4.\\tتێلہِ ژوٚل تِم دۅشوے اِکہٕ وٹہٕ: تہٕ بیٛاکھ شٲگِر ژوٚل پطرس پٲٹھۍ، تہٕ ووت گۅڈنچہ لٹہِ قبرس کُن۔\n5.\\tتہ وُچھن بۅن کُن تہ وُچھتھ وُچھن کُنہِ کُنہِ ک توتہِ گوٚو نہٕ سُہ اندر۔\n6. پَتہٕ چُھ شمعون پطرس أمِس پَتہٕ یِوان، تہٕ ژاو قبرس منز، تہٕ وُچھُن کُنہِ کُنہِ کُنہِ پَلَس پٔرِتھ،\n7. تہٕ رومال یُس أمۍ سٕندِس کلس متعلق اوس، یُس نہٕ کُنہِ جایہِ ؤلِتھ اوس۔\n8.\\tتمہ پتہ گۆو سہ بیاکھ شٲگِر تہِ، یُس گۅڈٕ قبرس پیٹھ آو، تہٕ تٔمۍ وُچھ تہٕ پژھ۔\n9.\\tتکیازِ وُنیُک تام اوس نہٕ تِمن صحیفہٕ پتاہ زِ سُہ گژھہِ مرنہٕ منزٕ دُبارٕ زندٕ روزُن۔\n10. پَتہٕ گٔیہِ شٲگِر دُبارٕ پننِس گَرَس کُن۔\n11.\\tمگر مریم گٔیہِ قبرس پیٹھ وُنُن وُن، تہٕ وُچھن قبرس کُن نظر،\n12.\\tتہٕ چُھ زٕ فرشتہ سفید بِہتھ وُچھان، اکھ کلہٕ پیٹھ، تہٕ بیٛاکھ قدمن پیٹھ، یَتھ منز عیسیٰ سُند لاش لوٚگمُت اوس۔\n13. تہٕ تِم چھِ أمِس ونان زِ زنانہٕ، ژٕ کیازِ چُھکھ روُن؟ سُہ چُھ تِمن ونان زِ تِمو چُھ میون رب نِمُت، تہٕ مے چُھنہٕ پتاہ زِ تِمو کتہِ چھُ سُہ ترٛٲومُت۔\n14. تہٕ ییلہ تٔمۍ یِتھٕ پٲٹھۍ ووٚنمُت، سُہ پھیُر پَنُن پان تہٕ وُچھُن عیسیٰ مسیح کھڑا تہٕ یہِ ٲس نہٕ زانان زِ یہِ اوس عیسیٰ مسیح۔\n15. عیسیٰ مسیح چُھ أمِس ونان زِ زنانہٕ، ژٕ کیازِ چُھکھ روُن؟ ژے کُس چھُکھ ژھانڈان؟ سۅ چھے أمِس باغبان مانان تہٕ وَنُن زِ جناب، اگر ژیہ أمِس اَتہِ زٲومُت چھُو، مے وَن ژے کتہِ چھُکھ سُہ ترٛٲومُت، تہٕ بہٕ نِنہٕ سُہ نِنہٕ۔\n16. عیسیٰ مسیح چُھ أمِس ونان مریم۔ سۅ کٔر پانس پھیُر، تہ ووٚنن تمس ربونی۔ یُس ونُن چُھ، ماسٹر ۔\n17. عیسیٰ مسیح چُھ أمِس ونان زِ مے کٔرِو نہٕ اتھہٕ۔ تکیازِ بہٕ چُھس نہٕ وُنیُک تام پننِس مٲلس نِش کھسنہٕ آمُت، مگر پننین باین نِش گژھ تہٕ تِمن ونُن، بہٕ چُھس پننِس مٲلس تہٕ چانہِ مٲلس نِش کھسان۔ تہٕ {to} میون خدا، تہٕ تُہند خدا۔\n18.\\tمریم مگدلینی آیہِ تہٕ وونُن مریدن زِ تٔمۍ چُھ خداوند وُچھمُت، تہٕ {یہ} اوس تٔمِس سٍتـ̡ یِم کتھ کٔرمٕژ۔\n19.\\tاَمہ دۅہہ شامُک گۅڈنیُک دۅہہ، ییلہ دروازٕ بند کرنہٕ آمٕتۍ ییتہِ یہودین ہٕندِ خوفہٕ سٍتـ̡ شٲگِر جمع گٔیہِ، حضرت عیسیٰ آو تہٕ درمِیان کھڑا تہٕ تِمن وَنُن تُہٕندِس سٍتـ̡ سلام۔\n20.\\tتہٕ ییلہ تٔمۍ یہِ ووٚن، تٔمۍ ہٲو تِمن پنٕنۍ اتھہٕ تہٕ پنٕنۍ طرف۔ اَمہِ پتہٕ گٔیہِ شٲگِرِ خۅش ییٚلہِ تِمو خداوند وُچھ۔\n21. اَمہِ پَتہٕ ووٚن عیسیٰ مسیحن تِمن دُبارٕ دُبارٕ تِمن سٍتـ̡ اَمن: یِتھٕ پٲٹھـ̡ {میانِہ} مٲلہِ سٍتـ̡ چُھہ سوزمُت، تِتھے پٲٹھـ̡ چُھہ بہٕ تہِ سوزمُت۔\n22. تہٕ ییلہ تٔمۍ یہ ووٚنمُت، تٔمۍ دِژ تِمن پیٹھ شاہ تہٕ تِمن وونُن، روح القدس رٔٹِو:\n23. یٔمۍ سٕندِس گۅناہ تہٕ تُہۍ معاف کٔرِو، سُہ چُھ تِمن نِش معاف کرنہٕ یِوان۔ {تہٕ} یٔمۍ سٕندِس {گۅناہ} سٍتـ̡ چُھہ برقرار تھاوان، سُہ چُھ برقرار تھاونہٕ آمُت۔\n24.\\tمگر تھامس، یُس بہو منزٕ اکھ اوس، یُس ڈیڈیمس ونان اوس، اوس نہٕ عیسیٰ سٕندِ وِزِ تِمن سٍتـ̡ موجود۔\n25.\\tتَمہِ کِنۍ ووٚن باقٕے شٲگِرِو أمِس وُچھمُت، أسۍ چھُ خداوند وُچھمُت۔ مگر تٔمۍ ووٚن تِمن زِ یوٚت تام بہٕ تٔمۍ سٕندِس اتھس منز کیلن ہُند نقوش وُچھِتھ تہٕ پنٕنۍ اوٚنگجہ کیلن ہٕندِس نشانس منز تراوٕ تہٕ پنُن اتھہٕ تٔمۍ سٕندِس اندس منز تراوُن، بہٕ کٔرٕ نہٕ پژھ۔\n26.\\tتہٕ ٲٹھن دۅہن پَتہٕ گٔیہِ تٔمۍ سٕندِ شٲگِرِ تہٕ تھامس تہٕ تِمن سٍتـ̡ آو عیسیٰ مسیح، دروازٕ بند کرنہٕ، تہٕ وونُن ژے سٍتـ̡ امن ۔\n27.\\tاَمہِ پَتہٕ چُھ سُہ تھامسَس وَنُن زِ پَنٕنہِ اوٚنٛگجہِ تام وٲتِتھ تہٕ وُچھِو میٲنۍ اتھہٕ۔ تہٕ پَنُن اَتھٕ واتناوُن، تہٕ دِیُن میٲنِس طرفس مَنٛز، تہٕ کٔرِو نہٕ بے وفایی بلکہ پژھ پٲٹھۍ۔\n28. تہٕ تھامس دیُت جواب تہٕ وونُن تٔمِس خدا۔\n29.\\tعیسیٰ چُھ أمِس ونان تھامس، کیازِ ژے چُھہ مے وُچھمُت، تہٕ توتہِ چُھکھ ایمان تھامُت، تِمو چُھہ بابرکت یِمو نہٕ وُچھمُت چُھ، تہٕ {توتہِ} چُھ ایمان تھامُت۔\n30. تہٕ واریاہ باقٕے نشانہٕ کٔر حضرت عیسیٰ علیہ السلام پٔزۍ پٲٹھۍ، یِم نہٕ اتھ کتابہِ منز لیکھنہٕ آمٕتۍ چھِ:\n31. مگر یِم چِھ لیکھنہٕ آمٕتۍ، یُتھ تہٕ یێلہِ عیسیٰ مسیح چُھ، یُس خدایہِ سُند نیٚچُو۔ تہٕ یہ یقین کٔرِتھ زِ تٔمۍ سٕندِ ناوٕ سٍتۍ ہیکہِ زندگی حٲصل کٔرتھ۔","1. یِمو چیزو پَتہٕ کٔر حضرت عیسیٰ علیہ السلام دُبارٕ طبریا کِس سمندرس مَنٛز شاگردن نِش ظٲہر۔ تہٕ اَتھ دانشمندی پیٹھ ہٲو تٔمۍ {پان}۔\n2.\\tاتہِ ٲسۍ شمعون پطرس تہٕ تھامس یُس ڈیڈیمس ونان اوس، تہٕ گلیلِس مَنٛز کاناہُک نتھانیل، تہٕ زبدی سٕندِ نیچوۍ تہٕ تٔمۍ سٕندِ زٕ شٲگِرۍ۔\n3.\\tشمعون پطرس چھہ تمن ونان زِ بہٕ چُھس گاڈٕ رٹان۔ تِم چھِ أمِس ونان زِ أسۍ تہِ چھِ ژےٚ سٍتۍ نیران۔ تِم گٔیہِ نیبر، تہٕ ژاو فوراً أکِس جہازس منٛز۔ تہٕ تمہ رٲژ رٔٹۍ نہٕ کیٚنٛہہ تہِ۔\n4.\\tمگر ییلہ وُنہِ صُبح ووت، عیسیٰ اوس بٹھس پیٹھ کھڑا مگر شاگردن ٲس نہ خبر زِ یہ اوس عیسیٰ مسیح۔\n5.\\tتێلہِ چُھ عیسیٰ علیہ السلام تِمن ونان زِ بچو، کیا تُہۍ چھوا کانہہ ماز؟ تِمو دِژ أمِس جواب، نہٕ۔ {بچہٕ: یا، سر}\n6. تہٕ تٔمۍ ووٚن تِمَن جہازٕ کِس دٔچھنِس طرفہٕ جال تراوُن، تہٕ تُہۍ لٔبِو۔ تِمو ترٛٲو تَمہِ کِنۍ تہٕ وۄنۍ ہیوٚک نہٕ تِم گاڈَن ہٕنٛدِ بٔڑِس خٲطرٕ کھینِتھ ہیوٚک۔\n7. تَمہِ مۄکھٕ چُھ سُہ شٲگِر یُس عیسیٰ مسیح محبت کران اوس، سُہ چُھ پطرس ونان زِ یہِ چُھ خداوند ۔ وۅنۍ ییلہ شمعون پطرس بوز زِ یہ اوس خداوند، تٔمۍ لوٚگ پنُن گاڈٕ ہٲر سُند کوٹ، (تکیازِ سُہ اوس ننگہٕ،) تہٕ ترووُن پان سمندرس مَنٛز۔\n8.\\tتہٕ باقٕے شٲگِر آیہ أکِس لۄکٹِس جہازس منز۔ (تکیازِ تم ٲسۍ نہ زمینہِ نش دور مگر یہ ٲسۍ زٕ ہتھ کیوبٹ،) گاڈٕ سٍتۍ جالس لٔگتھ۔\n9.\\tییلہ تم زمینس پیٹھ وٲتۍ، تِمو وُچھ تتہِ ژیلہِ ہُند نار، تہٕ گاڈٕ تہٕ روٹی۔\n10. عیسیٰ مسیح چُھ تِمن وَنُن زِ سُہ گاڈ أنِو یُس وُنۍ رٔٹمُت چھُ۔\n11.\\tشمعون پطرس ووت تھوٚد، تہٕ لوٚگ جال بٔڈۍ گاڈٕ سٍتـ̡ بٔرِتھ زمینس کُن، اکھ ہتھ پنژاہ تہٕ ترےٚ: تہٕ سارِنٕے خٲطرٕ ٲسۍ واریاہ زیادٕ، توتہِ اوس نہٕ جال پھُٹمُت۔\n12.\\tعیسیٰ مسیح چُھ تِمن ونان زِ یِمو {تہٕ} کھین۔ تہٕ کانہہ تہِ شٲگِر چھُنہٕ أمِس پرژھنٕچ ہمت کٔرِتھ، تُہۍ کُس چھُو؟ یہ زٲنتھ زِ یہ اوس خدا۔\n13.\\tعیسیٰ چُھ یِوان تہٕ روٹی نِوان تہٕ تِمن تہٕ گاڈٕ دِوان تہٕ یِتھے پٲٹھۍ چُھ گاڈٕ دِوان۔\n14. یہِ چُھ وُنـ̡ تریٚیِمہِ لٹہِ یێمہِ لٹہِ عیسیٰ مسیحن پَنٕنـ̡ پَنٕنـ̡ پَنُن پان ہاونہٕ آمُت، تمہِ پَتہٕ گۆو سُہ مُردٕ پى۪ٹھہٕ زندٕ۔\n15.\\tتێلہِ ییلہ تِمو کھٮ۪وان چُھ، عیسیٰ علیہ السلام چُھہ شمعون پطرس ونان یُس یونس سُند نیچو چُھہ ژے میہ یِمو کھوتہٕ زیادٕ محبت؟ سُہ چُھ أمِس ونان ، آ، خدا۔ ژے چھے پتاہ زِ بہٕ چُھس ژے محبت کران۔ سُہ چُھ أمِس ونان زِ میانین دانٛدن ہُند چارہ دِیُن۔\n16.\\tسُہ چُھہ دوٚیمہِ لٹہِ أمِس دُبارٕ وَنان، شمعن، جونس سُند نیچو، کیا ژٕ چُھہ میہ سٍتـ̡ محبت کران؟ سُہ چُھ أمِس ونان ، آ، خدا۔ ژے چھے پتاہ زِ بہٕ چُھس ژے محبت کران۔ سُہ چُھ أمِس ونان زِ میانہِ دانٛد کھیٚو۔\n17.\\tسُہ چُھ أمِس تریمہِ لٹہِ ونان زِ شمع، جونس سُند نیچو، کیا ژٕ چُھکھ میہ محبت؟ پطرس گوٚو غمگسار تکیازِ تٔمۍ ووٚن تس تریمہِ لٹہِ میہ محبت؟ تہٕ تٔمۍ ووٚن أمِس خدا، ژٕ چُھکھ سارِنٕے چیٖز زانان۔ ژے چھے پتاہ زِ بہٕ چُھس ژے محبت کران۔ عیسیٰ مسیح چُھ أمِس ونان زِ میانہِ دانٛد کھیٚو۔\n18. پٔزۍ پٲٹھۍ، بہٕ چُھس ژے ونان زِ ییلہ ژے جوان ٲس، تہٕ ژے ٲسکھ پنُن پان لٲگِتھ، تہٕ ییتہِ تہِ پکان ٲس، مگر ییلہ تہٕ بُزرگ گژھِو، تہٕ بیاکھ کرِ پان اتھہٕ پھٔہلٲوِتھ، تہٕ تتہِ نِنہٕ ییتہِ نہٕ ژے یژھان چھِو۔\n19.\\tیہ وۆن تٔمۍ کُس موتس سٍتـ̡ خدایہ سُند حمد کرُن۔ تہٕ ییلہ تٔمۍ یہ کتھ کٔر، سُہ چُھ أمِس ونان زِ میانہِ پٲٹھۍ۔\n20. پطرس چُھہ پُرِ پٔرِتھ سُہ شٲگِر وُچھان یٔمِس حضرت عیسیٰ سٕندِس پَتہٕ پٲٹھـ̡ پٲٹھـ̡ پٲٹھـ� یُس تہِ شامس وِزِ پننِس سینس پیٹھ تھپھ کٔرِتھ وونُن، خداوند، کُس چُھ ژےٚ دھوکہٕ دِوان۔\n21.\\tپطرس وُچھِتھ چُھ عیسیٰ مسیحس وُچھِتھ خداوند، تہٕ یہِ انسان کیا کرُن؟\n22.\\tعیسیٰ مسیح چُھ أمِس ونان زِ یێلہِ بہٕ یێلہِ بہٕ یِنـ̡ سُہ روزُن، تێلہِ کیا چُھہ تۅہہِ خٲطرٕ؟ میانہِ پٲٹھۍ۔\n23.\\tاَمہِ پَتہٕ ووت یہِ کتھ زِ سُہ شٲگِر گژھِ نہٕ مَرُن، توتہِ ووٚن نہٕ عیسیٰ علیہ السلام أمِس مَرُن، سُہ گژھِ نہٕ مَرُن۔ مگر، اگر بہٕ یژھان زِ سُہ روزِ بہٕ یِنس تام روزُن، تۅہہ کیا چُھ؟\n24.\\tیہِ چُھ سُہ شٲگِد یُس یِمن چیزن ہٕنز گوٲہی دِوان چُھ، تہٕ یِم کتھٕ لیوکھمٕژ چھِ، تہٕ أسۍ چھِ زانان زِ تٔمۍ سٕنز گوٲہی چھے صحیح۔\n25.\\tتہِ چھہ واریاہ چیز یُس حضرت عیسیٰ علیہ السلام کٔرۍ، یُس پریتھ کانہہ لیکھنہ یُن، میانہِ خیالہ چھہ زِ دنیاہس منز تہِ ہیکہِ نہ تم کتابہ لیکھنہ یِن۔ آمین۔"];
